window.QDATA = {"chapters":{"1":{"title":"Computer Networks and the Internet","deck":"Chapter_1_v8.1 - Tagged.pdf","slides":70},"2":{"title":"Application Layer","deck":"Chapter_2_v8.1 - Tagged.pdf","slides":58},"3":{"title":"Transport Layer","deck":"Chapter_3_v8.0.pptx","slides":108}},"sources":{"M26":{"label":"Midterm — 2nd Term 2026 (latest)","file":"exams/mid_2026_term2.pdf","id":"M26"},"MA":{"label":"Midterm — paper A (graded student copy)","file":"exams/past_papers.pdf (pages 1–6)","id":"MA"},"MB":{"label":"Midterm — paper B (photos)","file":"exams/past_papers.pdf (pages 7–9)","id":"MB"},"BQ21":{"label":"Blackboard Quiz — Spring 2021 (1442 H)","file":"exams/past_papers.pdf (pages 10–12)","id":"BQ21"},"MC":{"label":"Midterm — paper C (photos)","file":"exams/past_papers.pdf (pages 13–19)","id":"MC"},"BB1":{"label":"Blackboard Quiz — Chapter 1 (screenshot)","file":"exams/past_papers.pdf (page 20)","id":"BB1"},"FA":{"label":"Final — paper A (photos)","file":"exams/past_papers.pdf (pages 26–35, 265–284)","id":"FA"},"FB":{"label":"Final — paper B (photos)","file":"exams/past_papers.pdf (pages 42–43)","id":"FB"},"BB2":{"label":"Blackboard Quiz — Chapter 1 (screenshots)","file":"exams/past_papers.pdf (pages 54–59)","id":"BB2"},"Q1R":{"label":"Quiz #1 — review screenshots","file":"exams/past_papers.pdf (pages 64–69)","id":"Q1R"},"MD":{"label":"Midterm — paper D (photos)","file":"exams/past_papers.pdf (pages 70–71)","id":"MD"},"Q125":{"label":"Quiz #1 — 1st Semester 2025","file":"exams/past_papers.pdf (pages 72–73)","id":"Q125"},"FC":{"label":"Final — model answer (paper C)","file":"exams/past_papers.pdf (pages 50–53)","id":"FC"},"BB3":{"label":"Blackboard Quiz — Chapters 1–2 (screenshots)","file":"exams/past_papers.pdf (pages 74–93)","id":"BB3"},"ME":{"label":"Midterm — paper E (graded copy)","file":"exams/past_papers.pdf (pages 94–101)","id":"ME"},"MF":{"label":"Midterm — paper F (photos)","file":"exams/past_papers.pdf (pages 102–105)","id":"MF"},"MG":{"label":"Midterm — paper G (screen photos)","file":"exams/past_papers.pdf (pages 106–114)","id":"MG"},"MH":{"label":"Midterm — paper H (graded, with key)","file":"exams/past_papers.pdf (pages 115–120)","id":"MH"},"M23":{"label":"Midterm (Makeup) — 1st Semester 2023 (31 Oct 2023)","file":"exams/past_papers.pdf (pages 121–125)","id":"M23"},"M23J":{"label":"Midterm 1 (Ch 1–2) — January 2023","file":"exams/past_papers.pdf (pages 126–129; model answer pages 135–139)","id":"M23J"},"M22S":{"label":"Midterm — Summer 2021/2022 (model answers, 28 Jul 2022)","file":"exams/past_papers.pdf (pages 130–134)","id":"M22S"},"MI":{"label":"Midterm — paper I (graded key)","file":"exams/past_papers.pdf (pages 140–145)","id":"MI"},"MJ":{"label":"Midterm — Transport layer (graded key)","file":"exams/past_papers.pdf (pages 146–150)","id":"MJ"},"MK":{"label":"Midterm — paper K (photos)","file":"exams/past_papers.pdf (pages 151–153)","id":"MK"},"FD":{"label":"Final — 1st Semester 2023 (photos)","file":"exams/past_papers.pdf (pages 154–157)","id":"FD"},"F22":{"label":"Final 2022 — students' recalled questions","file":"exams/past_papers.pdf (page 158)","id":"F22"},"FE":{"label":"Final — paper E (photos)","file":"exams/past_papers.pdf (pages 161–167)","id":"FE"},"F14":{"label":"Final — 1st Semester 1435-36 (28 Dec 2014, model answer)","file":"exams/past_papers.pdf (pages 198–206)","id":"F14"},"F13":{"label":"Final — 29 Dec 2013 (model answer)","file":"exams/past_papers.pdf (pages 207–213; copy 214–221)","id":"F13"},"F15":{"label":"Final — 2nd Semester 2015 (17 May 2015, model answer)","file":"exams/past_papers.pdf (pages 222–229)","id":"F15"},"M16":{"label":"Midterm 2 — 1st Semester 1437-38 (14 Dec 2016, model answer)","file":"exams/past_papers.pdf (pages 230–236)","id":"M16"},"M14":{"label":"Midterm II — 13 Apr 2014 (model answer)","file":"exams/past_papers.pdf (pages 250–256)","id":"M14"},"M15":{"label":"Midterm 2 — Spring 2015 (4 May 2015)","file":"exams/past_papers.pdf (pages 257–264)","id":"M15"},"PJ":{"label":"Midterm — key shown on projector (photos)","file":"exams/past_papers.pdf (pages 237–243)","id":"PJ"},"ML":{"label":"Midterm — paper L (graded photos)","file":"exams/past_papers.pdf (pages 244–247)","id":"ML"},"QZ":{"label":"Quiz — Transport layer (UDP, rdt, GBN/SR)","file":"exams/past_papers.pdf (pages 248–249)","id":"QZ"},"FF":{"label":"Final — 1st Semester 2023 paper F (photos)","file":"exams/past_papers.pdf (pages 272–284)","id":"FF"}},"questions":[{"id":"M26-1-1","ch":1,"sl":"3, 12","tp":"Hosts / end systems","t":"mcq","q":"Which of the following network devices is considered a host?","o":["Router","Switch","Printer","Wi-Fi Access point"],"a":2,"e":"Slides 3 and 12: hosts = end systems that run network apps at the network's edge (clients and servers). A networked printer is an end system. Routers, switches and access points are packet switches / network infrastructure, not hosts.","from":[{"s":"M26","qn":"Q1 A.1","pg":1}]},{"id":"M26-1-2","ch":1,"sl":"31","tp":"FDM","t":"mcq","q":"In FDM, multiple channels are transmitted by?","o":["Sharing time slots.","Sending packets sequentially.","Using different frequency bands simultaneously.","Using different routers."],"a":2,"e":"Slide 31 (Circuit switching: FDM and TDM): in FDM the optical/electromagnetic frequencies are divided into narrow frequency bands; each call is given its own band and can transmit at the max rate of that narrow band <i>at the same time</i> as the others. Sharing time slots is TDM.","from":[{"s":"M26","qn":"Q1 A.2","pg":1}]},{"id":"M26-1-3","ch":1,"sl":"30","tp":"Circuit switching","t":"mcq","q":"Circuit switching provides:","o":["Guaranteed performance.","Shared resources.","Packet loss.","All of the above are correct."],"a":0,"e":"Slide 30: in circuit switching, end-end resources are allocated to and reserved for the call — dedicated resources, no sharing, circuit-like (guaranteed) performance. Resources are not shared and there is no queueing loss.","from":[{"s":"M26","qn":"Q1 A.3","pg":1}]},{"id":"M26-1-4","ch":1,"sl":"61","tp":"Protocol stack — link layer","t":"mcq","q":"Which layer of the TCP/IP stack is responsible for data transfer between neighboring network elements (directly connected nodes)?","o":["Application layer.","Transport layer.","Network layer","Link layer.","Physical Layer"],"a":3,"e":"Slide 61 (Layered Internet protocol stack): <b>link</b> layer = data transfer between neighboring network elements (Ethernet, 802.11 WiFi, PPP). Network = routing datagrams source to destination; transport = process-to-process; physical = bits on the wire.","from":[{"s":"M26","qn":"Q1 A.4","pg":1}]},{"id":"M26-1-5","ch":1,"sl":"62–65","tp":"Encapsulation names","t":"mcq","q":"Which of the following terms refers to a chunk of data with a header at the Network layer?","o":["Message","Segment","Datagram","Frame","packet"],"a":2,"e":"Slides 62–65 (Services, Layering and Encapsulation): application = <b>message</b> M; transport adds H<sub>t</sub> → <b>segment</b>; network adds H<sub>n</sub> → <b>datagram</b>; link adds H<sub>l</sub> → <b>frame</b>.","from":[{"s":"M26","qn":"Q1 A.5","pg":1},{"s":"MC","qn":"Q1 A.6","pg":15},{"s":"FA","qn":"Q1 A.15","pg":30}]},{"id":"M26-1-B","ch":1,"sl":"7","tp":"Define protocol","t":"short","q":"Define the <b>Protocol</b> in the context of computer networks.","a":"A protocol defines the <b>format</b> and the <b>order of messages</b> sent and received among network entities, and the <b>actions taken</b> on message transmission and receipt.","e":"Slide 7 (What's a protocol?): network protocols are between computers (devices) rather than humans; all communication activity in the Internet is governed by protocols. The slide's definition is the answer above.","from":[{"s":"M26","qn":"Q1 B","pg":1}]},{"id":"M26-3-A","ch":1,"sl":"27, 45–46, 49, 53–54","tp":"Delay, throughput, utilization, traffic intensity","t":"short","q":"Consider the figure: client — Link 1 — R1 — Link 2 — R2 — Link 3 — server.<div class=\"tbl\"><table class=\"mini\"><tr><th>Link</th><th>Rate</th><th>Length</th></tr><tr><td>Link 1</td><td>100 Mbps</td><td>3 km</td></tr><tr><td>Link 2</td><td>1000 Mbps</td><td>1000 km</td></tr><tr><td>Link 3</td><td>10 Mbps</td><td>2 km</td></tr></table></div>The packet length is <b>500 Megabytes</b>; propagation speed on each link is 3×10<sup>8</sup> m/s.<br>1. What is the transmission delay of link 1?<br>2. Compute the propagation delay at link 1.<br>3. What is the maximum achievable data rate (throughput) the client can send to the server over all three links, in Mbps?<br>4. If the client sends at the maximum achievable rate, what is the utilization of link 3?<br>5. If the client sends at the maximum achievable rate, what is the traffic intensity at router R1?","img":"M26-3-A.jpg","a":"1. d<sub>trans</sub> = L/R = (500×8×10<sup>6</sup> bits)/(100×10<sup>6</sup> bps) = 4×10<sup>9</sup>/10<sup>8</sup> = <b>40 s</b><br>2. d<sub>prop</sub> = d/s = 3000 m / 3×10<sup>8</sup> m/s = <b>10<sup>-5</sup> s = 10 µs</b><br>3. Throughput = min(100, 1000, 10) = <b>10 Mbps</b> (link 3 is the bottleneck)<br>4. Utilization of link 3 = 10/10 = <b>1 (100%)</b><br>5. Traffic intensity at R1 = La/R = 10 Mbps / 1000 Mbps (R1's output link is link 2) = <b>0.01</b>","e":"Chapter 1, slide 27 / 46: transmission delay = L/R; propagation delay = d/s. Slides 53–54 (Throughput): end-end throughput is limited by the bottleneck link, min(R<sub>s</sub>, R<sub>c</sub>, …). Utilization = rate actually used ÷ link capacity. Slide 49 (Packet queueing delay): traffic intensity = La/R, where La is the arrival rate in bits/s and R is the rate of the router's outgoing link. Remember 1 Megabyte = 8×10<sup>6</sup> bits.","from":[{"s":"M26","qn":"Q3 A","pg":4}]},{"id":"Q125-1","ch":1,"sl":"46, 49; ch2 24","tp":"Propagation delay, traffic intensity, persistent RTTs","t":"short","q":"a) Router A and router B are connected by a link with transmission rate 100 Mbps and length 2000 km. The propagation speed is 2.5×10<sup>6</sup> m/s. You send a packet of 200 Kbits from A to B. What is the propagation delay?<br>b) A network has 750 requests per second, each request is 2 KB (2 Kilobytes), and the link capacity is 10 Mbps. What is the traffic intensity (utilization) of the link?<br>c) How many RTTs are needed to download a web page consisting of a base page and 5 objects, if the connection is persistent and without pipelining?","a":"a) d<sub>prop</sub> = d/s = 2000×10<sup>3</sup> / 2.5×10<sup>6</sup> = <b>0.8 s</b> (packet size and rate don't matter).<br>b) La/R = (750 × 2000 bytes × 8)/10×10<sup>6</sup> = 12×10<sup>6</sup>/10×10<sup>6</sup> = <b>1.2</b> (> 1: work arrives faster than it can be serviced, so the queue grows without bound).<br>c) <b>7 RTT</b> = 1 RTT TCP setup + 1 RTT base page + 5 × 1 RTT for the objects (one at a time, since no pipelining).","e":"Chapter 1, slide 46: d<sub>prop</sub> = d/s. Slide 49: traffic intensity La/R; La/R &gt; 1 → average delay infinite. Chapter 2, slide 24: persistent HTTP keeps the connection open so each object needs one RTT (no new TCP setup); without pipelining the client waits for each response before the next request.","from":[{"s":"Q125","qn":"Q1","pg":72}]},{"id":"Q125-2-1","ch":1,"sl":"65–66","tp":"Highest layer per device","t":"short","q":"For each device, determine the highest layer it can work on: Router, Server, Link-layer switch, Smartphone.","a":"Router → <b>Network</b> layer<br>Server → <b>Application</b> layer<br>Link-layer switch → <b>Link</b> layer<br>Smartphone → <b>Application</b> layer","e":"Chapter 1, slides 65–66 (Encapsulation: an end-end view): end systems (hosts like servers and smartphones) implement all five layers; routers implement up to the network layer; switches up to the link layer.","from":[{"s":"Q125","qn":"Q2.1","pg":72}]},{"id":"Q125-2-2","ch":1,"sl":"30, 33, 46, 53","tp":"Match concepts","t":"short","q":"Match each concept with its description:<br>Throughput · Circuit Switching · Packet Switching · Propagation Delay<br>1. Resources (bandwidth, buffers) are reserved end-to-end<br>2. Time for one bit to travel across the physical link<br>3. The average rate at which bits are successfully delivered over a link<br>4. Packets may take different routes, causing variable delay","a":"Throughput → <b>3</b><br>Circuit Switching → <b>1</b><br>Packet Switching → <b>4</b><br>Propagation Delay → <b>2</b>","e":"Slide 53: throughput = rate at which bits are sent from sender to receiver. Slide 30: circuit switching reserves end-end resources. Slides 23, 28, 33: packet switching forwards each packet independently with queueing → variable delay. Slide 46: propagation delay d/s.","from":[{"s":"Q125","qn":"Q2.2","pg":73}]},{"id":"MA-1-1","ch":1,"sl":"3, 5–6","tp":"What is the Internet","t":"mcq","q":"The internet can be viewed as:","o":["A collection of hardware and software components executing internet protocols.","A \"network of networks\".","A collection of billions of computing devices, and packet switches interconnected by links.","Infrastructure that provides services to applications.","All the above."],"a":4,"e":"Chapter 1 gives two views of the Internet. \"Nuts and bolts\" view (slides 3, 5): billions of connected computing devices (hosts) and packet switches interconnected by communication links, a \"network of networks\" of interconnected ISPs, with protocols everywhere controlling sending and receiving of messages. Services view (slide 6): infrastructure that provides services to applications. Every option is one of these descriptions.","from":[{"s":"MA","qn":"Q1.1","pg":1}]},{"id":"MA-1-2","ch":1,"sl":"24–26","tp":"Routing vs forwarding","t":"mcq","q":"What is the difference between routing and forwarding?","o":["Routing determines the entire path, while forwarding moves packets to the next node.","Forwarding calculates the best path, while routing sends data.","Routing is used in wired networks, while forwarding is used in wireless networks.","There is no difference between the two."],"a":0,"e":"Slide 24 (Two key network-core functions): <b>forwarding</b> is a <i>local</i> action — move arriving packets from the router's input link to the appropriate output link (using the local forwarding table). <b>Routing</b> is a <i>global</i> action — determine the source-destination paths taken by packets (routing algorithms).","from":[{"s":"MA","qn":"Q1.2","pg":1},{"s":"MC","qn":"Q1 A.2","pg":15}]},{"id":"MA-1-3","ch":1,"sl":"7","tp":"What is a protocol","t":"mcq","q":"What is a protocol in networking?","o":["A device that connects different networks together.","A set of rules governing data communication.","A software application for managing network traffic.","A hardware device for routing packets."],"a":1,"e":"Slide 7: protocols define the format and order of messages sent and received among network entities, and the actions taken on transmission/receipt — i.e. the rules that govern communication. A protocol is not a device or an application.","from":[{"s":"MA","qn":"Q1.3","pg":1}]},{"id":"MA-1-4","ch":1,"sl":"16","tp":"DSL access","t":"mcq","q":"The digital subscriber line DSL is a technology to get access to the network using:","o":["The cable-based television line.","The existing telephone line.","The wireless networks including WiFi, 4G, and 5G.","All the above."],"a":1,"e":"Slide 16 (Access networks: DSL): DSL uses the <b>existing telephone line</b> to the central office DSLAM; data goes to the Internet and voice to the telephone net. Cable-based access (HFC) is slides 14–15; wireless access is slide 18.","from":[{"s":"MA","qn":"Q1.4","pg":1}]},{"id":"MA-1-5","ch":1,"sl":"3, 18","tp":"Physical media — terrestrial microwave","t":"mcq","q":"Which one of the following transmission media connect wireless sender and receiver in a line-of-sight point to point:","o":["Twisted pair","Fiber optical cables","Satellite","Bluetooth.","Terrestrial Microwave"],"a":4,"e":"Twisted pair and fiber are guided (wired) media. Among the wireless (radio) media, <b>terrestrial microwave</b> channels are point-to-point, line-of-sight links. Satellite links go through a satellite in orbit; Bluetooth is a short-range wireless technology. Your slides only list links briefly (slide 3: fiber, copper, radio, satellite; slide 18: wireless access), so this detail comes from the textbook section on physical media.","nb":"Detail from textbook §1.2 (physical media); slides only list link types.","from":[{"s":"MA","qn":"Q1.5","pg":1}]},{"id":"MA-1-6","ch":1,"sl":"61","tp":"Transport layer role","t":"mcq","q":"Which of the following Internet architecture layers is responsible for end-to-end logical communication between processes?","o":["Application Layer","Transport Layer","Network Layer","Data Link Layer"],"a":1,"e":"Slide 61: <b>transport</b> = process-process data transfer (TCP, UDP). Chapter 3, slide 4 says the same: transport protocols provide logical communication between application processes running on different hosts.","from":[{"s":"MA","qn":"Q1.6","pg":1}]},{"id":"MA-1-7","ch":1,"sl":"32–33","tp":"Packet vs circuit switching","t":"mcq","q":"What is an advantage of packet-switching over circuit switching?","o":["It is more efficient for real-time voice communication.","It allows multiple users to share the same network bandwidth.","It requires less error-checking mechanisms.","It ensures guaranteed delivery without retransmission."],"a":1,"e":"Slides 32–33: packet switching allows <b>more users to use the network</b> (35 users vs 10 in the 1 Gb/s example) because resources are shared on demand; it is great for bursty data. Its downsides are excessive congestion, delay and loss — guaranteed behavior is a circuit-switching property.","from":[{"s":"MA","qn":"Q1.7","pg":1},{"s":"MC","qn":"Q1 A.3","pg":15}]},{"id":"MA-1-8","ch":1,"sl":"31","tp":"FDM vs TDM","t":"mcq","q":"What is the primary difference between FDM and TDM?","o":["FDM allocates frequency bands to users, while TDM allocates time slots.","FDM is used in digital communication, while TDM is used in analogue communication.","TDM allows simultaneous data transmission, while FDM does not.","TDM is more efficient than FDM in all cases.","All of the above"],"a":0,"e":"Slide 31: FDM divides frequencies into narrow bands, each call gets its own band (all transmit simultaneously). TDM divides time into slots, each call gets periodic slot(s) and transmits at the full (wider) band's rate only during its slots.","from":[{"s":"MA","qn":"Q1.8","pg":2}]},{"id":"MA-1-9","ch":1,"sl":"61","tp":"Network layer role","t":"mcq","q":"Which of the following layers in TCP/IP stack model is used for establishing a logical communication between hosts, and it also used for routing the datagrams from source host to destination hosts?","o":["Application layer.","Transport layer.","Network layer.","Link layer.","Physical layer."],"a":2,"e":"Slide 61: <b>network</b> = routing of datagrams from source to destination (IP, routing protocols). Chapter 3, slide 6: network layer = logical communication between <i>hosts</i>; transport layer = logical communication between <i>processes</i>.","from":[{"s":"MA","qn":"Q1.9","pg":2},{"s":"MC","qn":"Q1 A.4","pg":15}]},{"id":"MA-1-10","ch":1,"sl":"65–66","tp":"Which devices implement which layers","t":"mcq","q":"Which of the following network devices can perform all functions in the layers of the internet model; it runs the functions of application layer, transport layer, network layer, link layer, and physical layer?","o":["Router","Switch","Hub","Host","Firewall"],"a":3,"e":"Slides 65–66 (Encapsulation: an end-end view): the source and destination <b>hosts</b> implement all five layers; the <b>switch</b> implements only link + physical; the <b>router</b> implements network + link + physical.","from":[{"s":"MA","qn":"Q1.10","pg":2}]},{"id":"MA-1-13","ch":1,"sl":"62–65","tp":"Encapsulation names — frame","t":"mcq","q":"A chunk of data with the header created at the link layer is called:","o":["Message","Segment","Frame","Datagram"],"a":2,"e":"Slides 62–65: message (application) → segment (transport, H<sub>t</sub>) → datagram (network, H<sub>n</sub>) → <b>frame</b> (link, H<sub>l</sub>).","from":[{"s":"MA","qn":"Q1.13","pg":2},{"s":"MG","qn":"Q1 Part2.5","pg":112},{"s":"M22S","qn":"Q1.14","pg":132}]},{"id":"MA-3-A","ch":1,"sl":"27, 46, 49, 53–54","tp":"Delay, throughput, utilization, traffic intensity","t":"short","q":"A client sends packets over Link 1 → R1 → Link 2 → R2 → Link 3 to a server.<div class=\"tbl\"><table class=\"mini\"><tr><th>Link</th><th>Rate</th><th>Length</th></tr><tr><td>Link 1</td><td>10 Mbps</td><td>3 km</td></tr><tr><td>Link 2</td><td>100 Mbps</td><td>5000 km</td></tr><tr><td>Link 3</td><td>1000 Mbps</td><td>2 km</td></tr></table></div>Packet length L = <b>24000 bytes</b>; propagation speed = 2.5×10<sup>8</sup> m/s.<br>1. Compute the transmission delay at link 1.<br>2. Compute the propagation delay at link 2.<br>3. What is the maximum achievable data rate (in Mbps) from client to server over all three links?<br>4. If the client sends at that rate, what is the utilization of link 3?<br>5. If the client sends at that rate, what is the traffic intensity at router R1?","img":"MA-3-A.jpg","a":"1. L/R = 24000×8 / 10×10<sup>6</sup> = 192000/10<sup>7</sup> = <b>0.0192 s (19.2 ms)</b><br>2. d/s = 5000×10<sup>3</sup> / 2.5×10<sup>8</sup> = <b>0.02 s (20 ms)</b><br>3. min(10, 100, 1000) = <b>10 Mbps</b><br>4. 10 / 1000 = <b>0.01 (1%)</b><br>5. La/R at R1 = 10 Mbps / 100 Mbps (R1's output link is link 2) = <b>0.1</b>","e":"Chapter 1: transmission delay L/R (slides 27, 46), propagation delay d/s (slide 46), end-end throughput = rate of the bottleneck link (slides 53–54), traffic intensity La/R (slide 49). Utilization of a link = the rate actually sent over it divided by its capacity.","from":[{"s":"MA","qn":"Q3 A","pg":5}]},{"id":"MB-1-1","ch":1,"sl":"32–33","tp":"Packet vs circuit switching efficiency","t":"tf","q":"Packet switching, based on resource sharing between all users, is also more efficient than circuit switching in terms of resource utilization.","a":0,"e":"Slides 32–33: sharing link capacity on demand lets packet switching support more users (35 vs 10 in the slide example), so it uses resources more efficiently — <b>True</b>.","from":[{"s":"MB","qn":"Q1 T/F 1","pg":7}]},{"id":"MB-1-2","ch":1,"sl":"24","tp":"Routing vs forwarding","t":"tf","q":"<b>Routing</b> is the local action of moving arriving packets from a router's input link to the appropriate router output link, while <b>forwarding</b> is the global action of determining the source-destination paths taken by packets.","a":1,"e":"Slide 24: it is the reverse — <b>forwarding</b> is the local action (input link → output link) and <b>routing</b> is the global action (determine source-destination paths). <b>False</b>.","from":[{"s":"MB","qn":"Q1 T/F 2","pg":7},{"s":"MG","qn":"Q1 Part1.3","pg":111}]},{"id":"MB-1-3","ch":1,"sl":"3, 18","tp":"Wireless links","t":"tf","q":"Wireless links are the best transmission media in terms of transmission rate and reliability.","a":1,"e":"Wireless links are a shared medium and suffer interference and bit errors (slide 18: shared wireless access network); guided media such as fiber give higher rates and lower error rates. <b>False</b>.","from":[{"s":"MB","qn":"Q1 T/F 3","pg":7}]},{"id":"MB-1-4","ch":1,"sl":"65–66","tp":"Switch layers","t":"tf","q":"In the context of networking model layers, the <i>switches</i> work on the three lower layers.","a":1,"e":"Slide 66 (Encapsulation: an end-end view): a link-layer switch implements only <b>two</b> layers — link and physical. It is the router that implements the three lower layers. <b>False</b>.","from":[{"s":"MB","qn":"Q1 T/F 4","pg":7}]},{"id":"MB-1-5","ch":1,"sl":"61, 69","tp":"Network layer role","t":"tf","q":"The main function of the network layer in the OSI network reference model is process-to-process data transfer.","a":1,"e":"Slide 61: process-process data transfer is the <b>transport</b> layer; the network layer routes datagrams from source to destination (host to host). Slide 69 shows the same layers in the OSI model. <b>False</b>.","from":[{"s":"MB","qn":"Q1 T/F 5","pg":7}]},{"id":"MB-1-7","ch":1,"sl":"61","tp":"Application layer role","t":"tf","q":"The main function of the application layer is to establish an end-to-end connection between applications.","a":1,"e":"Slide 61: the application layer supports network applications (HTTP, IMAP, SMTP, DNS). Setting up end-to-end (process-to-process) connections is the transport layer's job (TCP handshake, Chapter 3 slide 78). <b>False</b>.","from":[{"s":"MB","qn":"Q1 T/F 7","pg":7},{"s":"FD","qn":"Q1 B.2","pg":155},{"s":"FE","qn":"Q1 B.4","pg":161}]},{"id":"MB-1-8","ch":1,"sl":"31","tp":"FDM/TDM in circuit switching","t":"tf","q":"In circuit switching, Frequency Division Multiplexing (FDM) and Time Division Multiplexing (TDM) are two approaches for implementing this technique.","a":0,"e":"Slide 31 (Circuit switching: FDM and TDM). <b>True</b>.","from":[{"s":"MB","qn":"Q1 T/F 8","pg":7},{"s":"MG","qn":"Q1 Part1.5","pg":111}]},{"id":"MB-2-1","ch":1,"sl":"45","tp":"Queueing delay","t":"mcq","q":"What is the packet's delay component that is computed as the time spent waiting in packet buffers for link transmission?","o":["Queueing delay","Propagation delay","Processing delay","Transmission delay"],"a":0,"e":"Slide 45 (Packet delay: four sources): d<sub>queue</sub> = queueing delay — time waiting at the output link for transmission; it depends on the congestion level of the router.","from":[{"s":"MB","qn":"Q2.1","pg":7},{"s":"FA","qn":"Q1 A.1","pg":26}]},{"id":"MB-2-2","ch":1,"sl":"62–65","tp":"Encapsulation","t":"mcq","q":"Which of the definitions below describe what is meant by the term \"encapsulation\"?","o":["Receiving a \"packet\" from the layer below, extracting the payload field, and after some internal actions possibly delivering that payload to an upper layer protocol.","Starting a transport layer timer for a transmitted segment, and then if an ACK segment isn't received before the timeout, placing that segment in a retransmission queue.","Computing the sum of all of the bytes within a packet and placing that value in the packet header field.","Taking data from the layer above, adding header fields appropriate for this layer, and then placing the data in the payload field of the \"packet\" for that layer.","Determining the name of the destination host, translating that name to an IP address and then placing that value in a packet header field."],"a":3,"e":"Slides 62–65 (Services, Layering and Encapsulation): the transport layer encapsulates the application message M with header H<sub>t</sub> to create a segment; the network layer encapsulates the segment with H<sub>n</sub> to create a datagram, and so on. Option A describes decapsulation; C is a checksum; E is DNS.","from":[{"s":"MB","qn":"Q2.2","pg":7},{"s":"MF","qn":"Q1.2","pg":102},{"s":"MG","qn":"Q1 Part2.6","pg":113},{"s":"BB3","qn":"Q5","pg":91}]},{"id":"MB-2-3","ch":1,"sl":"65–66","tp":"Router layers","t":"mcq","q":"Within the TCP/IP model layers, where does a router, functioning as a computer networking device, primarily operate?","o":["The three upper layers","In application layer","The three lower layers","Physical layer"],"a":2,"e":"Slides 65–66: a router implements the <b>network, link and physical</b> layers (the three lower layers). A switch implements link + physical; hosts implement all five.","from":[{"s":"MB","qn":"Q2.3","pg":8}]},{"id":"MB-2-4","ch":1,"sl":"3","tp":"Guided vs unguided media","t":"mcq","q":"Which of this is not a guided media?","o":["Fiber optical cable","Coaxial cable","Wireless LAN","Copper wire"],"a":2,"e":"Guided media: signals propagate in solid media (copper twisted pair, coaxial cable, fiber). Unguided media: signals propagate freely (radio) — <b>wireless LAN</b> is radio. Slide 3 lists the link types (fiber, copper, radio, satellite); the guided/unguided split is in the textbook's physical-media section.","nb":"Detail from textbook §1.2 (physical media); slides only list link types.","from":[{"s":"MB","qn":"Q2.4","pg":8},{"s":"FE","qn":"Q1 A.5","pg":167}]},{"id":"MB-3","ch":1,"sl":"27, 46, 53–54","tp":"Delay & throughput (MCQ set)","t":"short","q":"A client sends packets over Link 1 → Link 2 → Link 3 to the server.<div class=\"tbl\"><table class=\"mini\"><tr><th>Link</th><th>Rate</th><th>Length</th></tr><tr><td>Link 1</td><td>1000 Mbps</td><td>2 km</td></tr><tr><td>Link 2</td><td>10 Mbps</td><td>5000 km</td></tr><tr><td>Link 3</td><td>100 Mbps</td><td>1 km</td></tr></table></div>Packet length = <b>32000 bytes</b>; propagation speed = 3×10<sup>8</sup> m/s.<br>1) Transmission delay at link 1? (A) 0.128 msec (B) 0.032 msec (C) 0.256 msec (D) 32 sec (E) 256 sec<br>2) Propagation delay for link 2? (A) 0.01667 msec (B) 0.01667 sec (C) 0.5 sec (D) 0.5 msec (E) 0.05 msec<br>3) Maximum end-to-end achievable data rate? (A) 1000 (B) 100 (C) 10 (D) 1110 (E) 1 Mbps<br>4) If the client sends at that rate, the utilization U of link 3? U = 1 / 100 / 0.10 / 10 / 1000<br>5) If the total delay for links 1, 2, 3 is 10, 20, 30 msec respectively, what is the end-to-end delay from client to server?","img":"MB-3.jpg","a":"1) <b>C — 0.256 msec</b> (32000×8 = 256000 bits; 256000 / 10<sup>9</sup> = 2.56×10<sup>-4</sup> s)<br>2) <b>B — 0.01667 sec</b> (5×10<sup>6</sup> m / 3×10<sup>8</sup> m/s)<br>3) <b>C — 10 Mbps</b> (bottleneck = link 2)<br>4) <b>U = 0.10</b> (10 Mbps / 100 Mbps)<br>5) End-to-end delay = 10 + 20 + 30 = <b>60 msec</b>","e":"Chapter 1: d<sub>trans</sub> = L/R (slide 27, 46); d<sub>prop</sub> = d/s (slide 46); end-end throughput is set by the bottleneck link (slides 53–54). The end-to-end delay is the sum of the per-link (nodal) delays along the path.","from":[{"s":"MB","qn":"Q3","pg":8}]},{"id":"MC-1-B","ch":1,"sl":"7, 61; ch3 9","tp":"Define protocol + transport protocols","t":"short","q":"Define the <b>Protocol</b> in the context of computer networks. Also, identify two protocols that operate at the transport layer of the TCP/IP model.","a":"<b>Protocol:</b> defines the format and order of messages sent and received among network entities, and the actions taken on message transmission and receipt.<br><b>Transport-layer protocols:</b> <b>TCP</b> and <b>UDP</b>.","e":"Chapter 1, slide 7 gives the definition. Slide 61 (Layered Internet protocol stack): transport = process-process data transfer — TCP, UDP. Chapter 3, slide 9: the two principal Internet transport protocols are TCP and UDP.","from":[{"s":"MC","qn":"Q1 B","pg":14}]},{"id":"MC-1-A1","ch":1,"sl":"23","tp":"Network core device","t":"mcq","q":"Which of these devices is a network core device?","o":["Laptop.","Server.","Switch.","Smartphone."],"a":2,"e":"Chapter 1, slide 23 (The network core): a mesh of interconnected routers / packet switches. Slide 3: packet switches forward packets — routers and <b>switches</b>. Laptops, servers and smartphones are hosts at the network edge (slide 12).","from":[{"s":"MC","qn":"Q1 A.1","pg":15}]},{"id":"MC-1-A5","ch":1,"sl":"45–46","tp":"Components of end-to-end delay","t":"mcq","q":"When a sender wants to send a message to the receiver, the End-to-End delay can include:","o":["Transmission delay.","Propagation delay.","Queuing delay.","All the previous answers are correct."],"a":3,"e":"Chapter 1, slides 45–46: nodal delay d<sub>nodal</sub> = d<sub>proc</sub> + d<sub>queue</sub> + d<sub>trans</sub> + d<sub>prop</sub>; the end-to-end delay is the sum over all hops, so it includes transmission, propagation and queueing (and processing) delays.","from":[{"s":"MC","qn":"Q1 A.5","pg":15}]},{"id":"MC-3-A","ch":1,"sl":"53–55","tp":"Throughput with shared middle link","t":"short","q":"Four different servers are connected to four different clients over four three-hop paths. The four pairs share a common middle hop with capacity <b>R = 400 Mbps</b>. The four links from the servers to the shared link have capacity <b>R<sub>S</sub> = 40 Mbps</b>; each of the four links from the shared middle link to a client has capacity <b>R<sub>C</sub> = 20 Mbps</b>.<br>1. What is the maximum achievable end-end throughput (in Mbps) for each of the four client-to-server pairs, assuming the middle link is fairly shared (divides its rate equally)?<br>2. If the server has a file of 10 Megabytes and sends it at a transmission rate of 40 Mbps, compute the transmission delay.<br>3. If the shared middle link is upgraded to 800 Mbps, will this increase the end-to-end throughput for each pair?<br>4. Provide a solution to increase the network utilization and improve overall performance.","img":"MC-3-A.jpg","a":"1. min(R<sub>S</sub>, R/4, R<sub>C</sub>) = min(40, 100, 20) = <b>20 Mbps</b> (the client links are the bottleneck).<br>2. L/R = (10×8×10<sup>6</sup> bits)/(40×10<sup>6</sup> bps) = <b>2 s</b>.<br>3. <b>No.</b> Each pair would get min(40, 800/4 = 200, 20) = still <b>20 Mbps</b>; the bottleneck is R<sub>C</sub>, not the middle link.<br>4. Upgrade the <b>bottleneck links</b> — the client access links R<sub>C</sub> (e.g. to 40 Mbps gives 40 Mbps per pair). The middle link is only 4×20/400 = 20% utilized, so it can also serve more client-server pairs.","e":"Chapter 1, slides 53–54: the end-end throughput equals the rate of the bottleneck link on the path. Slide 55 (Throughput: network scenario): with 10 connections fairly sharing a backbone link R, the per-connection throughput is min(R<sub>c</sub>, R<sub>s</sub>, R/10); in practice R<sub>c</sub> or R<sub>s</sub> is often the bottleneck. Transmission delay is L/R (slide 27).","from":[{"s":"MC","qn":"Q3 A","pg":18}]},{"id":"ME-1-1","ch":1,"sl":"31","tp":"FDM definition","t":"mcq","q":"______ divides the frequency spectrum of a higher-bandwidth channel into many individual smaller-bandwidth communication channels.","o":["TDM","FDM","RFC","IETF"],"a":1,"e":"Chapter 1, slide 31: FDM — optical, electromagnetic frequencies divided into (narrow) frequency bands; each call allocated its own band. RFC and IETF are Internet standards terms (slide 5).","from":[{"s":"ME","qn":"Q1.1","pg":94}]},{"id":"ME-1-2","ch":1,"sl":"45","tp":"Queueing delay","t":"mcq","q":"Time that a packet waits at the output link for transmission; depends on the congestion level of the router:","o":["Transmission delay","Queueing delay","Nodal processing","Propagation delay"],"a":1,"e":"Chapter 1, slide 45: d<sub>queue</sub>: queueing delay — time waiting at output link for transmission; depends on congestion level of router.","from":[{"s":"ME","qn":"Q1.2","pg":94},{"s":"M23J","qn":"Q1.3","pg":126},{"s":"F22","qn":"Q6","pg":158}]},{"id":"ME-1-3","ch":1,"sl":"53","tp":"Throughput definition","t":"mcq","q":"A rate (bits/time unit) at which bits are being sent from sender to receiver:","o":["End-to-end delay","Transmission delay","Traceroute","Throughput"],"a":3,"e":"Chapter 1, slide 53: throughput — rate (bits/time unit) at which bits are being sent from sender to receiver; instantaneous or average.","from":[{"s":"ME","qn":"Q1.3","pg":94},{"s":"F22","qn":"Q5","pg":158}]},{"id":"ME-1-4","ch":1,"sl":"24","tp":"Forwarding = local action","t":"mcq","q":"A local action: move arriving packets from the router's input link to the appropriate router output link.","o":["Routing","Forwarding","Traceroute","Throughput"],"a":1,"e":"Chapter 1, slide 24: forwarding (aka switching) is a local action; routing is the global action of determining source-destination paths.","from":[{"s":"ME","qn":"Q1.4","pg":94},{"s":"F22","qn":"Q7","pg":158},{"s":"FE","qn":"Q1 A.3","pg":167}]},{"id":"ME-1-7","ch":1,"sl":"5, 10","tp":"ISP meaning","t":"mcq","q":"ISP stands for:","o":["Internet Support Provider","Internet Standard Protocol","Internet Service Provider","Internet Selective Protocol"],"a":2,"e":"Chapter 1, slide 5: Internet = \"network of networks\" — interconnected ISPs (Internet Service Providers). Slides 34–42 describe access ISPs, regional ISPs and global ISPs.","from":[{"s":"ME","qn":"Q1.7","pg":95},{"s":"M23J","qn":"Q1.1","pg":126}]},{"id":"ME-1-9","ch":1,"sl":"12, 65–66","tp":"Hosts implement all layers","t":"mcq","q":"Hosts in the network edge implement ______ layer(s).","o":["Application, and transport","Physical, and data link","Network","All of the above"],"a":3,"e":"Chapter 1, slide 12: hosts (clients and servers) sit at the network edge. Slides 65–66: source and destination hosts implement all five layers — application, transport, network, link and physical.","from":[{"s":"ME","qn":"Q1.9","pg":95}]},{"id":"ME-1-11","ch":1,"sl":"31–32","tp":"FDM bandwidth per user","t":"mcq","q":"15 users are connected into a circuit-switched network. All links have bit rate 30 Mbps and 15 FDM channels. How much bandwidth does each host have?","o":["100 Kbps","2 Mbps","30 Mbps","15 Mbps"],"a":1,"e":"Chapter 1, slide 31: in FDM each call gets its own narrow frequency band = link rate ÷ number of channels → 30 Mbps / 15 = <b>2 Mbps</b>.","from":[{"s":"ME","qn":"Q1.11","pg":95}]},{"id":"ME-4-A","ch":1,"sl":"46","tp":"Delays of link 1","t":"short","q":"Three links: Link 1 = 10 Mbps, 3 km; Link 2 = 100 Mbps, 1000 km; Link 3 = 1000 Mbps, 3 km. Packet length 8000 bits; propagation speed 3×10<sup>8</sup> m/s.<br>1. Transmission delay of link 1?<br>2. Propagation delay of link 1?<br>3. Total delay of link 1?","img":"ME-4-A.jpg","a":"1. L/R = 8000 / 10×10<sup>6</sup> = <b>8×10<sup>-4</sup> s (0.8 ms)</b><br>2. d/s = 3×10<sup>3</sup> / 3×10<sup>8</sup> = <b>10<sup>-5</sup> s (10 µs)</b><br>3. 8×10<sup>-4</sup> + 1×10<sup>-5</sup> = <b>8.1×10<sup>-4</sup> s (0.81 ms)</b>","e":"Chapter 1, slide 46: d<sub>trans</sub> = L/R, d<sub>prop</sub> = d/s; with no queueing/processing given, the delay of a link is d<sub>trans</sub> + d<sub>prop</sub>.","from":[{"s":"ME","qn":"Q4 A","pg":99}]},{"id":"ME-4-B","ch":1,"sl":"53–55","tp":"Shared-link throughput & file time","t":"short","q":"Four servers connect to four clients over three-hop paths sharing a middle hop of <b>R = 200 Mbps</b>. Server links R<sub>S</sub> = <b>30 Mbps</b>; client links R<sub>C</sub> = <b>80 Mbps</b>.<br>1. Maximum achievable end-end throughput for each pair (middle link fairly shared)?<br>2. Which link is the bottleneck for each session?<br>3. If one server sends a file of <b>30 MB</b> to its client, how long will it take?","img":"ME-4-B.jpg","a":"1. min(R<sub>S</sub>, R/4, R<sub>C</sub>) = min(30, 50, 80) = <b>30 Mbps</b><br>2. The server link <b>R<sub>S</sub></b><br>3. Time = file size / throughput = (30×10<sup>6</sup>×8 bits)/(30×10<sup>6</sup> bps) = <b>8 s</b>.","e":"Chapter 1, slides 53–55: the end-end throughput equals the bottleneck link rate (with the shared link divided fairly, R/4). A long file is streamed through the path at the bottleneck rate, so the transfer time ≈ L / throughput. (The graded paper also wrote 3 × 8 = 24 s \"for 3 hops\" — that would only apply if the whole 30 MB were stored and forwarded as one packet over three 30 Mbps links.)","from":[{"s":"ME","qn":"Q4 B","pg":100}]},{"id":"MF-2","ch":1,"sl":"46, 49, 53","tp":"Single link: delays, throughput, packets/s","t":"short","q":"A router transmits packets of length L over one link of rate R to another router. The link is <b>10000 km</b> long, propagation speed 2×10<sup>8</sup> m/s. L = <b>64000 bytes</b>, R = <b>1 Mbps</b>.<br>1) Transmission delay? (A) 0.64 s (B) 0.064 s (C) 0.512 s (D) 512 s (E) 1 s<br>2) Propagation delay? (A) 0.0005 s (B) 0.05 ms (C) 0.05 s (D) 10000 s (E) 10 s<br>3) Maximum achievable throughput of this link? (A) 64000 bps (B) 128000 bps (C) 1 Mbps (D) 512 Mbps<br>4) Maximum number of packets per second that can be transmitted? (A) 64 (B) 7 (C) 16 (D) 2<br>5) Total delay (in msec) to send the packet to the other end of the link?","img":"MF-2.jpg","a":"1) <b>C — 0.512 s</b> (64000×8 = 512000 bits ÷ 10<sup>6</sup> bps)<br>2) <b>C — 0.05 s</b> (10<sup>7</sup> m ÷ 2×10<sup>8</sup> m/s)<br>3) <b>C — 1 Mbps</b> (a single link: throughput = its rate R)<br>4) <b>D — ≈2 packets</b> (10<sup>6</sup>/512000 ≈ 1.95 packets/s)<br>5) 512 + 50 = <b>562 msec</b>","e":"Chapter 1, slide 46: d<sub>trans</sub> = L/R, d<sub>prop</sub> = d/s. Slide 53: the maximum throughput over one link is its transmission rate. Packets per second = R / L. Total delay (no queueing/processing) = d<sub>trans</sub> + d<sub>prop</sub>.","from":[{"s":"MF","qn":"Q2","pg":102}]},{"id":"MG-1-TF1","ch":1,"sl":"16","tp":"DSL uses telephone line","t":"tf","q":"The digital subscriber line DSL is a technology to get access to the network using the cable-based television line.","a":1,"e":"Chapter 1, slide 16: DSL uses the existing <b>telephone line</b> to the central office DSLAM. Cable TV lines are used by cable-based access (HFC, slides 14–15). <b>False</b>.","from":[{"s":"MG","qn":"Q1 Part1.1","pg":111}]},{"id":"MG-1-TF2","ch":1,"sl":"3, 5–7","tp":"Internet as hardware/software running protocols","t":"tf","q":"The Internet can be viewed as a collection of hardware and software components executing protocols that define the format and the order of messages exchanged between two or more communicating entities, as well as the actions taken on the transmission and/or receipt of a message or other event.","a":0,"e":"Chapter 1, slides 3–5 (\"nuts and bolts\" view: devices, links, packet switches, protocols everywhere) and slide 7 (definition of a protocol). <b>True</b>.","from":[{"s":"MG","qn":"Q1 Part1.2","pg":111}]},{"id":"MG-1-TF4","ch":1,"sl":"23, 30","tp":"Packet switching reserves nothing","t":"tf","q":"In packet switching, the resources have to be reserved for a call from source to destination before data is transmitted.","a":1,"e":"Chapter 1, slide 30: reserving end-end resources for a call is <b>circuit</b> switching. Packet switching (slides 23, 33) shares resources on demand with no call setup. <b>False</b>.","from":[{"s":"MG","qn":"Q1 Part1.4","pg":111}]},{"id":"MG-1-TF6","ch":1,"sl":"5, 34–42","tp":"\"Network of networks\" meaning","t":"tf","q":"When we say that the Internet is a \"network of networks\" we mean the Internet is the biggest and fastest network ever built.","a":1,"e":"Chapter 1, slide 5: \"network of networks\" means the Internet is made of <b>interconnected ISPs</b>. Slides 34–42 show how access ISPs, regional ISPs, global ISPs, IXPs and content-provider networks connect together. It says nothing about size or speed. <b>False</b>.","from":[{"s":"MG","qn":"Q1 Part1.6","pg":111}]},{"id":"MG-1-TF7","ch":1,"sl":"46","tp":"Propagation delay independent of packet length","t":"tf","q":"The propagation delay for a packet to travel between two hosts depends on the packet length and the distance between these hosts, so a large packet takes longer propagation delay than a small packet.","a":1,"e":"Chapter 1, slide 46: d<sub>prop</sub> = d/s depends only on the link length and propagation speed. Packet length affects the <b>transmission</b> delay L/R. <b>False</b>.","from":[{"s":"MG","qn":"Q1 Part1.7","pg":111}]},{"id":"MG-1-TF8","ch":1,"sl":"53–54","tp":"Bottleneck = minimum","t":"tf","q":"In a network path that contains multiple links, each with varying throughput values, the maximum achievable end-to-end throughput is determined by the maximum throughput among these links.","a":1,"e":"Chapter 1, slides 53–54: the end-end throughput is set by the <b>bottleneck</b> link — the link with the <b>minimum</b> rate on the path. <b>False</b>.","from":[{"s":"MG","qn":"Q1 Part1.8","pg":111}]},{"id":"MG-1-P2-1","ch":1,"sl":"46","tp":"Propagation delay definition","t":"mcq","q":"Time needed for bits to physically travel through the transmission medium from one end of a link to the other:","o":["Transmission delay","Processing delay","Propagation delay"],"a":2,"e":"Chapter 1, slide 46: d<sub>prop</sub> = d/s.","from":[{"s":"MG","qn":"Q1 Part2.1","pg":111}]},{"id":"MG-1-P2-2","ch":1,"sl":"46, 53","tp":"Single link: delay, throughput, packets/s","t":"short","q":"A single router transmits packets of length L = <b>16000 bytes</b> over a link of rate R = <b>1 Mbps</b>.<br>2) Transmission delay? (A) 0.16 s (B) 0.016 s (C) 0.128 s (D) 0.0128 msec (E) 1.28 s<br>3) Maximum achievable throughput of this link? (A) 16000 bps (B) 128000 bps (C) 1 Mbps (D) 16 Mbps<br>4) Maximum number of packets per second? (A) 16000 packets/s (B) 7 packets/s (C) 128000 packets/s (D) 1 Mbps","a":"2) <b>C — 0.128 s</b> (16000×8 = 128000 bits ÷ 10<sup>6</sup>)<br>3) <b>C — 1 Mbps</b><br>4) <b>B — ≈7 packets/s</b> (10<sup>6</sup> / 128000 = 7.8 → 7 whole packets)","e":"Chapter 1, slide 46: d<sub>trans</sub> = L/R. Slide 53: throughput over one link = its rate R. Packets per second = R / L.","from":[{"s":"MG","qn":"Q1 Part2.2–4","pg":112}]},{"id":"MH-1-1","ch":1,"sl":"30","tp":"Circuit switching reserves resources","t":"mcq","q":"In circuit switching networks, which of the following options is true?","o":["Transmission rate cannot be guaranteed.","The resources needed along a path are reserved.","Uses the resources on demand.","A and B are both correct"],"a":1,"e":"Chapter 1, slide 30: end-end resources are allocated to, <b>reserved</b> for the call; circuit-like (guaranteed) performance. Using resources on demand is packet switching (slide 33). So only B is true.","from":[{"s":"MH","qn":"Q1.1","pg":116},{"s":"M23","qn":"Q2.4","pg":123}]},{"id":"MH-1-2","ch":1,"sl":"49, 52","tp":"Traffic intensity low → no loss","t":"mcq","q":"The average packet arrival rate at a router is 10 packets/sec with packet length L = 1.5 Kbits. The router output link rate is 100 Mbps. So,","o":["traffic intensity is low and packet loss may occur.","traffic intensity is high and packet loss may occur.","traffic intensity is low and packet loss will not occur.","traffic intensity is high and packet loss will not occur"],"a":2,"e":"Chapter 1, slide 49: La/R = (10 × 1500)/(100×10<sup>6</sup>) = 1.5×10<sup>-4</sup> ≈ 0 → small queueing delay. Slide 52: loss happens when packets arrive to a full buffer; with almost no queue, no packets are lost.","from":[{"s":"MH","qn":"Q1.2","pg":116}]},{"id":"MH-1-3","ch":1,"sl":"45","tp":"Which delay can be zero","t":"mcq","q":"In a network, if P is the only packet being transmitted and there were no earlier transmissions, which of the following delays could be zero?","o":["Propagation delay","Queuing delay","Transmission delay","Processing delay"],"a":1,"e":"Chapter 1, slide 45: queueing delay is time waiting at the output link and depends on the congestion level. With no other packets in the queue, it is zero. Transmission (L/R) and propagation (d/s) delays are never zero.","from":[{"s":"MH","qn":"Q1.3","pg":116}]},{"id":"M23-2-2","ch":1,"sl":"49, 52","tp":"Traffic intensity (15 packets/s)","t":"mcq","q":"The average packet arrival rate at a router is 15 packets/sec with packet length L = 1.5 Kbits. The router output link rate is 100 Mbps. So,","o":["traffic intensity is low and packet loss may occur.","traffic intensity is high and packet loss may occur.","traffic intensity is low and packet loss will not occur.","traffic intensity is high and packet loss will not occur"],"a":2,"e":"Chapter 1, slide 49: La/R = (15 × 1500)/(100×10<sup>6</sup>) = 2.25×10<sup>-4</sup> ≈ 0 → queueing delay small, buffer never fills (slide 52), so no loss.","from":[{"s":"M23","qn":"Q2.2","pg":122}]},{"id":"M23J-1-2","ch":1,"sl":"30, 33","tp":"Advantage of circuit switching","t":"mcq","q":"Advantage of circuit switching over packet switching:","o":["More bandwidth","Provide guaranteed service","Connection setup","Multi routes"],"a":1,"e":"Chapter 1, slide 30: dedicated resources → circuit-like (guaranteed) performance. Slide 33: packet switching has no call setup but suffers excessive congestion (delay and loss); \"how to provide circuit-like behavior with packet switching?\" is an open question.","from":[{"s":"M23J","qn":"Q1.2","pg":126}]},{"id":"M23J-1-4","ch":1,"sl":"46","tp":"Propagation delay Vancouver→Halifax","t":"mcq","q":"The one-way propagation delay for a single bit traveling at the speed of light (3×10<sup>8</sup> m/s) over a fiber-optic cable from Vancouver to Halifax (6000 km) would be approximately:","o":["1 millisecond","2 milliseconds","20 milliseconds","50 milliseconds"],"a":2,"e":"Chapter 1, slide 46: d<sub>prop</sub> = d/s = 6×10<sup>6</sup> m / 3×10<sup>8</sup> m/s = 0.02 s = <b>20 ms</b>.","from":[{"s":"M23J","qn":"Q1.4","pg":126}]},{"id":"M23J-1-5","ch":1,"sl":"7","tp":"Protocols define format/order","t":"mcq","q":"The format and the order of messages exchanged between two or more communicating nodes are defined by:","o":["Protocols","Headers","Client/Server model","Network layers"],"a":0,"e":"Chapter 1, slide 7: protocols define the format, order of messages sent and received among network entities, and actions taken on message transmission and receipt.","from":[{"s":"M23J","qn":"Q1.5","pg":126}]},{"id":"M23J-1-6","ch":1,"sl":"45","tp":"Processing delay","t":"mcq","q":"The time required to examine the packet's header and determine where to direct the packet is part of:","o":["Transmission delay","Propagation delay","Queuing delay","Processing delay"],"a":3,"e":"Chapter 1, slide 45: d<sub>proc</sub> (nodal processing) — check bit errors, <b>determine output link</b>; typically &lt; microseconds.","from":[{"s":"M23J","qn":"Q1.6","pg":127}]},{"id":"M23J-2","ch":1,"sl":"27, 38–40, 49","tp":"Company network: delay, intensity, fix","t":"short","q":"A company network has <b>10 hosts</b>, each connected to Router1 by a <b>100 Mbps</b> link. The access link between Router1 and Router2 is <b>1 Mbps</b>. Packet length L = <b>10 Kbits</b>. The Internet delay between Router2 and any web server is <b>1 ms</b>.<br>a. Only Host A is active. Neglecting processing, queueing and propagation delays, compute the end-to-end delay from Host A to server S1.<br>b. Now all 10 hosts are active; the average packet arrival rate at Router1 is <b>80 packets/s</b>.<br>&nbsp;&nbsp;1) Compute the traffic intensity at Router1.<br>&nbsp;&nbsp;2) Will the queueing delay increase? Explain.<br>&nbsp;&nbsp;3) Propose a solution to decrease the response time (time from a client's request for a page until it gets it). Explain.","img":"M23J-2.jpg","a":"a. L/R<sub>1</sub> + L/R<sub>access</sub> + Internet delay = 10<sup>4</sup>/10<sup>8</sup> + 10<sup>4</sup>/10<sup>6</sup> + 1 ms = 0.1 ms + 10 ms + 1 ms = <b>11.1 ms</b>.<br>b1. La/R = (10<sup>4</sup> bits × 80)/10<sup>6</sup> bps = <b>0.8</b> (Router1's output link is the 1 Mbps access link).<br>b2. <b>Yes</b> — La/R = 0.8 is close to 1, so the average queueing delay becomes large (and it grows very fast as the intensity approaches 1).<br>b3. Install a <b>Web cache (proxy server)</b> inside the company network: many requests are satisfied locally at LAN speed, which cuts traffic on the access link (lower intensity → lower queueing delay) and lowers response time. (Upgrading the 1 Mbps access link also works but costs more.)","e":"Chapter 1, slide 27: store-and-forward — each link adds L/R. Slide 49: traffic intensity La/R; ≈ 0 small delay, → 1 large delay, &gt; 1 infinite. Chapter 2, slides 37–40 (Caching example): with 0.97 access-link utilization, buying a faster access link is expensive; installing a local web cache with a 40% hit rate drops utilization to 0.58 and lowers the average end-end delay.","from":[{"s":"M23J","qn":"Q2","pg":128}]},{"id":"BB1-8","ch":1,"sl":"16","tp":"DSL splitter","t":"mcq","q":"________ device separates the data and phone signals arriving to the home and forwards the data signal to the DSL modem.","o":["Splitter","Cable modem","DSLAM","CMTS"],"a":0,"e":"Chapter 1, slide 16 (Access networks: DSL): in the home, the <b>splitter</b> separates voice and data (sent at different frequencies) and passes data to the DSL modem; the DSLAM is at the central office; cable modem and CMTS belong to cable access (slides 14–15).","from":[{"s":"M22S","qn":"Q1.15","pg":133},{"s":"BB1","qn":"Q8","pg":20}]},{"id":"M22S-1-1","ch":1,"sl":"61–63","tp":"Transport passes to network","t":"mcq","q":"The transport layer receives data from different applications and passes it to the:","o":["Data Link layer.","Application layer.","Network layer.","Physical layer."],"a":2,"e":"Chapter 1, slides 62–63: the transport layer encapsulates the application message into a segment and passes it down to the <b>network</b> layer, which encapsulates it into a datagram. Chapter 3, slide 4: the sender breaks application messages into segments and passes them to the network layer.","from":[{"s":"M22S","qn":"Q1.1","pg":131},{"s":"MJ","qn":"Q1.1","pg":146}]},{"id":"M22S-1-2","ch":1,"sl":"62–63","tp":"Transport unit = segment","t":"mcq","q":"In the transport layer, a message is divided into:","o":["frames.","segments.","datagrams.","packets."],"a":1,"e":"Chapter 1, slides 62–63: transport-layer protocol encapsulates the application message M with header H<sub>t</sub> to create a transport-layer <b>segment</b>. Chapter 3, slide 4: sender breaks application messages into segments.","from":[{"s":"M22S","qn":"Q1.2","pg":131},{"s":"MJ","qn":"Q1.2","pg":146}]},{"id":"M22S-1-3","ch":1,"sl":"61","tp":"Application-layer protocol","t":"mcq","q":"Which of the following is an application layer protocol?","o":["HTTP","TCP","UDP","IP protocol"],"a":0,"e":"Chapter 1, slide 61: application layer — HTTP, IMAP, SMTP, DNS; transport — TCP, UDP; network — IP.","from":[{"s":"M22S","qn":"Q1.3","pg":131}]},{"id":"M22S-1-8","ch":1,"sl":"28–29","tp":"Queueing delay when arrivals exceed rate","t":"mcq","q":"The ______ delay occurs when the arrival rate (in bps) to a link exceeds the transmission rate (bps) of the link for some period of time.","o":["Transmission","Propagation","Queueing","Processing"],"a":2,"e":"Chapter 1, slides 28–29 (Packet-switching: queueing): if the arrival rate exceeds the transmission rate for some time, packets will <b>queue</b>, waiting to be transmitted on the output link.","from":[{"s":"M22S","qn":"Q1.8","pg":132}]},{"id":"M22S-1-11","ch":1,"sl":"46","tp":"Link speed affects transmission delay","t":"mcq","q":"Which delay is affected by the speed (transmission rate) of the link between the sender and the receiver?","o":["Transmission Delay","Propagation Delay","Processing Delay","Queueing Delay"],"a":0,"e":"Chapter 1, slide 46: d<sub>trans</sub> = L/R, where R is the link transmission rate (bps). Propagation delay depends on length and propagation speed, not on R.","from":[{"s":"M22S","qn":"Q1.11","pg":132}]},{"id":"M22S-2","ch":1,"sl":"53–54","tp":"File transfer time via bottleneck","t":"short","q":"A) Calculate the time (in seconds) to transfer an MP3 file of <b>50 million bits</b> from the server to the client. The server's access link is R<sub>s</sub> = <b>5 Mbps</b> and the client's access link is R<sub>c</sub> = <b>2 Mbps</b>. Ignore all other delays.<br>B) Which link is the bottleneck — server link or client link? Why?","a":"A) Throughput = min(R<sub>s</sub>, R<sub>c</sub>) = 2 Mbps → time = 50×10<sup>6</sup> / 2×10<sup>6</sup> = <b>25 s</b>.<br>B) The <b>client link</b> — it has the minimum transmission rate, so it limits the end-to-end rate.","e":"Chapter 1, slide 54: R<sub>s</sub> &gt; R<sub>c</sub> → average end-end throughput is R<sub>c</sub>; the bottleneck link is the link on the end-end path that constrains end-end throughput. Transfer time = file size / throughput.","from":[{"s":"M22S","qn":"Q2","pg":133}]},{"id":"M22S-3-A","ch":1,"sl":"31–32","tp":"TDM file transfer time","t":"short","q":"A file of <b>1,280,000 bits</b> is sent from Host A to Host B over a circuit-switched network. All links use TDM with <b>24 slots</b> and a bit rate of <b>1.536 Mbps</b>. Establishing the end-to-end circuit takes <b>1 second</b>. How long does it take to send the file?","a":"Per-circuit rate = 1,536,000 / 24 = 64,000 bps.<br>Transfer time = 1,280,000 / 64,000 = 20 s.<br>Total = 20 + 1 (circuit setup) = <b>21 s</b>.","e":"Chapter 1, slide 31: in TDM each circuit gets one slot per frame, so it gets 1/24 of the link rate. Slide 30: the circuit must be set up (call setup) before data can flow.","from":[{"s":"M22S","qn":"Q3 A","pg":134}]},{"id":"MI-2","ch":1,"sl":"46, 49, 53–54","tp":"Voice path: bottleneck, prop, end-to-end, intensity","t":"short","q":"Path: H1 —Link1 (1 Gbps)— R1 —Link2 (5 Mbps)— R2 —Link3 (2.5 Gbps)— H2. Each link is <b>2 km</b> long; propagation speed 2×10<sup>8</sup> m/s. H1 sends real-time voice to H2.<br>1. Which link constrains the end-end throughput?<br>2. Total propagation delay from H1 to H2?<br>3. With empty queues and negligible processing delay, what is the end-to-end delay for a <b>16-byte</b> packet?<br>4. The average arrival rate at R1 is 250 packets/s, link bandwidth 1 Gbps, packet length 1024 bits. Traffic intensity at R1?","img":"MI-2.jpg","a":"1. <b>Link 2</b> (5 Mbps, the smallest rate).<br>2. Per link: 2000 / 2×10<sup>8</sup> = 10<sup>-5</sup> s; total = 3×10<sup>-5</sup> s = <b>30 µs</b>.<br>3. L = 128 bits. Transmission: 128/10<sup>9</sup> + 128/5×10<sup>6</sup> + 128/2.5×10<sup>9</sup> = 0.128 + 25.6 + 0.0512 µs ≈ 25.78 µs. Total = 25.78 + 30 = <b>≈ 55.78 µs</b>.<br>4. La/R = 250 × 1024 / 10<sup>9</sup> = <b>0.000256</b>.","e":"Chapter 1, slides 53–54: the bottleneck (minimum-rate) link limits throughput. Slide 46: d<sub>prop</sub> = d/s per link, d<sub>trans</sub> = L/R per link (store-and-forward, slide 27). Slide 49: traffic intensity La/R.","from":[{"s":"MI","qn":"Q2","pg":141}]},{"id":"MK-3-1","ch":1,"sl":"27, 46","tp":"File over 20,000 km link; stop-and-wait packets","t":"short","q":"Hosts A and B are <b>20,000 km</b> apart, connected by a direct link of <b>R = 1 Mbps</b>; propagation speed 2×10<sup>8</sup> m/s. A file of <b>200,000 bits</b> is sent continuously as one large message.<br>A) File transmission delay?<br>B) Propagation delay?<br>C) Total end-to-end delay (processing and queueing negligible)?<br>D) Now the file is broken into <b>10 packets of 20,000 bits</b>; each packet is acknowledged, ACK transmission time is negligible, and the sender can't send a packet until the previous one is acknowledged. How long does it take to send the file?","a":"A) 200,000 / 10<sup>6</sup> = <b>0.2 s</b><br>B) 2×10<sup>7</sup> / 2×10<sup>8</sup> = <b>0.1 s</b><br>C) 0.2 + 0.1 = <b>0.3 s</b><br>D) Each packet: 0.02 s transmit + 0.1 s to arrive + 0.1 s for the ACK to return = 0.22 s. The first 9 packets take 9 × 0.22 = 1.98 s; the last packet arrives 0.12 s later → <b>2.1 s</b> (2.2 s if you count until the last ACK reaches A).","e":"Chapter 1, slide 46: d<sub>trans</sub> = L/R, d<sub>prop</sub> = d/s. Part D is stop-and-wait (Chapter 3, slides 49–51): each packet costs L/R + RTT, where RTT = 2·d<sub>prop</sub>.","from":[{"s":"MK","qn":"Q3.1","pg":151}]},{"id":"FA-1-2","ch":1,"sl":"30–31","tp":"Circuit switching characteristics","t":"mcq","q":"Which of the characteristics below are associated with the technique of <i>Circuit switching</i>?","o":["Resources are reserved before data being transmitted from the source to the destination.","Frequency Division Multiplexing (FDM) and Time Division Multiplexing (TDM) are two approaches for implementing this technique.","Commonly used in traditional telephone networks.","All the above."],"a":3,"e":"Chapter 1, slide 30: end-end resources are allocated to, reserved for the \"call\" between source and destination; commonly used in traditional telephone networks. Slide 31: circuit switching is implemented with FDM or TDM.","from":[{"s":"FA","qn":"Q1 A.2","pg":26}]},{"id":"FA-1-3","ch":1,"sl":"7","tp":"Protocol definition","t":"mcq","q":"Define the format, order of messages sent and received among network entities, and actions taken on message transmission, receipt.","o":["Routing algorithm","Encapsulation","Multiplexing","Protocols","Data communication"],"a":3,"e":"Chapter 1, slide 7 (What's a protocol?): <i>protocols</i> define the format, order of messages sent and received among network entities, and actions taken on message transmission, receipt.","from":[{"s":"FA","qn":"Q1 A.3","pg":26}]},{"id":"FB-1-9","ch":1,"sl":"28–29, 52","tp":"Arrival rate > link rate","t":"mcq","q":"If the packet arrival rate (in bps) to a link exceeds the transmission rate (bps) of the link for some period of time, which of the following will occur?","o":["packets will queue","packets can be dropped (lost)","memory (buffer) in router fills up","All of the above"],"a":3,"e":"Chapter 1, slides 28–29 (Packet-switching: queueing): if the arrival rate exceeds the transmission rate for some time, packets will queue, waiting to be transmitted on the output link, and packets can be dropped (lost) if the memory (buffer) in the router fills up. Slide 52: a packet arriving to a full buffer is dropped.","from":[{"s":"FB","qn":"Q1 A.9","pg":43}]},{"id":"FB-1-10","ch":1,"sl":"33","tp":"Bursty data → packet switching","t":"mcq","q":"Which type of switching is great for bursty data (sometimes has more data to send, sometimes a moderate amount, but at other times no data to send)?","o":["Circuit switching","Packet switching","All of the above","None of the above"],"a":1,"e":"Chapter 1, slide 33: packet switching is great for \"bursty\" data — sometimes has data to send, but at other times not; resource sharing, simpler, no call setup.","from":[{"s":"FB","qn":"Q1 A.10","pg":43}]},{"id":"FC-TF-8","ch":1,"sl":"65–66","tp":"Network layer in every host and router","t":"tf","q":"Network layer protocols must be defined in every host and router.","a":0,"e":"Chapter 1, slides 65–66: hosts implement all five layers and routers implement network, link and physical — so the network layer (IP) is present in every host and router. <b>True</b>.","from":[{"s":"FC","qn":"Q1(b).8","pg":50},{"s":"F13","qn":"Q1(b).8","pg":209}]},{"id":"FC-TF-10","ch":1,"sl":"30","tp":"Circuit paths are dedicated","t":"tf","q":"Circuit switching is used to establish dedicated network paths that may be shared by other end systems.","a":1,"e":"Chapter 1, slide 30: in circuit switching the resources are <b>dedicated</b> to the call — no sharing. A circuit segment is idle if not used by the call. <b>False</b>.","from":[{"s":"FC","qn":"Q1(b).10","pg":50},{"s":"F13","qn":"Q1(b).10","pg":209}]},{"id":"FD-2-A","ch":1,"sl":"46","tp":"800,000-bit file over 20,000 km","t":"short","q":"Hosts A and B are separated by <b>20,000 km</b> and connected by a direct link of <b>R = 10 Mbps</b>; propagation speed 2×10<sup>8</sup> m/s. A file of <b>800,000 bits</b> is sent continuously as one large message. How long does it take to send the file (until it is fully received at B)?","img":"FD-2-A.jpg","a":"d<sub>trans</sub> = 800,000 / 10×10<sup>6</sup> = 0.08 s; d<sub>prop</sub> = 2×10<sup>7</sup> / 2×10<sup>8</sup> = 0.1 s → total = <b>0.18 s</b>.","e":"Chapter 1, slide 46: d<sub>trans</sub> = L/R and d<sub>prop</sub> = d/s; the last bit is pushed out after L/R and arrives d/s later.","from":[{"s":"FD","qn":"Q2 A.1","pg":155}]},{"id":"F22-1","ch":1,"sl":"46","tp":"10 Gb file: transmission & propagation","t":"short","q":"A <b>10 Gb</b> file is sent between two hosts. The transmission rate is <b>10 Gbps</b>, the distance between the two nodes is <b>10,000 km</b>, and data travels at 2×10<sup>8</sup> m/s.<br>1. What is the transmission delay?<br>2. What is the propagation delay?","a":"1. L/R = 10×10<sup>9</sup> / 10×10<sup>9</sup> = <b>1 s</b><br>2. d/s = 10<sup>7</sup> / 2×10<sup>8</sup> = <b>0.05 s = 50 ms</b>","e":"Chapter 1, slide 46: d<sub>trans</sub> = L/R; d<sub>prop</sub> = d/s.","from":[{"s":"F22","qn":"Q1–2","pg":158}]},{"id":"FE-2-A","ch":1,"sl":"27","tp":"Message segmentation (8 Mbit, 2 switches)","t":"short","q":"Host A sends an <b>8 Mbit</b> message to Host B through <b>two packet switches</b>. Each link is <b>2 Mbps</b>; ignore propagation, queueing and processing delays.<br>1. Without message segmentation, how long does it take to move the message from Host A to the first switch?<br>2. Each switch uses store-and-forward packet switching. What is the total time to move the message from A to B?<br>3. Now the message is segmented into <b>800 packets of 10,000 bits</b>. How long does it take to move the first packet from A to the first switch?","img":"FE-2-A.jpg","a":"1. 8×10<sup>6</sup> / 2×10<sup>6</sup> = <b>4 s</b><br>2. Three links, each store-and-forward: 3 × 4 = <b>12 s</b><br>3. 10,000 / 2×10<sup>6</sup> = <b>5 ms</b><br><i>Going further:</i> with segmentation the whole message arrives after (800 + 2) × 5 ms = <b>4.01 s</b> instead of 12 s, because the switches work on different packets in parallel (pipelining).","e":"Chapter 1, slide 27 (Packet-switching: store-and-forward): it takes L/R seconds to transmit an L-bit packet into a link at R bps, and the entire packet must arrive at the router before it can be transmitted on the next link — so end-end delay for one packet over N links = N·L/R.","from":[{"s":"FE","qn":"Q2 A","pg":162}]},{"id":"FE-1-1","ch":1,"sl":"5, 34","tp":"Connect via an ISP","t":"mcq","q":"To join the Internet, the computer has to be connected to a ______.","o":["internet architecture board","internet society","internet service provider","different computer"],"a":2,"e":"Chapter 1, slide 34: hosts connect to the Internet via access ISPs (Internet Service Providers): residential, enterprise (company, university, commercial) ISPs.","from":[{"s":"FE","qn":"Q1 A.1","pg":167}]},{"id":"FE-1-2","ch":1,"sl":"39–42","tp":"Internet exchange point","t":"mcq","q":"ISPs exchange Internet traffic between their networks by ______.","o":["internet exchange point","subscriber endpoint","ISP endpoint","internet end point"],"a":0,"e":"Chapter 1, slides 39–42 (Internet structure: a network of networks): competing ISPs interconnect at an <b>Internet exchange point (IXP)</b> or through peering links.","from":[{"s":"FE","qn":"Q1 A.2","pg":167}]},{"id":"FF-2-A","ch":1,"sl":"62–64","tp":"Which layer does this?","t":"short","q":"Which layer of the Internet stack best corresponds to each phrase?<br>1. \"passes frames from one node to another across some medium\"<br>2. \"bits live on the wire\"<br>3. \"moves datagrams from the source host to the destination host\"<br>4. \"handles the delivery of segments from the application layer, may be reliable or unreliable\"<br>5. \"handles messages from a set of network applications\"","a":"1. <b>Link</b> · 2. <b>Physical</b> · 3. <b>Network</b> · 4. <b>Transport</b> · 5. <b>Application</b>","e":"Chapter 1, slide 61 (layered Internet protocol stack) and slides 62–64 (message → segment → datagram → frame, with bits on the physical wire). TCP is reliable and UDP unreliable, which is why phrase 4 says \"may be reliable or unreliable\".","from":[{"s":"FF","qn":"Q2 A","pg":274}]},{"id":"FF-2-B","ch":1,"sl":"46","tp":"1.6 Mbit file over 40,000 km; with request","t":"short","q":"Client A and server B are <b>40,000 km</b> apart, connected by a direct link of <b>R = 20 Mbps</b>; propagation speed 2×10<sup>8</sup> m/s.<br>1. A <b>1.6 Mbit</b> file is downloaded from B to A as one large message. Transmission delay?<br>2. Propagation delay?<br>3. Total delay to move the file (no processing/queueing)?<br>4. If A first sends a request message of negligible size, what is the total time from sending the request until the file is received?","img":"FF-2-B.jpg","a":"1. 1.6×10<sup>6</sup> / 20×10<sup>6</sup> = <b>0.08 s</b><br>2. 4×10<sup>7</sup> / 2×10<sup>8</sup> = <b>0.2 s</b><br>3. 0.08 + 0.2 = <b>0.28 s</b><br>4. 0.2 (request propagates) + 0.28 = <b>0.48 s</b> (= RTT + file transmission time)","e":"Chapter 1, slide 46: d<sub>trans</sub> = L/R, d<sub>prop</sub> = d/s. The request has negligible size, so it only costs one propagation delay.","from":[{"s":"FF","qn":"Q2 A","pg":280}]},{"id":"BB2-5","ch":1,"sl":"31","tp":"Sharing a circuit link","t":"mcq","q":"In circuit switching, a physical link can be shared among multiple users via:","o":["FDM and TDM","Packet switching","Wi-Fi and 4G","None of the above"],"a":0,"e":"Chapter 1, slide 31 (Circuit switching: FDM and TDM).","from":[{"s":"Q1R","qn":"Q7","pg":65},{"s":"BB3","qn":"Q8","pg":79},{"s":"BB2","qn":"Q3","pg":56}]},{"id":"Q1R-4","ch":1,"sl":"46, 49","tp":"Transmission delay, total delay, traffic intensity","t":"short","q":"Same 3-link network: lengths 1500, 5000, 1000 km; rates 10, 30, 25 Mbps; s = 2×10<sup>8</sup> m/s; packet = 4000 bits. (Answer in seconds.)<br>a. Transmission delay of link 2 = ?<br>b. Total delay of link 2 = ?<br>c. If the average packet arrival rate at Router 1 is 10 packets/s, compute the traffic intensity at Router 1.","a":"a. 4000 / 30×10<sup>6</sup> = <b>1.333×10<sup>-4</sup> s</b><br>b. 1.333×10<sup>-4</sup> + 5×10<sup>6</sup>/2×10<sup>8</sup> = 0.000133 + 0.025 = <b>0.025133 s</b><br>c. Router 1 sends on link 2: La/R = (4000 × 10)/30×10<sup>6</sup> = <b>0.00133</b>","e":"Chapter 1, slide 46 (d<sub>trans</sub> = L/R, d<sub>prop</sub> = d/s) and slide 49 (traffic intensity La/R using the router's output link).","from":[{"s":"Q1R","qn":"Q4","pg":64}]},{"id":"Q1R-3","ch":1,"sl":"53–55","tp":"Utilization of shared link","t":"short","q":"Four servers connect to four clients over four three-hop paths sharing a middle hop of capacity <b>R = 300 Mbps</b>. Server links R<sub>S</sub> = <b>50 Mbps</b>; client links R<sub>C</sub> = <b>90 Mbps</b>. Assuming the servers all send at their maximum possible rate, what is the utilization of the shared link (R)? (Answer as 1.00 or 0.xx.)","img":"Q1R-3.jpg","a":"Each pair's rate = min(R<sub>S</sub>, R/4, R<sub>C</sub>) = min(50, 75, 90) = 50 Mbps. The shared link carries 4 × 50 = 200 Mbps → utilization = 200/300 = <b>0.67</b>.","e":"Chapter 1, slides 53–55: each connection's throughput is limited by its bottleneck — here the 50 Mbps server links. Utilization of a link = traffic it carries ÷ its capacity.","from":[{"s":"Q1R","qn":"Q3","pg":66}]},{"id":"Q1R-2","ch":1,"sl":"66","tp":"Switch layers","t":"short","q":"An internet (link-layer) switch involves which layers of the TCP/IP layers?","a":"<b>Physical and data link layers</b> only.","e":"Chapter 1, slide 66: the switch implements link + physical; the router adds the network layer; hosts implement all five layers.","from":[{"s":"Q1R","qn":"Q2","pg":67}]},{"id":"Q1R-8","ch":1,"sl":"45–46","tp":"Match delay components","t":"short","q":"Match each description to its packet-delay component:<br>1. Time needed to perform an integrity check, look up packet information in a local table and move the packet from an input link to an output link in a router.<br>2. Time spent waiting in packet buffers for link transmission.<br>3. Time spent transmitting the packet's bits into the link.<br>4. Time needed for bits to physically propagate through the transmission medium from one end of a link to the other.","a":"1 → <b>Processing delay</b><br>2 → <b>Queueing delay</b><br>3 → <b>Transmission delay</b><br>4 → <b>Propagation delay</b>","e":"Chapter 1, slide 45: d<sub>proc</sub> = check bit errors, determine output link; d<sub>queue</sub> = time waiting at output link for transmission. Slide 46: d<sub>trans</sub> = L/R; d<sub>prop</sub> = d/s.","from":[{"s":"Q1R","qn":"Q8","pg":68}]},{"id":"BB1-1","ch":1,"sl":"27, 46","tp":"End-to-end transmission delay","t":"mcq","q":"A network path connects a server to a client: server —(200 km, 1 Gb/s)— X —(2000 km, 1 Gb/s)— Y —(2 km, 1 Mb/s)— client. What is the end-to-end <b>transmission</b> delay for a packet of size 10,000 bits?","img":"BB1-1.jpg","o":["10.02 ms","4.99 µs","0.2 µs","200 µs"],"a":0,"e":"Chapter 1, slide 27: with store-and-forward the packet is transmitted (L/R) on every link. 10<sup>4</sup>/10<sup>9</sup> + 10<sup>4</sup>/10<sup>9</sup> + 10<sup>4</sup>/10<sup>6</sup> = 10 µs + 10 µs + 10 ms = <b>10.02 ms</b>. Propagation delay (d/s) is not part of the transmission delay.","from":[{"s":"BB1","qn":"Q1","pg":20}]},{"id":"BB1-2","ch":1,"sl":"49","tp":"Traffic intensity","t":"mcq","q":"Consider a 10 Mb/s link that is 400 km long, with a queue large enough to hold 2,000 packets. Packets arrive at the queue with an average rate of 4,000 packets per second and the average packet length is 2,000 bits. What is the traffic intensity?","o":["0.4","0.8","Very large","20"],"a":1,"e":"Chapter 1, slide 49: traffic intensity = La/R = (2000 bits × 4000 pkt/s) / 10×10<sup>6</sup> bps = 8×10<sup>6</sup>/10<sup>7</sup> = <b>0.8</b>. The link length and buffer size are not needed.","from":[{"s":"BB1","qn":"Q2","pg":20}]},{"id":"BB1-3","ch":1,"sl":"27","tp":"Store-and-forward","t":"mcq","q":"Store and forward mechanism is used in:","o":["both packet-switched and circuit-switched networks","packet-switched networks","circuit-switched networks"],"a":1,"e":"Chapter 1, slide 27 (Packet-switching: store-and-forward): the entire packet must arrive at the router before it can be transmitted on the next link. Circuit switching has a dedicated end-to-end circuit, so bits flow through without being stored.","from":[{"s":"BB1","qn":"Q3","pg":20}]},{"id":"BB1-4","ch":1,"sl":"30","tp":"Circuit switching guarantees","t":"mcq","q":"As the resources are reserved between two communicating end systems in circuit switching networks, this is achieved:","o":["authentication","store and forward","reliability","guaranteed constant rate"],"a":3,"e":"Chapter 1, slide 30: end-end resources (link bandwidth, switch capacity) are allocated to and reserved for the call → dedicated resources, circuit-like (<b>guaranteed</b>) performance at a constant rate.","from":[{"s":"BB1","qn":"Q4","pg":20}]},{"id":"BB1-5","ch":1,"sl":"46","tp":"Propagation delay definition","t":"mcq","q":"The time required for a bit to propagate from the beginning of a link to the end of the link is:","o":["end-to-end delay","processing delay","propagation delay","transmission delay"],"a":2,"e":"Chapter 1, slide 46: d<sub>prop</sub> = d/s, where d = length of the physical link and s = propagation speed (~2×10<sup>8</sup> m/s). Transmission delay (L/R) is the time to push the bits <i>onto</i> the link.","from":[{"s":"BB1","qn":"Q5","pg":20}]},{"id":"BB1-6","ch":1,"sl":"61","tp":"Application-layer protocols","t":"mcq","q":"Which one of the following is not an application layer protocol?","o":["FTP","DNS","UDP","HTTP"],"a":2,"e":"Chapter 1, slide 61: application layer — HTTP, IMAP, SMTP, DNS (FTP too); <b>UDP</b> is a transport-layer protocol (with TCP).","from":[{"s":"BB1","qn":"Q6","pg":20}]},{"id":"BB1-7","ch":1,"sl":"61–62","tp":"Layer services","t":"mcq","q":"The Application layer provides services to which layer?","o":["None","Link Layer","Network layer","Transport layer"],"a":0,"e":"Chapter 1, slides 60–62: each layer implements a service and relies on the services of the layer <i>below</i> it. The application layer is the top layer, so it provides services to the network applications/users, not to another layer. The transport layer serves the application layer, not the other way round.","from":[{"s":"BB1","qn":"Q7","pg":20}]},{"id":"BB2-4","ch":1,"sl":"46","tp":"Transmission delay definition","t":"mcq","q":"The amount of time required to push all of the packet's bits into the link is the:","o":["propagation delay","queuing delay","transmission delay","end-to-end delay"],"a":2,"e":"Chapter 1, slide 46: d<sub>trans</sub> = L/R — the time to push (transmit) the L bits of the packet into the link of rate R.","from":[{"s":"BB3","qn":"Q1","pg":81},{"s":"BB2","qn":"Q2","pg":56}]},{"id":"BB2-6","ch":1,"sl":"66","tp":"Router layers","t":"mcq","q":"An internet router involves the following layers of the TCP/IP layers:","o":["Physical and data link layers","Application, transport and network layers","Transport, network and physical layers","Network, data link and physical layers"],"a":3,"e":"Chapter 1, slide 66 (Encapsulation: an end-end view): the router implements network, link and physical; the switch only link and physical.","from":[{"s":"BB3","qn":"Q4","pg":74},{"s":"BB2","qn":"Q1","pg":58}]},{"id":"BB3-5b","ch":1,"sl":"46, 53–54","tp":"Propagation, total delay, max throughput (3 links)","t":"short","q":"Hosts A and B are connected by 3 links (Host A —Link1— Router 1 —Link2— Router 2 —Link3— Host B). Lengths: 1500 km, 5000 km, 1000 km; rates: 10 Mbps, 30 Mbps, 25 Mbps; propagation speed 2×10<sup>8</sup> m/s; packet length 4000 bits.<br>a. Propagation delay of link 2 = ? s<br>b. Total delay of link 2 = ? s<br>c. What is the maximum throughput that can be achieved from A to B?","a":"a. 5×10<sup>6</sup> / 2×10<sup>8</sup> = <b>0.025 s</b><br>b. 4000/30×10<sup>6</sup> + 0.025 = 0.000133 + 0.025 = <b>0.025133 s</b><br>c. min(10, 30, 25) = <b>10 Mbps</b> (link 1 is the bottleneck).","e":"Chapter 1, slide 46: d<sub>prop</sub> = d/s, d<sub>trans</sub> = L/R. Slides 53–54: the end-end throughput is the rate of the bottleneck link. (A student copy wrote 0.0133 for part c — that's 4000×100/30×10<sup>6</sup>, a traffic intensity, not a throughput.)","from":[{"s":"BB3","qn":"Q5","pg":74},{"s":"BB3","qn":"Q5","pg":92}]},{"id":"BB3-6","ch":1,"sl":"62–64","tp":"Header H1/H2/H3 in a frame","t":"short","q":"A link-layer frame is heading from a host to a router, shown as <b>H<sub>1</sub> H<sub>2</sub> H<sub>3</sub> M</b> (H<sub>1</sub> outermost, next to the link). Match each header to its layer (Transport, Network, Link, Application, Physical).","img":"BB3-6.jpg","a":"H<sub>1</sub> → <b>Link</b> layer<br>H<sub>2</sub> → <b>Network</b> layer<br>H<sub>3</sub> → <b>Transport</b> layer<br>(M is the application message.)","e":"Chapter 1, slides 62–64 (Services, Layering and Encapsulation): the transport layer adds H<sub>t</sub> to M, then the network layer adds H<sub>n</sub> in front, then the link layer adds H<sub>l</sub> in front — so the outermost header is the link header: [H<sub>l</sub> H<sub>n</sub> H<sub>t</sub> M]. A student copy (p. 84) picked D/A/B, which is wrong.","from":[{"s":"BB3","qn":"Q6","pg":74},{"s":"BB3","qn":"Q6","pg":84}]},{"id":"BB3-1b","ch":1,"sl":"53–55","tp":"Utilization of client links","t":"short","q":"Four servers connect to four clients over three-hop paths sharing a middle link of R = 300 Mbps. Server links R<sub>S</sub> = 50 Mbps; client links R<sub>C</sub> = 90 Mbps. If the servers all send at their maximum possible rate, what is the utilization of the <b>client</b> links (R<sub>C</sub>)? (1.00 or 0.xx)","a":"Each pair carries min(50, 300/4 = 75, 90) = 50 Mbps → client-link utilization = 50/90 = <b>0.56</b>.","e":"Chapter 1, slides 53–55: per-connection throughput = min of the link rates on its path (with the shared link split fairly). Utilization = carried rate ÷ capacity.","from":[{"s":"BB3","qn":"Q1","pg":80}]},{"id":"BB3-L3","ch":1,"sl":"62–65","tp":"Match layer to unit of data","t":"short","q":"Match each Internet layer with the unit of data exchanged among protocol entities at that layer: Application, Transport, Network, Link, Physical ↔ Segment, Message, Datagram, Bit, Frame.","a":"Application → <b>Message</b><br>Transport → <b>Segment</b><br>Network → <b>Datagram</b><br>Link → <b>Frame</b><br>Physical → <b>Bit</b>","e":"Chapter 1, slides 62–65 (encapsulation): message → segment → datagram → frame; the physical layer moves bits on the wire.","from":[{"s":"BB3","qn":"Q3","pg":82}]},{"id":"BB3-PS5","ch":1,"sl":"32–33","tp":"Packet switching serves more users","t":"mcq","q":"Packet Switching is:","o":["More efficient than Circuit Switching in terms of the number of users that can be served","Suitable for real-time services","A dedicated end-to-end connection between two hosts","All of the above"],"a":0,"e":"Chapter 1, slide 32: on a 1 Gb/s link, circuit switching supports 10 users, while packet switching supports 35 users with tiny probability of overload. Real-time services and dedicated connections are circuit-switching properties (slides 30, 33).","from":[{"s":"BB3","qn":"Q5","pg":83}]},{"id":"BB2-1","ch":1,"sl":"53","tp":"Bandwidth vs throughput","t":"mcq","q":"The amount of data that <i>can be</i> transferred from one location to another in a given amount of time is called:","o":["Bandwidth","Speed","Throughput","Transmission Rate"],"a":0,"e":"The maximum amount of data a link or path <i>can</i> carry per unit time is its <b>bandwidth</b> (capacity). Slide 53 defines <b>throughput</b> as the rate at which bits are <i>actually</i> being sent from sender to receiver (instantaneous or average), which is at most the bandwidth of the bottleneck link.","nb":"The quiz screenshot shows \"Bandwidth\" selected but not whether it was marked right.","from":[{"s":"BB2","qn":"Q1","pg":54}]},{"id":"BB2-2","ch":1,"sl":"31–32","tp":"TDM per-circuit rate","t":"mcq","q":"In a circuit-switched TDM network with 5 users and bit rate R, each circuit has transmission rate:","o":["R/5","R","5R","R/10"],"a":0,"e":"Chapter 1, slide 31: in TDM each call gets periodic slot(s) and transmits at the full rate R only during its slot, so with 5 circuits each gets 1/5 of the time → average rate <b>R/5</b>. (Slide 32: a 1 Gb/s link shared by 10 circuits gives each user 100 Mb/s.)","from":[{"s":"BB2","qn":"Q2","pg":54}]},{"id":"BB2-3","ch":1,"sl":"27, 46, 49","tp":"Propagation, total delay, traffic intensity (3 links)","t":"short","q":"Hosts A and B are connected by 3 links: Host A —Link1— Router 1 —Link2— Router 2 —Link3— Host B. Link lengths: <b>1500 km, 5000 km, 1000 km</b>; rates: <b>10 Mbps, 30 Mbps, 25 Mbps</b>. Propagation speed 2×10<sup>8</sup> m/s; packet length <b>4000 bits</b>. (Answer in seconds.)<br>a. Propagation delay of link 3 = ?<br>b. Total delay of link 3 (transmission + propagation) = ?<br>c. If the average packet arrival rate at Router 2 is 100 packets/s, compute the traffic intensity at Router 2.","img":"BB2-3.jpg","a":"a. d<sub>prop</sub> = 1000×10<sup>3</sup> / 2×10<sup>8</sup> = <b>0.005 s</b><br>b. d<sub>trans</sub> = 4000 / 25×10<sup>6</sup> = 0.00016 s → total = 0.00016 + 0.005 = <b>0.00516 s</b><br>c. Router 2 sends on link 3: La/R = (4000 × 100)/25×10<sup>6</sup> = <b>0.016</b><br><i>Variant on the same quiz (link 2):</i> d<sub>prop</sub> = 5×10<sup>6</sup>/2×10<sup>8</sup> = 0.025 s; d<sub>trans</sub> = 4000/30×10<sup>6</sup> ≈ 0.000133 s; total ≈ <b>0.025133 s</b>.","e":"Chapter 1, slide 46: d<sub>trans</sub> = L/R and d<sub>prop</sub> = d/s; the delay \"of a link\" is their sum (no queueing/processing given). Slide 49: traffic intensity = La/R, with R the rate of the router's <i>outgoing</i> link (link 3 for Router 2). A student copy (p. 57) used link 2's rate and got 0.0133 — that would be the intensity of traffic arriving <i>over</i> link 2, not of Router 2's output queue.","from":[{"s":"BB2","qn":"Q3","pg":55},{"s":"BB2","qn":"Q (variant)","pg":57}]},{"id":"BB2-7","ch":1,"sl":"31","tp":"TDM vs FDM","t":"mcq","q":"The difference between TDM and FDM:","o":["TDM uses time while FDM uses frequency for splitting","FDM uses time while TDM uses frequency for splitting","FDM is for packet switching while TDM for circuit switching","None of above"],"a":0,"e":"Chapter 1, slide 31: TDM divides time into slots; FDM divides frequencies into narrow bands. Both are circuit-switching techniques.","from":[{"s":"BB2","qn":"Q3","pg":59}]},{"id":"ML-1-2","ch":1,"sl":"3, 7","tp":"Every device runs protocols","t":"mcq","q":"Which of the following Internet devices must run protocols?","o":["end systems","link-layer switches","routers","All of the above"],"a":3,"e":"Chapter 1, slide 3: protocols are everywhere — they control the sending and receiving of messages. Slide 66 shows hosts, routers and switches each implementing protocol layers.","from":[{"s":"ML","qn":"Q1.2","pg":244}]},{"id":"ML-1-3","ch":1,"sl":"40–42","tp":"Multi-homing","t":"mcq","q":"In Internet network structure 4, connecting any ISP (except tier-1 ISPs) to two or more provider ISPs is called:","o":["PoP","peer","multi-home","IXP"],"a":2,"e":"Chapter 1, slides 40–42 (network of networks): regional networks may arise to connect access networks to ISPs, and ISPs connect at IXPs and peering links. Connecting one ISP to two or more provider ISPs is <b>multi-homing</b>. A PoP is a group of routers where customers connect; peering joins two ISPs of the same level directly.","nb":"The term \"multi-home\" is from the textbook (§1.3.3); your slides show the structure but don't name it.","from":[{"s":"ML","qn":"Q1.3","pg":244}]},{"id":"ML-1-4","ch":1,"sl":"66","tp":"Router processes network layer","t":"mcq","q":"Which layer in the Internet protocol stack does a router process (highest)?","o":["Network layer","Transport layer","a and b","None of the above"],"a":0,"e":"Chapter 1, slide 66: a router implements network, link and physical layers — it never processes the transport layer.","from":[{"s":"ML","qn":"Q1.4","pg":244}]},{"id":"ML-2-2","ch":1,"sl":"30–31","tp":"TDM circuit: 4 MB file","t":"short","q":"A file of <b>4 Mbytes</b> is sent from Host A to Host B over a circuit-switched network. All links use <b>TDM with 6 slots</b> and have a bit rate of <b>1.536 Mbps</b>. Establishing the end-to-end circuit takes <b>600 ms</b>.<br>a. End-to-end transmission delay?<br>b. Total time to send the file (propagation negligible)?","a":"Per-circuit rate = 1.536 Mbps / 6 = 256 kbps. File = 4 × 8 × 10<sup>6</sup> = 32×10<sup>6</sup> bits.<br>a. 32×10<sup>6</sup> / 256×10<sup>3</sup> = <b>125 s</b><br>b. 125 + 0.6 = <b>125.6 s</b>","e":"Chapter 1, slide 31: each TDM circuit gets one slot in 6 → 1/6 of the rate. Slide 30: the circuit must first be set up; there is no store-and-forward, so the file's transmission delay is counted once.","from":[{"s":"ML","qn":"Q2.2","pg":245}]},{"id":"ML-4","ch":1,"sl":"27, 53–54","tp":"3-link path: throughput & delay","t":"short","q":"Host A sends a large file to Host B over three links with rates R<sub>1</sub> = <b>500 kbps</b>, R<sub>2</sub> = <b>2 Mbps</b>, R<sub>3</sub> = <b>1 Mbps</b>.<br>a. With no other traffic, what is the end-to-end throughput?<br>b. The file is 4 Mbytes and fits in one packet. Calculate the end-to-end transmission delay.<br>c. Divide the file size by the throughput to approximate the transfer time. What do you conclude?","img":"ML-4.jpg","a":"a. min(500k, 2M, 1M) = <b>500 kbps</b><br>b. L = 32×10<sup>6</sup> bits, store-and-forward over 3 links: 32×10<sup>6</sup>/5×10<sup>5</sup> + 32×10<sup>6</sup>/2×10<sup>6</sup> + 32×10<sup>6</sup>/10<sup>6</sup> = 64 + 16 + 32 = <b>112 s</b><br>c. 32×10<sup>6</sup> / 5×10<sup>5</sup> = <b>64 s</b> — the bottleneck link dominates; if the file is split into many small packets (pipelining), the transfer time gets close to L / throughput.<br><i>(The printed figure shows 800 kb/s, 1 Gb/s, 2 Mb/s instead: throughput 800 kbps, b = 40 + 0.032 + 16 ≈ 56 s, c = 40 s.)</i>","e":"Chapter 1, slides 53–54: throughput = bottleneck rate. Slide 27: one big packet is stored and forwarded, paying L/R on every link.","from":[{"s":"ML","qn":"Q4","pg":247}]},{"id":"M16-1-5","ch":1,"sl":"24","tp":"Forwarding definition","t":"mcq","q":"Forwarding refers to ______.","o":["the manner by which datagrams are routed from source to destination ports of end hosts","the manner by which datagrams are moved from input to output ports of individual routers","the set of algorithms required to ensure near-optimal path selection","the manner by which datagrams are routed from source to destination between adjacent routers"],"a":1,"e":"Chapter 1, slide 24: forwarding = local action: move arriving packets from the router's input link to the appropriate router output link. Path selection algorithms are routing.","from":[{"s":"M16","qn":"Q1.5","pg":231}]},{"id":"F15-2-1","ch":1,"sl":"27, 45–46","tp":"One switch store-and-forward","t":"short","q":"There is exactly one packet switch between a sending host and a receiving host. Both links have rate R = <b>100 Mbps</b>.<br>a. With store-and-forward switching, what is the total end-to-end delay for a packet of length L = <b>1 kbit</b>?<br>b. State two delays that were neglected.","a":"a. 2 × L/R = 2 × 1000 / 10<sup>8</sup> = 2×10<sup>-5</sup> s = <b>0.02 ms</b><br>b. Any two of: <b>propagation</b> delay, <b>processing</b> delay, <b>queueing</b> delay.","e":"Chapter 1, slide 27: store-and-forward — the whole packet must arrive at the switch before it is transmitted on the next link, so the packet pays L/R on each of the 2 links. Slide 45: d<sub>nodal</sub> = d<sub>proc</sub> + d<sub>queue</sub> + d<sub>trans</sub> + d<sub>prop</sub>.","from":[{"s":"F15","qn":"Q2.1","pg":224}]},{"id":"F14-1-1","ch":1,"sl":"27","tp":"File over 10 store-and-forward links","t":"mcq","q":"A file of 160,000 bits is sent from Host A to Host B over <b>10 links</b>, each 2 Mbps. In a <b>packet-switched</b> network (the file sent as one packet), the end-to-end transmission delay is:","o":["0.8 sec","1.6 sec","0.08 sec","16 sec"],"a":0,"e":"Chapter 1, slide 27 (store-and-forward): each link adds L/R = 160,000 / 2×10<sup>6</sup> = 0.08 s, and the whole packet must arrive before the next link starts → 10 × 0.08 = <b>0.8 s</b>.","from":[{"s":"F14","qn":"Q1.1","pg":199}]},{"id":"F14-1-2","ch":1,"sl":"30–31","tp":"File over TDM circuit","t":"mcq","q":"Same file (160,000 bits) over the same 10 links of 2 Mbps, but in a <b>circuit-switched</b> network using <b>TDM with 20 slots</b>. The end-to-end transmission delay is:","o":["0.8 sec","1.6 sec","0.08 sec","16 sec"],"a":1,"e":"Chapter 1, slide 31: each TDM circuit gets 1/20 of the rate → 2 Mbps / 20 = 100 kbps. A circuit is end-to-end with no store-and-forward, so the delay is counted once: 160,000 / 100,000 = <b>1.6 s</b> (slide 30: dedicated circuit).","from":[{"s":"F14","qn":"Q1.2","pg":199}]},{"id":"F14-2-1","ch":1,"sl":"46","tp":"Terminals to router: delays","t":"short","q":"M terminals are attached to a router, each with its own dedicated line. Each terminal is <b>2500 m</b> from the router, the line rate is <b>10 Mbps</b>, packets are <b>12,500 bytes</b>, propagation speed 2.5×10<sup>8</sup> m/s.<br>a. Transmission time of a packet at any terminal?<br>b. Propagation time of a packet from one terminal to another terminal (end-to-end)?","a":"a. L/R = 12,500×8 / 10<sup>7</sup> = <b>0.01 s = 10 ms</b><br>b. Terminal → router → terminal = 2 × 2500 m: 5000 / 2.5×10<sup>8</sup> = <b>2×10<sup>-5</sup> s = 20 µs</b>","e":"Chapter 1, slide 46: d<sub>trans</sub> = L/R, d<sub>prop</sub> = d/s.","from":[{"s":"F14","qn":"Q2.1","pg":201}]},{"id":"M15-1-2","ch":1,"sl":"62–64","tp":"Header overhead percentage","t":"mcq","q":"An application generates chunks of <b>60 bytes</b> of data every 35 ms; each chunk is encapsulated in a TCP segment and then an IP datagram (20-byte headers each). What percentage of the datagram is application data?","o":["60%","20%","58.3%","40%"],"a":0,"e":"Chapter 1, slides 62–64 (encapsulation): each layer adds its own header. Datagram = 60 data + 20 TCP header + 20 IP header = 100 bytes → 60/100 = <b>60%</b>.","from":[{"s":"M15","qn":"Q1.2","pg":258}]},{"id":"M26-1-6","ch":2,"sl":"12–13","tp":"App requirements — file transfer","t":"mcq","q":"The applications of file transfer over internet requires one of the following to be more effective:","o":["Low delay","100% of data integrity.","low value of throughput","None of the above"],"a":1,"e":"Chapter 2, slides 12–13 (What transport service does an app need?): some apps, e.g. file transfer and web transactions, require <b>100% reliable data transfer</b> (data integrity). The table shows file transfer: no loss, elastic throughput, not time sensitive.","from":[{"s":"M26","qn":"Q1 A.6","pg":1}]},{"id":"M26-2-1","ch":2,"sl":"27","tp":"HTTP GET with URL parameters","t":"mcq","q":"Which of the following HTTP request methods is used by a client to retrieve data from a server by including data as query parameters appended to the URL?","o":["Post Method","Get Method","Head Method","Put Method"],"a":1,"e":"Chapter 2, slide 27 (Other HTTP request messages): <b>GET method (for sending data to server)</b> — include user data in the URL field of the HTTP GET request message (following a '?'), e.g. www.somesite.com/animalsearch?monkeys&banana. POST puts input in the entity body; HEAD asks for headers only; PUT uploads a new file/object.","from":[{"s":"M26","qn":"Q2 Part1.1","pg":2}]},{"id":"M26-2-2","ch":2,"sl":"29","tp":"HTTP status codes","t":"mcq","q":"Which of the following HTTP status codes indicate that the server could not understand the request message sent by the client?","o":["300","400","404","505"],"a":1,"e":"Chapter 2, slide 29: <b>400 Bad Request</b> — request message not understood by server. 404 Not Found = requested document not found; 505 = HTTP version not supported; 301 = moved permanently.","from":[{"s":"M26","qn":"Q2 Part1.2","pg":2}]},{"id":"M26-2-P2-1","ch":2,"sl":"54, 57","tp":"DNS record types","t":"short","q":"Write the type of DNS record in the blank:<pre>(networkutopia.com, dns1.networkutopia.com, ______)\n(dns1.networkutopia.com, 212.212.212.1, ______)</pre>","a":"(networkutopia.com, dns1.networkutopia.com, <b>NS</b>)<br>(dns1.networkutopia.com, 212.212.212.1, <b>A</b>)","e":"Chapter 2, slide 54 (DNS records): type=<b>NS</b> → name is a domain, value is the hostname of the authoritative name server for that domain; type=<b>A</b> → name is a hostname, value is its IP address. Slide 57 (Getting your info into the DNS) inserts exactly these two records for the startup \"Network Utopia\".","from":[{"s":"M26","qn":"Q2 Part2.1","pg":3},{"s":"MC","qn":"Q2 Part2.1","pg":16}]},{"id":"M26-2-P2-2","ch":2,"sl":"41","tp":"Conditional GET","t":"short","q":"Suppose the HTTP protocol uses a conditional GET request with the header <code>If-Modified-Since: &lt;date&gt;</code>. If the resource on the server <b>has been updated after this date</b>, what will the server response be? Will the data be downloaded, and what is the status code in the response?","a":"The server sends the <b>new (modified) object</b> in the response, so <b>yes, the data is downloaded</b>. Status code: <b>200 OK</b>.","e":"Chapter 2, slide 41 (Conditional GET): if the cached copy is up-to-date the server replies <code>HTTP/1.0 304 Not Modified</code> with no object (no transmission delay). If the object <i>was modified after</i> the given date the server replies <code>HTTP/1.0 200 OK</code> followed by <code>&lt;data&gt;</code>.","from":[{"s":"M26","qn":"Q2 Part2.2","pg":3}]},{"id":"M26-2-P2-3","ch":2,"sl":"36","tp":"Why web caching","t":"short","q":"Why is web caching used? List two reasons.","a":"1- To <b>reduce response time</b> for the client request (the cache is closer to the client).<br>2- To <b>reduce traffic on an institution's access link</b>.<br>(Also: the Internet is dense with caches, which lets \"poor\" content providers deliver content more effectively.)","e":"Chapter 2, slide 36 (Web caches — Why Web caching?) lists exactly these reasons.","from":[{"s":"M26","qn":"Q2 Part2.3","pg":3},{"s":"MC","qn":"Q2 Part2.2","pg":16}]},{"id":"Q125-2-3","ch":2,"sl":"28–29, 24","tp":"Read an HTTP response (Wireshark)","t":"short","q":"The following was captured by Wireshark:<pre>HTTP/1.1 200 OK\\r\\n\nDate: Tue, 23 SEP 2025 17:11:13 GMT\\r\\n\nServer: Apache/2.4.6 (CentOS) ...\\r\\n\nContent-Length: 209\\r\\n\nKeep-Alive: timeout=5, max=100\\r\\n\nConnection: Keep-Alive\\r\\n\nContent-Type: text/html; charset=iso-8859-1\\r\\n\n\\r\\n</pre>a) Was the server able to successfully find the file or not?<br>b) Is the connection non-persistent or persistent? How did you get your answer?","a":"a) <b>Yes</b> — the status line is <code>HTTP/1.1 200 OK</code> (request succeeded, requested object follows).<br>b) <b>Persistent</b> — the headers <code>Connection: Keep-Alive</code> and <code>Keep-Alive: timeout=5, max=100</code> tell the client the server keeps the TCP connection open (HTTP/1.1 is persistent by default). A non-persistent reply would say <code>Connection: close</code>.","e":"Chapter 2, slide 28 (HTTP response message: status line + header lines), slide 29 (200 OK), slide 24 (Persistent HTTP — server leaves the connection open after sending the response).","from":[{"s":"Q125","qn":"Q2.3","pg":73}]},{"id":"Q125-2-4","ch":2,"sl":"54","tp":"DNS NS and CNAME records","t":"short","q":"For each DNS record type, fill in what Name and Value hold: <b>NS</b>, <b>CNAME</b>.","a":"<b>NS</b>: Name = a <b>domain</b> (e.g. foo.com); Value = <b>hostname of the authoritative name server</b> for this domain.<br><b>CNAME</b>: Name = an <b>alias name</b> for some \"canonical\" (real) name; Value = the <b>canonical name</b> (e.g. www.ibm.com is really servereast.backup2.ibm.com).","e":"Chapter 2, slide 54 (DNS records): RR format (name, value, type, ttl); type=A, NS, CNAME, MX definitions.","from":[{"s":"Q125","qn":"Q2.4","pg":73}]},{"id":"MA-1-11","ch":2,"sl":"8–10","tp":"Sockets","t":"mcq","q":"Which is correct regards the concept of \"Socket\"?","o":["Serve as interface between Application layer and transport layer within the network stack.","Works as a \"door\" through which the processes at the end systems send/receive messages.","It is defined by using a combination of IP addresses and port number.","There are two types of sockets: TCP reliable connection-oriented socket and UDP connectionless socket.","All of the above."],"a":4,"e":"Chapter 2, slide 9 (Sockets): a process sends/receives messages to/from its socket; the socket is analogous to a <b>door</b> between the application process and the transport protocol. Slide 10: the identifier includes both the <b>IP address and port number</b>. Slide 14 / Chapter 3: the two transport services are TCP (reliable, connection-oriented) and UDP (connectionless), giving the two socket types.","from":[{"s":"MA","qn":"Q1.11","pg":2}]},{"id":"MA-1-12","ch":2,"sl":"12–13","tp":"App requirements — VoIP timing","t":"mcq","q":"The applications of voice over IP (VOIP) require one of the following to be more effective:","o":["Low delay","100% of data integrity.","low value of throughput","None of the above"],"a":0,"e":"Chapter 2, slide 12: some apps (e.g. Internet telephony, interactive games) require <b>low delay</b> (timing) to be effective. Slide 13: real-time audio/video is loss-tolerant and time sensitive (10s of msec).","from":[{"s":"MA","qn":"Q1.12","pg":2}]},{"id":"MA-1-14","ch":2,"sl":"18–19","tp":"HTTP overview","t":"mcq","q":"Which of the following is correct about the HTTP protocol?","o":["Web's application-layer protocol used for sending and receiving web transactions.","Works based on the peer-to-peer communication model.","Stateful protocol; maintains some information about past client requests.","Uses TCP or UDP protocol for sending and receiving data.","All of the above are correct."],"a":0,"e":"Chapter 2, slide 18: HTTP is the Web's application-layer protocol, using the <b>client/server</b> model (not P2P). Slide 19: HTTP uses <b>TCP</b>, and HTTP is <b>stateless</b> — the server maintains no information about past client requests.","from":[{"s":"MA","qn":"Q1.14","pg":2},{"s":"MC","qn":"Q1 A.8","pg":15}]},{"id":"MA-2-8","ch":2,"sl":"50","tp":"Local DNS server","t":"mcq","q":"Which of the following DNS server that replies to the local host's DNS query, by contacting other DNS servers to answer the query?","o":["Local DNS server","Top Level Domain (TLD) servers","Authoritative DNS server","DNS root servers"],"a":0,"e":"Chapter 2, slide 50 (Local DNS name servers): when a host makes a DNS query it is sent to its <b>local DNS server</b>, which returns the reply either from its cache or by <b>forwarding the request into the DNS hierarchy</b> (root → TLD → authoritative) for resolution.","from":[{"s":"MA","qn":"Q2 Part1.8","pg":4},{"s":"MC","qn":"Q2 Part1.8","pg":13}]},{"id":"MA-2-P2","ch":2,"sl":"51, 54","tp":"DNS iterative query steps","t":"short","q":"The figure shows a DNS <b>iterative</b> query: the requesting host cse.nyu.edu wants to visit gaia.cs.umass.edu but doesn't know its IP address. No DNS records are cached in any DNS server. Steps: 1 host→local DNS (dns.nyu.edu), 2–3 local↔root, 4–5 local↔TLD, 6–7 local↔authoritative (dns.umass.edu), 8 local→host.<br>1) When the local DNS server receives the request, where does it check first?<br>2) Which DNS server is provided in the response of the root DNS server in step 3?<br>3) Which DNS server is provided in the response of the TLD DNS server in step 5?<br>4) Between steps 6 and 7 the authoritative DNS server responds with the IP we want. What type of DNS record is returned?","img":"MA-2-P2.jpg","a":"1) It checks its own <b>local cache</b> first; since nothing is cached, it sends the query to a <b>root DNS server</b> (step 2).<br>2) The root returns the <b>TLD DNS server</b> responsible for <b>.edu</b>.<br>3) The TLD returns the <b>authoritative DNS server</b> for umass.edu (dns.umass.edu).<br>4) A <b>type A</b> record (hostname → IP address).","e":"Chapter 2, slide 50: the local DNS server answers from its cache of recent translations, or forwards the request into the hierarchy. Slide 51 (iterated query): each contacted server replies with the name of the next server to contact — \"I don't know this name, but ask this server\": root → TLD (.edu) → authoritative (umass.edu). Slide 54: type=A gives hostname → IP address.","from":[{"s":"MA","qn":"Q2 Part2","pg":4}]},{"id":"MB-1-6","ch":2,"sl":"12–13","tp":"Loss-tolerant apps","t":"tf","q":"Streaming video and audio applications are loss-tolerant applications, meaning they accept some loss of their data.","a":0,"e":"Chapter 2, slides 12–13: some apps (e.g. audio, real-time and stored audio/video) can tolerate some loss. <b>True</b>.","from":[{"s":"MB","qn":"Q1 T/F 6","pg":7},{"s":"FE","qn":"Q1 B.1","pg":161}]},{"id":"MB-2-5","ch":2,"sl":"41","tp":"Conditional GET purpose","t":"mcq","q":"What is the purpose of the <i>conditional</i> HTTP GET request message?","o":["To allow a server to only send the requested object to the client if the client has never requested that object before.","To allow a server to only send the requested object to the client if the server is not overloaded.","To allow a server to only send the requested object to the client if the client is authorized to receive that object.","To allow a server to only send the requested object to the client if this object has changed since the server last sent this object to the client."],"a":3,"e":"Chapter 2, slide 41 (Conditional GET): goal — don't send the object if the cache has an up-to-date cached version. The client sends <code>If-modified-since: &lt;date&gt;</code>; the server replies <code>304 Not Modified</code> with no object if unchanged, or <code>200 OK</code> with the object if it was modified.","from":[{"s":"MB","qn":"Q2.5","pg":8},{"s":"FE","qn":"Q1 A.7","pg":161},{"s":"BB3","qn":"Q6","pg":90}]},{"id":"MB-2-6","ch":2,"sl":"29","tp":"HTTP 400 Bad Request","t":"mcq","q":"Which of the following response codes in an HTTP response message means that the request is bad and not understood by the server?","o":["200","404","400","505"],"a":2,"e":"Chapter 2, slide 29: <b>400 Bad Request</b> — request msg not understood by server. 200 OK = success; 404 Not Found; 505 HTTP Version Not Supported.","from":[{"s":"MB","qn":"Q2.6","pg":8},{"s":"FE","qn":"Q1 A.6","pg":167}]},{"id":"MB-4","ch":2,"sl":"20–24, 50","tp":"HTTP response time with DNS (RTT₀, RTT_HTTP)","t":"short","q":"You click a link to obtain a Web page. The IP address for the URL is not cached locally, so a DNS lookup is needed. Only one DNS server, the local DNS cache, is visited, with RTT<sub>0</sub> = <b>3 msec</b>. The page contains exactly one small HTML object. The RTT between the local host and the Web server is RTT<sub>HTTP</sub> = <b>27 msec</b>.<br>1) Assuming zero transmission time for the HTML object, how much time elapses from clicking the link until the client receives the object?<br>2) The HTML object references 10 very small objects on the same server. Neglecting transmission times, how much time elapses until the base object and all 10 objects are received, with <b>non-persistent HTTP and no parallel</b> TCP connections?<br>3) Same, but the client supports a maximum of <b>5 parallel</b> TCP connections, with <b>non-persistent</b> HTTP.<br>4) Same, but with <b>5 parallel</b> connections and <b>persistent</b> HTTP.<br>5) Which is fastest: non-persistent serial, non-persistent parallel, or persistent parallel?","img":"MB-4.jpg","a":"1) RTT<sub>0</sub> + 2·RTT<sub>HTTP</sub> = 3 + 54 = <b>57 msec</b><br>2) 57 + 10 × 2·RTT<sub>HTTP</sub> = 57 + 540 = <b>597 msec</b><br>3) 57 + ⌈10/5⌉ × 2·RTT<sub>HTTP</sub> = 57 + 2×54 = <b>165 msec</b><br>4) 57 + ⌈10/5⌉ × RTT<sub>HTTP</sub> = 57 + 2×27 = <b>111 msec</b><br>5) <b>Persistent-parallel</b> is the fastest.","e":"Chapter 2, slide 23: non-persistent HTTP response time = 2RTT + file transmission time (one RTT to set up the TCP connection, one RTT for the request and first bytes of the response). Slide 24: non-persistent HTTP needs 2 RTTs per object; persistent HTTP leaves the connection open so each later object needs only one RTT. The DNS lookup (slide 50) adds RTT<sub>0</sub> once. With 5 parallel connections, the 10 objects are fetched in ⌈10/5⌉ = 2 rounds.","from":[{"s":"MB","qn":"Q4","pg":9}]},{"id":"MC-2-5","ch":2,"sl":"29","tp":"HTTP 505","t":"mcq","q":"Which of the following codes in HTTP response status codes indicates that the HTTP Version Not Supported by the server?","o":["200 OK","404","400","505"],"a":3,"e":"Chapter 2, slide 29 (HTTP response status codes): <b>505 HTTP Version Not Supported</b>. 200 OK = request succeeded; 400 Bad Request = not understood; 404 Not Found = requested document not found on this server.","from":[{"s":"MC","qn":"Q2 Part1.5","pg":13}]},{"id":"MC-1-C","ch":2,"sl":"6–7","tp":"Client-server vs P2P","t":"short","q":"Compare the Client-Server paradigm and the Peer-to-Peer (P2P) paradigm based on: role of each end system in providing service; need for a centralized server to transfer data; direct connection between end systems; scalability; security and management.","a":"<div class=\"tbl\"><table class=\"mini\"><tr><th>Criteria</th><th>Client-Server</th><th>P2P</th></tr><tr><td>Role of each end system</td><td>Server provides the service; clients only request it</td><td>Each peer both requests service and provides service to other peers</td></tr><tr><td>Centralized server needed</td><td>Yes — always-on host with a permanent IP address</td><td>No always-on server</td></tr><tr><td>Direct connection between end systems</td><td>No — clients do not communicate directly with each other</td><td>Yes — arbitrary end systems directly communicate</td></tr><tr><td>Scalability</td><td>Limited by the server (scaled with data centers)</td><td>Self-scalable — new peers bring new service capacity as well as new demands</td></tr><tr><td>Security &amp; management</td><td>Easier, centralized at the server</td><td>Complex management; peers are intermittently connected and change IP addresses</td></tr></table></div>","e":"Chapter 2, slide 6 (Client-server paradigm): server = always-on host, permanent IP address, often in data centers for scaling; clients contact the server, may be intermittently connected, may have dynamic IPs and do not communicate directly with each other. Slide 7 (Peer-peer architecture): no always-on server, arbitrary end systems directly communicate, peers request and provide service, self scalability, peers intermittently connected and change IP addresses → complex management.","from":[{"s":"MC","qn":"Q1 C","pg":14}]},{"id":"MC-1-A7","ch":2,"sl":"12–13","tp":"App requirements — interactive games","t":"mcq","q":"The applications of <b>interactive gaming</b> on the internet require one of the following to be more effective:","o":["Low delay","100% of data integrity.","low value of throughput","None of the above"],"a":0,"e":"Chapter 2, slide 12 (timing): some apps (e.g. Internet telephony, <b>interactive games</b>) require low delay to be \"effective\". Slide 13 lists interactive games as loss-tolerant and time sensitive (10s msec).","from":[{"s":"MC","qn":"Q1 A.7","pg":15}]},{"id":"MC-2-P2-3","ch":2,"sl":"17, 20–24","tp":"HTTP requests per page; persistent vs non-persistent","t":"short","q":"Suppose a user requests a Web page that consists of some text and five images.<br>A) How many request messages will be sent?<br>B) How many response messages will he receive?<br>C) In general, which type of HTTP connection is more efficient to download web pages and their contents: persistent or non-persistent? Explain why.","a":"A) <b>6</b> request messages (1 base HTML file + 5 images).<br>B) <b>6</b> response messages (one per object).<br>C) <b>Persistent HTTP</b> is more efficient: the server leaves the TCP connection open after sending a response, so the remaining objects are sent over the same connection — no new TCP connection (extra RTT) and no OS overhead per object; the client can request each referenced object as soon as it finds it (as little as one RTT for all the referenced objects).","e":"Chapter 2, slide 17: a web page consists of a base HTML file plus several referenced objects, each addressable by a URL; HTTP uses one request/response pair per object. Slide 24 (Persistent HTTP): non-persistent HTTP requires 2 RTTs per object plus OS overhead for each TCP connection; persistent HTTP keeps the connection open, cutting response time.","from":[{"s":"MC","qn":"Q2 Part2.3","pg":16}]},{"id":"MD-2-1","ch":2,"sl":"29","tp":"HTTP 400","t":"mcq","q":"A generic error code indicating that the request could not be understood by the server.","o":["301","400","505","404"],"a":1,"e":"Chapter 2, slide 29: 400 Bad Request — request msg not understood by server.","from":[{"s":"MD","qn":"Q2.1","pg":70}]},{"id":"MD-2-2","ch":2,"sl":"12–13","tp":"Internet telephony needs low delay","t":"mcq","q":"Internet telephony, to be effective, requires:","o":["Low delay","No loss","Encryption","None of the above"],"a":0,"e":"Chapter 2, slide 12 (timing): some apps (e.g. Internet telephony, interactive games) require low delay to be \"effective\"; they tolerate some loss (slide 13).","from":[{"s":"MD","qn":"Q2.2","pg":70}]},{"id":"MD-2-3","ch":2,"sl":"20","tp":"Non-persistent HTTP definition","t":"mcq","q":"At most one object sent over a TCP connection. Connection then closed. Multiple connections to download multiple objects.","o":["Non-Persistent HTTP","Persistent HTTP","Conditional Get","None of the above"],"a":0,"e":"Chapter 2, slide 20 (HTTP connections: two types): non-persistent HTTP — TCP connection opened, at most one object sent over it, connection closed; downloading multiple objects requires multiple connections.","from":[{"s":"MD","qn":"Q2.3","pg":70}]},{"id":"MD-2-4","ch":2,"sl":"54, 57","tp":"DNS NS record","t":"mcq","q":"What is the correct type for the DNS Resource Record (networkutopia.com, dns1.networkutopia.com, ?)","o":["A","MX","NS","CNAME"],"a":2,"e":"Chapter 2, slide 54: type=NS — name is a domain (networkutopia.com), value is the hostname of the authoritative name server for this domain (dns1.networkutopia.com). Slide 57 uses this exact record.","from":[{"s":"MD","qn":"Q2.4","pg":70}]},{"id":"MD-2-5","ch":2,"sl":"35–36","tp":"Web caching benefits","t":"mcq","q":"By using Web caching ______.","o":["it is possible to reduce response time for client request","it is possible to reduce traffic on an institution's access link","the cache acts as both client and server","All of the above responses are correct"],"a":3,"e":"Chapter 2, slide 36 (Web caches aka proxy servers): the Web cache acts as both client and server (server for the original requesting client, client to the origin server). Why Web caching? Reduce response time for client request; reduce traffic on an institution's access link.","from":[{"s":"MD","qn":"Q2.5","pg":71},{"s":"MG","qn":"Q1 Part2.2","pg":109},{"s":"M23","qn":"Q2.6","pg":123},{"s":"M23J","qn":"Q1.8","pg":127},{"s":"MK","qn":"Q1.5","pg":153}]},{"id":"MD-2-6","ch":2,"sl":"8","tp":"Process definition","t":"mcq","q":"______ is a program running within a host.","o":["Protocol","Socket","Process","Identifier"],"a":2,"e":"Chapter 2, slide 8 (Processes communicating): <b>process</b>: program running within a host.","from":[{"s":"MD","qn":"Q2.6","pg":71}]},{"id":"MD-3","ch":2,"sl":"23, 50–52","tp":"Protocols & time with 3 DNS servers","t":"short","q":"You want to retrieve a Web document at a given URL. The IP address of the URL is initially unknown (not cached in your local host).<br>1) What are the application-layer protocols needed in this scenario?<br>2) Suppose 3 DNS servers are visited before your host receives the IP address from DNS; the successive visits incur RTTs of RTT<sub>1</sub>, RTT<sub>2</sub> and RTT<sub>3</sub>. The Web page contains exactly one small HTML object. Let RTT<sub>0</sub> be the RTT between the local host and the server containing the object. Assuming zero transmission time of the object, how much time elapses from clicking the link until the client receives the object?","a":"1) <b>DNS</b> (to resolve the hostname to an IP address) and <b>HTTP</b> (to fetch the document).<br>2) Time = <b>RTT<sub>1</sub> + RTT<sub>2</sub> + RTT<sub>3</sub> + 2·RTT<sub>0</sub></b> — the DNS lookups, then one RTT to set up the TCP connection and one RTT to request and receive the object.","e":"Chapter 2, slides 50–52: the hostname must be resolved through DNS before the browser can contact the server. Slide 23: non-persistent HTTP response time = 2RTT + transmission time (zero here).","from":[{"s":"MD","qn":"Q3","pg":71}]},{"id":"ME-1-5","ch":2,"sl":"54","tp":"DNS RR format","t":"tf","q":"In a DNS server, a resource record (RR) is a four-tuple that contains the fields (Name, Value, Type, TTL). The meaning of Name and Value depends on Type.","a":0,"e":"Chapter 2, slide 54: RR format: (name, value, type, ttl); e.g. for type=A the name is a hostname and value an IP address, for type=NS the name is a domain… So the meaning depends on the type. <b>True</b>.","from":[{"s":"ME","qn":"Q1.5","pg":94}]},{"id":"ME-1-6","ch":2,"sl":"49","tp":"TLD servers","t":"mcq","q":"The type of DNS server that deals with edu, com, net, org and other similar extensions is called:","o":["Root DNS servers","Top-level DNS (TLD) servers","Authoritative DNS servers","Local DNS servers"],"a":1,"e":"Chapter 2, slide 49: Top-Level Domain (TLD) servers — responsible for .com, .org, .net, .edu, .aero, .jobs, .museums, and all top-level country domains (.cn, .uk, .fr, .ca, .jp).","from":[{"s":"ME","qn":"Q1.6","pg":94}]},{"id":"ME-1-10","ch":2,"sl":"41","tp":"Conditional GET → 200 OK","t":"mcq","q":"A client sends an HTTP request message with the <code>If-modified-since:</code> header. The object on the server <b>has changed</b> since the client last retrieved it. The server will send a response with status code:","o":["200 OK","404 Not Found","304 Not Modified","none of the above"],"a":0,"e":"Chapter 2, slide 41: if the object was modified after the given date, the server replies <code>HTTP/1.0 200 OK</code> with the data; if not modified it replies <code>304 Not Modified</code> with no object.","from":[{"s":"ME","qn":"Q1.10","pg":95},{"s":"MG","qn":"Q1 Part2.3","pg":109},{"s":"M23J","qn":"Q1.10","pg":127}]},{"id":"ME-1-12","ch":2,"sl":"31–34","tp":"Cookies keep state","t":"mcq","q":"To allow an HTTP server to keep client state, the technique used is:","o":["Web caches","Cookies","HTTP persistent connection","All above"],"a":1,"e":"Chapter 2, slide 31: HTTP GET/response interaction is stateless. Slide 32: Web sites and the client browser use <b>cookies</b> to maintain some state between transactions. Slide 34: cookies can be used for authorization, shopping carts, recommendations, user session state.","from":[{"s":"ME","qn":"Q1.12","pg":95},{"s":"F15","qn":"Q1.2","pg":223}]},{"id":"ME-2-A","ch":2,"sl":"13, 15","tp":"App requirements table","t":"short","q":"Fill the table for <b>File transfer</b>, <b>Web</b> and <b>Mail</b>: Loss tolerance (Yes/No), Time sensitive (Yes/No), Transport protocol (TCP/UDP), Application-layer protocol name.","a":"<div class=\"tbl\"><table class=\"mini\"><tr><th></th><th>Loss tolerant</th><th>Time sensitive</th><th>Transport</th><th>App protocol</th></tr><tr><td>File transfer</td><td>No</td><td>No</td><td>TCP</td><td>FTP</td></tr><tr><td>Web</td><td>No</td><td>No</td><td>TCP (or UDP for HTTP/3)</td><td>HTTP</td></tr><tr><td>Mail</td><td>No</td><td>No</td><td>TCP</td><td>SMTP</td></tr></table></div>","e":"Chapter 2, slide 13 (Transport service requirements: common apps): file transfer/download, e-mail and Web documents — no loss, elastic throughput, not time sensitive. Slide 15 (Internet applications and transport protocols): file transfer FTP [RFC 959] over TCP; e-mail SMTP [RFC 5321] over TCP; Web HTTP 1.1 over TCP (HTTP/3 over UDP).","from":[{"s":"ME","qn":"Q2 A","pg":97}]},{"id":"ME-3-A","ch":2,"sl":"24–26, 41","tp":"Analyze an HTTP GET request","t":"short","q":"<pre>GET /ross/interactive/welcom.htm HTTP/1.1\nHost: gaia.cs.umass.edu\nAccept: text/plain, text/html, text/xml, image/png, image/jpeg, application/*, */*\nAccept-Language: en-us, en-gb;q=0.6, en;q=0.1, fr, fr-ch, de, ar\nIf-Modified-Since: Mon, 13 Nov 2013 09:00:58 EST\nUser Agent: Mozilla/5.0 (Windows NT 6.1; WOW64; rv:10.0.2) Firefox/10.0.2\nKeep-Alive: 115\\r\\n\nConnection: keep-alive\\r\\n\n\\r\\n</pre>1. What is the name of the file being retrieved?<br>2. Does the client already have a (possibly out-of-date) copy of the file? Explain.<br>3. Is the HTTP connection persistent or non-persistent?<br>4. Does the request message have a body? If yes, specify.<br>5. If the requested file has <b>4 embedded images</b>, how many RTTs are required to retrieve the base file and the images with <b>persistent</b> HTTP (no pipelining)?<br>6. True or False: (a) The <code>Date:</code> header in an HTTP response indicates when the object in the response was last modified. (b) HTTP response messages never have an empty message body.","a":"1. <b>/ross/interactive/welcom.htm</b> (on host gaia.cs.umass.edu).<br>2. <b>Yes</b> — the request contains an <code>If-Modified-Since</code> header, which is only sent when the client has a cached copy (conditional GET).<br>3. <b>Persistent</b> — <code>Connection: keep-alive</code> (and HTTP/1.1).<br>4. <b>No</b> — a GET request has an empty entity body (the blank line \\r\\n ends the message); data would go in the body only with POST.<br>5. <b>6 RTT</b> = 1 RTT TCP setup + 1 RTT base file + 4 × 1 RTT for the images.<br>6. (a) <b>False</b> — Date is when the response was created/sent; <code>Last-Modified</code> gives the object's modification time. (b) <b>False</b> — e.g. a <code>304 Not Modified</code> reply (or a reply to HEAD) has an empty body.","e":"Chapter 2, slide 25 (HTTP request message: request line, header lines, blank line), slide 26 (general format with entity body), slide 27 (POST uses the body), slide 24 (persistent HTTP: one RTT per referenced object after the connection is open), slide 41 (conditional GET, 304 Not Modified has no object).","from":[{"s":"ME","qn":"Q3 A","pg":97}]},{"id":"M23-1-4","ch":2,"sl":"28","tp":"Date header","t":"tf","q":"The \"Date\" header in an HTTP response message indicates when the object in the response was last modified.","a":1,"e":"Chapter 2, slide 28 (HTTP response message): <code>Date:</code> is when the response was generated; <code>Last-Modified:</code> is when the object was last changed. <b>False</b>.","from":[{"s":"ME","qn":"Q3 A.6a","pg":98},{"s":"M23","qn":"Q1.4","pg":122}]},{"id":"M23-1-5","ch":2,"sl":"28–29, 41","tp":"Empty response body","t":"tf","q":"HTTP response messages never have an empty message body.","a":1,"e":"Chapter 2, slide 41: a <code>304 Not Modified</code> response carries no object (empty body). Responses to HEAD also have no body. <b>False</b>.","from":[{"s":"ME","qn":"Q3 A.6b","pg":98},{"s":"M23","qn":"Q1.5","pg":122}]},{"id":"FA-1-9","ch":2,"sl":"14","tp":"What TCP does NOT provide","t":"mcq","q":"One of the following is <b>not</b> included in the description of the TCP protocol:","o":["A reliable transport protocol.","Setup a connection between sender and receiver before data being transmitted.","Provide congestion control.","Provide flow control.","Provides minimum throughput guarantee.","All of the above"],"a":4,"e":"Chapter 2, slide 14 (Internet transport protocols services): TCP service = reliable transport, flow control, congestion control, connection-oriented (setup required between client and server). It does <b>not</b> provide timing, <b>minimum throughput guarantee</b>, or security.","from":[{"s":"MF","qn":"Q1.4","pg":102},{"s":"FA","qn":"Q1 A.9","pg":30},{"s":"FF","qn":"Q1.9","pg":279}]},{"id":"MF-1-3","ch":2,"sl":"18–19","tp":"HTTP description","t":"mcq","q":"One of the following describes the HTTP protocol:","o":["HTTP is a stateless protocol — does not maintain the history of its past transactions.","Uses port number 80 for its socket connection.","Is a client-server model.","All the above.","None of the above."],"a":3,"e":"Chapter 2, slide 18: HTTP uses the client/server model. Slide 19: client initiates a TCP connection (creates socket) to the server, <b>port 80</b>; HTTP is <b>stateless</b> — the server maintains no information about past client requests.","from":[{"s":"MF","qn":"Q1.3","pg":102}]},{"id":"MF-4","ch":2,"sl":"23–24, 50–51, 54","tp":"HTTP timing with DNS (RTT₀=2, RTT_HTTP=30)","t":"short","q":"You click a link; its IP address isn't cached, so a DNS lookup is needed. Only the local DNS cache is visited, RTT<sub>0</sub> = <b>2 msec</b>. The page has exactly one small HTML object. RTT<sub>HTTP</sub> = <b>30 msec</b>.<br>1) Assuming zero transmission time, how much time (msec) elapses from the click until the client receives the object?<br>2) The HTML object references <b>3</b> very small objects on the same server. With <b>non-persistent</b> HTTP and <b>no parallel</b> connections, how long until all are received?<br>3) Same 3 objects, but with up to <b>5 parallel</b> TCP connections and <b>persistent</b> HTTP?<br>4) Which type of DNS record is needed in this scenario? (A) A (B) NS (C) CNAME (D) MX<br>5) If there are other DNS servers (TLD, root, authoritative) and the IP address is not cached in the local DNS server, where does the local DNS server check first? (A) Local DNS server (B) DNS TLD (C) DNS root (D) DNS authoritative","img":"MF-4.jpg","a":"1) RTT<sub>0</sub> + 2·RTT<sub>HTTP</sub> = 2 + 60 = <b>62 msec</b><br>2) 62 + 3 × 2·RTT<sub>HTTP</sub> = 62 + 180 = <b>242 msec</b><br>3) 62 + 1 × RTT<sub>HTTP</sub> = 62 + 30 = <b>92 msec</b> (all 3 requested at once over the open connections)<br>4) <b>A</b> — hostname → IP address<br>5) <b>C — DNS root</b> (the query goes into the hierarchy starting at a root server)","e":"Chapter 2, slide 23: non-persistent response time = 2RTT + transmission time. Slide 24: persistent HTTP needs one RTT per (round of) referenced objects. Slides 50–51: the local DNS server answers from its cache or forwards the query into the hierarchy — root → TLD → authoritative. Slide 54: type A holds the hostname-to-IP mapping the browser needs.","from":[{"s":"MF","qn":"Q4","pg":103}]},{"id":"MG-P2-1","ch":2,"sl":"49, 57","tp":"TLD knows authoritative server's IP","t":"tf","q":"The .edu TLD name server knows the IP address of the authoritative name server for imamu.edu.","a":0,"e":"Chapter 2, slide 57 (Getting your info into the DNS): when a domain is registered, the registrar inserts <b>both</b> an NS record and an A record into the TLD server — e.g. (networkutopia.com, dns1.networkutopia.com, NS) and (dns1.networkutopia.com, 212.212.212.1, A). So the TLD server knows the name <i>and</i> the IP address of the authoritative server. <b>True</b>.<br><i>Note:</i> one photographed copy has \"False\" circled, but the graded January 2023 midterm marks <b>True</b> as correct, matching the slides.","from":[{"s":"MG","qn":"Q1 Part2.1","pg":109},{"s":"M23J","qn":"Q1.7","pg":127}]},{"id":"MG-P2-4","ch":2,"sl":"46, 49","tp":"Top-level domain in a URL","t":"mcq","q":"What part of the URL http://www.cisco.com/index.html represents the top-level DNS domain?","o":[".com","www","http","index"],"a":0,"e":"Chapter 2, slide 46 (DNS: a distributed, hierarchical database): Root → .com/.org/.edu TLD servers → authoritative servers (amazon.com, …). Slide 49: TLD servers are responsible for .com, .org, .net, .edu… so <b>.com</b> is the top-level domain.","from":[{"s":"MG","qn":"Q1 Part2.4","pg":109}]},{"id":"MG-P2-5","ch":2,"sl":"11","tp":"Application-layer protocol defines","t":"mcq","q":"What is the main characteristic of the application layer of the TCP/IP model?","o":["responsibility for logical addressing","responsibility for physical addressing","definition of the type, syntax and semantics of the exchanged messages","establishing window size"],"a":2,"e":"Chapter 2, slide 11: an application-layer protocol defines the <b>types</b> of messages exchanged, the message <b>syntax</b> (fields and how they are delineated), the message <b>semantics</b> (meaning of information in fields), and rules for when/how processes send and respond to messages.","from":[{"s":"MG","qn":"Q1 Part2.5","pg":109}]},{"id":"MG-P2-6","ch":2,"sl":"25, 27","tp":"GET requests data","t":"mcq","q":"What message type is used by an HTTP client to request data from a web server?","o":["GET","POST","PUT","ACK"],"a":0,"e":"Chapter 2, slides 25 and 27: the request line <code>GET /index.html HTTP/1.1</code> asks the server for an object. POST sends form input; PUT uploads a file; ACK is not an HTTP method.","from":[{"s":"MG","qn":"Q1 Part2.6","pg":109}]},{"id":"M23J-3","ch":2,"sl":"23–24, 54","tp":"Page with 7 objects (neom.com)","t":"short","q":"A DNS lookup for www.neom.com takes <b>30 msec</b>. The webpage (HTML file) contains <b>7 other objects</b> on the same server. Assume zero transmission time and <b>15 msec</b> to request and receive (RTT) one object. How much time elapses from the click until the client receives the objects with:<br>a. Non-persistent HTTP (no parallel TCP connections)?<br>b. Persistent HTTP?<br>c. Which DNS record type is needed? (A / NS / CNAME / MX)","a":"a. 8 objects × 2 RTT = 16 RTT → 30 + 16 × 15 = <b>270 msec</b><br>b. 1 RTT (TCP setup) + 8 × 1 RTT = 9 RTT → 30 + 9 × 15 = <b>165 msec</b><br>c. <b>A</b> (hostname → IP address)","e":"Chapter 2, slide 23 (2 RTTs per object with non-persistent HTTP), slide 24 (persistent HTTP: one RTT per referenced object after the first connection), slide 54 (type A record).","from":[{"s":"MG","qn":"Q2 Part1","pg":113},{"s":"M23J","qn":"Q3","pg":129}]},{"id":"MH-1-4","ch":2,"sl":"12–13","tp":"Netflix/Skype/Zoom requirements","t":"mcq","q":"Which of the following is TRUE about the applications Netflix, Skype and Zoom?","o":["They are elastic apps","They are rate-sensitive apps","They are loss-tolerant apps","Both B and C"],"a":3,"e":"Chapter 2, slide 12: some apps (e.g. multimedia) require a minimum amount of throughput to be effective (rate-sensitive); other apps (\"elastic apps\") make use of whatever throughput they get. Slide 13: real-time audio/video and streaming audio/video are loss-tolerant, with throughput needs of e.g. 10 kbps–5 Mbps.","from":[{"s":"MH","qn":"Q1.4","pg":116}]},{"id":"MH-1-5","ch":2,"sl":"27","tp":"PUT uploads a file","t":"mcq","q":"Which HTTP method would be used by the Facebook (or Instagram) app to upload a new image to the server?","o":["HEAD","POST","PUT","GET"],"a":2,"e":"Chapter 2, slide 27 (Other HTTP request messages): <b>PUT</b> method — uploads a new file (object) to the server; completely replaces the file that exists at the specified URL with the content in the entity body of the request. (POST is for form input.)","from":[{"s":"MH","qn":"Q1.5","pg":117},{"s":"M23","qn":"Q2.5","pg":123},{"s":"M22S","qn":"Q1.6","pg":131}]},{"id":"MH-1-6","ch":2,"sl":"29","tp":"Status code for Not Found","t":"mcq","q":"Which status code would appear in a browser screen that shows: <i>\"HTTP Status ? – Not Found. Description: The origin server did not find a current representation for the target resource…\"</i>","img":"MH-1-6.jpg","o":["200","301","400","404"],"a":3,"e":"Chapter 2, slide 29: <b>404 Not Found</b> — requested document not found on this server.","from":[{"s":"MH","qn":"Q1.6","pg":117}]},{"id":"MH-1-7","ch":2,"sl":"43–44, 18","tp":"Protocols to fetch a homepage","t":"mcq","q":"Consider a browser that retrieves the homepage of amazon.com. What application-layer protocols are needed in this scenario?","o":["HTTP only","DNS only","Both HTTP and DNS","Both HTTP and IP"],"a":2,"e":"Chapter 2, slides 43–44: DNS translates www.amazon.com to an IP address; slide 18: HTTP then fetches the page. IP is a network-layer protocol, not application-layer.","from":[{"s":"MH","qn":"Q1.7","pg":117},{"s":"M23","qn":"Q2.3","pg":123}]},{"id":"MH-1-8","ch":2,"sl":"53–54","tp":"DNS cache entries expire (TTL)","t":"mcq","q":"DNS resource records are removed from the client's cache when the ______ expires.","o":["TLD","TTL","RTT","None of the above"],"a":1,"e":"Chapter 2, slide 53 (Caching DNS information): cache entries time out (disappear) after some time — the <b>TTL</b>. Slide 54: RR format (name, value, type, ttl).","from":[{"s":"MH","qn":"Q1.8","pg":117}]},{"id":"MH-1-9","ch":2,"sl":"14","tp":"UDP provides none","t":"mcq","q":"A gaming application that uses UDP will have:","o":["Flow control","Connection management","Security guarantees","None of the above"],"a":3,"e":"Chapter 2, slide 14: UDP service is unreliable data transfer and does <b>not</b> provide reliability, flow control, congestion control, timing, throughput guarantee, security, or connection setup.","from":[{"s":"MH","qn":"Q1.9","pg":117}]},{"id":"MH-2","ch":2,"sl":"23–24, 50–52","tp":"DNS chain + HTTP timing (bank.com)","t":"short","q":"A user clicks a link to get an HTML page from bank.com. The IP address isn't cached in the local host, so a DNS lookup is needed; <b>DNS1, DNS2 and DNS3</b> are visited before the host gets the IP. RTTs: RTT<sub>0</sub> (local DNS cache) = <b>5 ms</b>, RTT<sub>1</sub> = <b>10 ms</b>, RTT<sub>2</sub> = <b>7 ms</b>, RTT<sub>3</sub> = <b>40 ms</b>, RTT<sub>HTTP</sub> = <b>35 ms</b>. How much time elapses from the click until the client receives the page?<br>a. The page is HTML text with negligible transmission time; persistent HTTP.<br>b. Same, persistent HTTP, but the IP address is cached in the local host.<br>c. The page references <b>10 objects</b> on the same server with an average transmission time of <b>3 ms</b>; non-persistent HTTP.","img":"MH-2.jpg","a":"DNS time = RTT<sub>0</sub> + RTT<sub>1</sub> + RTT<sub>2</sub> + RTT<sub>3</sub> = 5 + 10 + 7 + 40 = 62 ms.<br>a. 62 + 2·RTT<sub>HTTP</sub> = 62 + 70 = <b>132 ms</b><br>b. No DNS lookup is needed: 2·RTT<sub>HTTP</sub> = <b>70 ms</b> (the graded key wrote RTT<sub>0</sub> + 2·RTT<sub>HTTP</sub> = 75 ms, i.e. it assumed the address was in the <i>local DNS server's</i> cache).<br>c. 62 + 11 × 2·RTT<sub>HTTP</sub> + 11 × 3 = 62 + 770 + 33 = <b>865 ms</b> (base file + 10 objects, each needing its own TCP connection).","e":"Chapter 2, slides 50–52: the local DNS server is asked first, then the hierarchy (each visit costs its RTT). Slide 23: non-persistent HTTP costs 2RTT + transmission time per object. Slide 24: persistent HTTP — the base page still needs 2 RTT (TCP setup + request) the first time.","from":[{"s":"MH","qn":"Q2","pg":119}]},{"id":"M23-2-1","ch":2,"sl":"14","tp":"TCP doesn't give timing/throughput/security","t":"mcq","q":"The base design of the TCP protocol provides:","o":["timing","minimum throughput guarantee","security","None of the above"],"a":3,"e":"Chapter 2, slide 14: TCP does not provide timing, minimum throughput guarantee, or security (security is added by TLS, slide 16 area). It provides reliable transport, flow control, congestion control and connection setup.","from":[{"s":"M23","qn":"Q2.1","pg":122}]},{"id":"M23-2-13","ch":2,"sl":"44","tp":"DNS services","t":"mcq","q":"Which one is <b>not</b> a service provided by DNS?","o":["Translating host names","Mail server aliasing","Load distribution","Congestion control"],"a":3,"e":"Chapter 2, slide 44 (DNS: services, structure): hostname-to-IP-address translation, host aliasing, mail server aliasing, load distribution (replicated Web servers). Congestion control is a TCP (transport-layer) function.","from":[{"s":"M23","qn":"Q2.13","pg":124}]},{"id":"M23-2-14","ch":2,"sl":"54","tp":"MX record","t":"mcq","q":"For a DNS resource record of type MX:","o":["\"value\" is the hostname of the authoritative DNS server for the domain in the \"name\" field.","\"value\" is the canonical name for the alias domain in the \"name\" field.","\"value\" is the name of the mailserver for the domain in the \"name\" field.","\"value\" is the domain of the mailserver in the \"name\" field."],"a":2,"e":"Chapter 2, slide 54: type=MX — value is the name of the SMTP mail server associated with name. (A is NS; B is CNAME.)","from":[{"s":"M23","qn":"Q2.14","pg":124}]},{"id":"M23-3-A","ch":2,"sl":"24–26, 41","tp":"Analyze an HTTP GET request (hello.htm)","t":"short","q":"<pre>GET /ross/interactive/hello.htm HTTP/1.1\nHost: gaia.cs.umass.edu\nAccept: text/plain, text/html, text/xml, image/png, image/jpeg, application/*, */*\nAccept-Language: en-us, en-gb;q=0.6, en;q=0.1, fr, fr-ch, de, ar\nIf-Modified-Since: Mon, 13 Nov 2013 09:00:58 EST\nUser Agent: Mozilla/5.0 (Windows NT 6.1; WOW64; rv:10.0.2) Firefox/10.0.2\nKeep-Alive: 115\\r\\n\nConnection: keep-alive\\r\\n\n\\r\\n</pre>1. Name of the file being retrieved?<br>2. Does the client already have a (possibly out-of-date) copy? Explain.<br>3. Persistent or non-persistent? Explain.<br>4. Does the GET request have a body? If yes, specify.<br>5. If the file has 4 embedded images, how many RTTs are needed to retrieve the base file and images with persistent HTTP 1.1?","a":"1. <b>/ross/interactive/hello.htm</b><br>2. <b>Yes</b> — the <code>If-Modified-Since</code> header means it is a conditional GET for a cached copy.<br>3. <b>Persistent</b> — <code>Connection: keep-alive</code> / HTTP/1.1.<br>4. <b>No</b> — a GET carries no entity body; the message ends with the blank line.<br>5. <b>6 RTT</b> (1 TCP setup + 1 base file + 4 images, one RTT each).","e":"Chapter 2, slides 25–26 (request line, header lines, blank line, body), slide 41 (conditional GET), slide 24 (persistent HTTP).","from":[{"s":"M23","qn":"Q3 A","pg":124}]},{"id":"M23J-1-9","ch":2,"sl":"19","tp":"Why HTTP is stateless","t":"mcq","q":"HTTP is referred to as a stateless protocol because ______.","o":["servers and clients do not maintain open connections","clients do not maintain historic information about transactions with servers","servers maintain no information about past client requests","None of the responses above is correct"],"a":2,"e":"Chapter 2, slide 19: HTTP is \"stateless\" — the <b>server</b> maintains no information about past client requests. (Persistent HTTP does keep connections open, so A is wrong.)","from":[{"s":"M23J","qn":"Q1.9","pg":127}]},{"id":"M22S-1-4","ch":2,"sl":"43","tp":"DNS is application layer","t":"mcq","q":"The Domain Name System (DNS) is implemented as a protocol at the ______ layer.","o":["Transport","Application","Network","Data link"],"a":1,"e":"Chapter 2, slide 43: DNS is an <b>application-layer protocol</b>: hosts and DNS servers communicate to resolve names (address/name translation) — a core Internet function implemented as an application-layer protocol, with complexity at the network's \"edge\".","from":[{"s":"M22S","qn":"Q1.4","pg":131},{"s":"MI","qn":"Q1.1","pg":140}]},{"id":"M22S-1-5","ch":2,"sl":"29","tp":"HTTP 301","t":"mcq","q":"HTTP response status code 301 means that:","o":["Request succeeded","Requested object moved permanently.","Request message not understood by server","HTTP version is not supported by the server."],"a":1,"e":"Chapter 2, slide 29: <b>301 Moved Permanently</b> — requested object moved, new location specified later in this message (in the Location: field).","from":[{"s":"M22S","qn":"Q1.5","pg":131}]},{"id":"M22S-1-7","ch":2,"sl":"49, 51","tp":"TLD returns authoritative server","t":"mcq","q":"When contacted, a TLD DNS server would return an IP address of a(n):","o":["Root DNS server","Authoritative DNS server","Local DNS server","Another TLD DNS server."],"a":1,"e":"Chapter 2, slide 51 (iterated query): root → returns the TLD server; TLD → returns the <b>authoritative</b> DNS server (dns.cs.umass.edu); the authoritative server gives the final answer.","from":[{"s":"M22S","qn":"Q1.7","pg":131}]},{"id":"M22S-1-9","ch":2,"sl":"13","tp":"Time-sensitive apps","t":"mcq","q":"Which one of the following network applications is time-sensitive?","o":["File Transfer/download","E-mail","Web documents","Video conferencing"],"a":3,"e":"Chapter 2, slide 13: file transfer, e-mail and Web documents are not time sensitive; real-time audio/video (video conferencing) is time sensitive (10s of msec).","from":[{"s":"M22S","qn":"Q1.9","pg":132}]},{"id":"M22S-1-10","ch":2,"sl":"20–22","tp":"Non-persistent: one connection per object","t":"mcq","q":"With non-persistent HTTP, a client requests a web page consisting of a base HTML file and 5 JPEG images. How many TCP connections are generated?","o":["11 connections","6 connections","5 connections","None of the above"],"a":1,"e":"Chapter 2, slide 20: non-persistent HTTP — at most one object sent over a TCP connection, then the connection is closed. Slides 21–22 (example with 10 jpegs): steps 1–5 repeated for each object. 1 base file + 5 images = <b>6</b> connections.","from":[{"s":"M22S","qn":"Q1.10","pg":132}]},{"id":"M22S-1-12","ch":2,"sl":"28","tp":"Last-Modified header","t":"mcq","q":"In the HTTP header, the Last-Modified field indicates:","o":["The time and date when the object was created or last modified","The last time when the object was licensed by the server","The last time when the administrator changed the protocol specification","All of the above."],"a":0,"e":"Chapter 2, slide 28 (HTTP response message): <code>Last-Modified: Tue, 30 Oct 2007 17:00:02 GMT</code> — when the object was last modified (used by caches for conditional GET, slide 41).","from":[{"s":"M22S","qn":"Q1.12","pg":132}]},{"id":"M22S-1-13","ch":2,"sl":"15; ch1 61","tp":"SMTP between mail servers","t":"mcq","q":"Which protocol is used to transfer messages between the mail servers of the sender and the receiver?","o":["SMTP","HTTP","IMAP","HTTPs"],"a":0,"e":"Chapter 2, slide 15: e-mail uses <b>SMTP</b> [RFC 5321] over TCP. (IMAP is used by a user agent to retrieve mail from its own server; it isn't used server-to-server.)","nb":"E-mail has only a brief mention in your Chapter 2 slides (slide 15 table).","from":[{"s":"M22S","qn":"Q1.13","pg":132}]},{"id":"M22S-3-B","ch":2,"sl":"58","tp":"Types of network attacks","t":"short","q":"List two types of attacks in computer networks.","a":"1) <b>Denial of Service (DDoS)</b> attacks — e.g. bombarding root or TLD DNS servers with traffic.<br>2) <b>Spoofing</b> attacks — e.g. IP spoofing, or intercepting DNS queries and returning bogus replies (DNS cache poisoning).","e":"Chapter 2, slide 58 (DNS security): DDoS attacks (bombard root servers / TLD servers with traffic) and spoofing attacks (intercept DNS queries, returning bogus replies; DNS cache poisoning; DNSSEC as defense). The model answer lists Denial of Service and IP spoofing.","nb":"Network security has its own textbook chapter; in your slides it appears only as DNS security (Ch 2, slide 58).","from":[{"s":"M22S","qn":"Q3 B","pg":134}]},{"id":"MI-3","ch":2,"sl":"23–24","tp":"Wikipedia page: DNS + 5 objects","t":"short","q":"A user clicks a link to a Wikipedia page. The IP address isn't cached, so a DNS lookup returns an IP address within <b>3 ms</b>. The page references <b>5 objects</b>. The RTT between the user's device and the Wikipedia server is <b>0.5 ms</b>. Neglecting transmission times, how long until the page and all objects are received with:<br>1. Non-persistent HTTP with no parallel TCP connections?<br>2. Persistent HTTP with no pipelining?","a":"1. DNS + 2 RTT (page) + 5 × 2 RTT = 3 + 12 × 0.5 = <b>9 ms</b>.<br>2. DNS + 1 RTT (connection) + 1 RTT (page) + 5 × 1 RTT = 3 + 7 × 0.5 = <b>6.5 ms</b>.","e":"Chapter 2, slide 23: non-persistent HTTP needs 2 RTT per object (TCP setup + request/response). Slide 24: persistent HTTP sets up the connection once; then each object takes one RTT when requests are not pipelined.","from":[{"s":"MI","qn":"Q3","pg":144}]},{"id":"MK-2","ch":2,"sl":"23–24","tp":"RTTs for base page + 4 images","t":"short","q":"A user requests a Web page that consists of a base page with some text and <b>four images</b>. (RTT = time to send a request from the user to the server and get the response.)<br>1. How many RTTs are needed with <b>non-persistent</b> HTTP without parallel connections?<br>2. How many RTTs with <b>persistent</b> HTTP without parallel connections?","a":"1. 5 objects × 2 RTT = <b>10 RTT</b><br>2. 1 RTT (TCP setup) + 5 × 1 RTT = <b>6 RTT</b>","e":"Chapter 2, slide 23: non-persistent → 2 RTT per object. Slide 24: persistent → one TCP setup RTT, then 1 RTT per object.","from":[{"s":"MK","qn":"Q2 Part2","pg":151}]},{"id":"MK-1-4","ch":2,"sl":"54, 57","tp":"DNS A record","t":"mcq","q":"What is the correct type for the DNS Resource Record (dns1.networkutopia.com, 212.212.212.1, ??)","o":["A","MX","NS","CNAME"],"a":0,"e":"Chapter 2, slide 54: type A — name is a hostname, value is an IP address. Slide 57 inserts exactly this record into the .com TLD server.","from":[{"s":"MK","qn":"Q1.4","pg":153}]},{"id":"MK-1-6","ch":2,"sl":"14","tp":"TCP service: reliable transport","t":"mcq","q":"Which of the following services is provided by the TCP protocol?","o":["Guarantee minimum transmission delay.","Guarantee minimum throughput.","Guarantee enough security.","Reliable transport between sending and receiving processes.","All the above."],"a":3,"e":"Chapter 2, slide 14: TCP service — reliable transport between sending and receiving process, flow control, congestion control, connection-oriented. It does not provide timing, minimum throughput guarantee, or security.","from":[{"s":"MK","qn":"Q1.6","pg":153}]},{"id":"FA-1-5","ch":2,"sl":"43–44","tp":"Purpose of DNS","t":"mcq","q":"What is the primary purpose of the Domain Name System (DNS)?","o":["To convert domain names into IP addresses.","To manage routing between networks.","To provide secure access to resources.","To store data in a distributed manner."],"a":0,"e":"Chapter 2, slide 43: hosts have IP addresses and names (e.g. cs.umass.edu) — Q: how to map between IP address and name, and vice versa? DNS. Slide 44 lists its services: hostname-to-IP-address translation, host aliasing, mail server aliasing, load distribution. (DNS <i>is</i> a distributed database, but that's how it is built, not its purpose.)","from":[{"s":"FA","qn":"Q1 A.5","pg":26}]},{"id":"FC-1-10","ch":2,"sl":"25–27","tp":"POST uses entity body","t":"mcq","q":"We fill the \"entity body\" field of the HTTP request message when using:","o":["GET method","POST method","HEAD method","PUT method"],"a":1,"e":"Chapter 2, slide 26 (HTTP request message: general format) shows the entity body after the header lines. Slide 27: <b>POST</b> method — web page often includes form input; user input is sent from client to server in the <b>entity body</b> of the HTTP POST request message. GET puts the data in the URL. (PUT also carries a body — the new file — but POST is the answer the slides give for user input.)","from":[{"s":"FC","qn":"Q1(a).10","pg":50},{"s":"F13","qn":"Q1(a).10","pg":209}]},{"id":"FC-TF-9","ch":2,"sl":"14","tp":"No delay/bandwidth guarantees","t":"tf","q":"Transport layer protocols, i.e. TCP and UDP, provide delay and bandwidth guarantees.","a":1,"e":"Chapter 2, slide 14: TCP does not provide timing or minimum throughput guarantees; UDP provides none of reliability, flow control, congestion control, timing, throughput guarantee, security or connection setup. <b>False</b>.","from":[{"s":"FC","qn":"Q1(b).9","pg":50},{"s":"F13","qn":"Q1(b).9","pg":209}]},{"id":"FD-DNS","ch":2,"sl":"49–51, 54, 57","tp":"DNS: local, authoritative, TLD records","t":"short","q":"(Figure: requesting host → local DNS server → root → TLD → authoritative server dns.enterprise.com for www.enterprise.com.)<br>A) To which DNS server does a host send its requests? (full name)<br>B) Which type of DNS server holds a company's DNS records? (full name)<br>C) What is the name of the DNS server for enterprise.com?<br>D) When you request www.enterprise.com, your local DNS asks on your behalf. When it contacts the TLD server, how many resource records are returned? Write them.","img":"FD-DNS.jpg","a":"A) The <b>local DNS server</b> (default name server).<br>B) The <b>authoritative DNS server</b>.<br>C) <b>dns.enterprise.com</b><br>D) <b>Two</b> records:<br>(enterprise.com, dns.enterprise.com, <b>NS</b>)<br>(dns.enterprise.com, &lt;IP address of dns.enterprise.com&gt;, <b>A</b>)","e":"Chapter 2, slide 50: hosts send DNS queries to their local DNS server. Slide 49: authoritative servers hold the organization's hostname-to-IP mappings. Slide 57: the registrar inserts an NS record and an A record into the TLD server, so the TLD answers with both (the A record is the \"glue\" so the local server can reach the authoritative server).","from":[{"s":"FD","qn":"DNS question A–D","pg":154},{"s":"FF","qn":"Q3 (DNS figure)","pg":281}]},{"id":"FD-TF-1","ch":2,"sl":"12–13","tp":"Web transactions need integrity","t":"tf","q":"Web page transaction applications using the HTTP protocol require 100% integrity; they cannot tolerate loss of their data.","a":0,"e":"Chapter 2, slide 12: some apps (e.g. file transfer, <b>web transactions</b>) require 100% reliable data transfer. Slide 13: Web documents — no loss. <b>True</b>.","from":[{"s":"FD","qn":"Q1 B.1","pg":155}]},{"id":"FD-TF-4","ch":2,"sl":"6–7","tp":"P2P is self-scalable","t":"tf","q":"In general, a P2P file-sharing application has more scalability than a client-server based application.","a":0,"e":"Chapter 2, slide 7: P2P has self scalability — new peers bring new service capacity, as well as new service demands. A client-server app is limited by its servers (slide 6). <b>True</b>.","from":[{"s":"FD","qn":"Q1 B.4","pg":155}]},{"id":"BB3-A8","ch":2,"sl":"54","tp":"Type A record","t":"mcq","q":"What information does the type \"A\" resource record hold in the DNS database?","o":["A name and the name of the SMTP server associated with that name.","An alias name and a true name for a server.","A hostname and an IP address.","A domain name and the name of the authoritative name server for that domain."],"a":2,"e":"Chapter 2, slide 54: type=A → name is hostname, value is IP address. (Option A is MX, B is CNAME, D is NS.)","from":[{"s":"F22","qn":"Q8","pg":158},{"s":"BB3","qn":"Q8","pg":88}]},{"id":"F22-3","ch":2,"sl":"14","tp":"Reliable transport = TCP","t":"mcq","q":"Which transport protocol provides reliable transport between the sending and receiving process?","o":["UDP","TCP","IP","HTTP"],"a":1,"e":"Chapter 2, slide 14: TCP service — reliable transport between sending and receiving process; UDP — unreliable data transfer.","from":[{"s":"F22","qn":"Q3","pg":158}]},{"id":"F22-4","ch":2,"sl":"20","tp":"Persistent HTTP definition","t":"mcq","q":"Multiple objects can be sent over a single TCP connection between the client and that server. This is:","o":["Non-persistent HTTP","Persistent HTTP","Conditional GET","Web caching"],"a":1,"e":"Chapter 2, slide 20 (HTTP connections: two types): <b>persistent HTTP</b> — TCP connection opened to a server; multiple objects can be sent over a single TCP connection between client and that server; TCP connection closed.","from":[{"s":"F22","qn":"Q4","pg":158}]},{"id":"FE-8","ch":2,"sl":"46–48","tp":"Root DNS servers","t":"mcq","q":"Which DNS server is located at the highest level of the DNS hierarchy, and knows how to reach servers responsible for a given domain (e.g. *.com, *.edu)?","o":["Local DNS server","Top Level Domain (TLD) servers","DNS root servers","Authoritative DNS server"],"a":2,"e":"Chapter 2, slide 46: root DNS servers sit at the top of the hierarchy, above the .com/.org/.edu TLD servers. Slides 47–48: root name servers are the official contact-of-last-resort for name servers that can't resolve a name.","from":[{"s":"FE","qn":"Q1 A.8","pg":161}]},{"id":"FE-TF-2","ch":2,"sl":"20","tp":"Non-persistent = one object per connection","t":"tf","q":"In the non-persistent HTTP protocol, multiple objects can be sent over a single TCP connection between the client and that server.","a":1,"e":"Chapter 2, slide 20: in <b>non-persistent</b> HTTP at most one object is sent over a TCP connection, then the connection is closed. Sending multiple objects over one connection is persistent HTTP. <b>False</b>.","from":[{"s":"FE","qn":"Q1 B.2","pg":161}]},{"id":"FE-TF-3","ch":2,"sl":"12–13","tp":"Web transactions can't tolerate loss","t":"tf","q":"The web page transaction application using the HTTP protocol does not require 100% integrity, but it can tolerate some loss of data.","a":1,"e":"Chapter 2, slide 12: web transactions require 100% reliable data transfer; slide 13: Web documents — no loss. <b>False</b>.","from":[{"s":"FE","qn":"Q1 B.3","pg":161}]},{"id":"FE-2-B","ch":2,"sl":"51, 54","tp":"Resolve www.enterprise.com from given records","t":"short","q":"You want to visit www.enterprise.com but don't know the web server's IP address.<br>Records on the TLD DNS server:<br>• (www.enterprise.com, dns.enterprise.com, NS)<br>• (dns.enterprise.com, 146.54.116.12, A)<br>Records on the enterprise.com DNS server:<br>• (www.enterprise.com, east2.enterprise.com, CNAME)<br>• (east2.enterprise.com, 142.81.17.206, A)<br>• (enterprise.com, mail.enterprise.com, MX)<br>• (mail.enterprise.com, 247.29.42.227, A)<br>Explain how the name is resolved and which IP address the browser finally connects to. What are the canonical name of the web server and the address of the company's mail server?","a":"1. Local DNS → root → <b>TLD</b>, which returns the NS record <i>and</i> the A record for <b>dns.enterprise.com = 146.54.116.12</b>.<br>2. The local DNS asks the authoritative server 146.54.116.12. It answers that www.enterprise.com is an <b>alias</b> (CNAME) for <b>east2.enterprise.com</b>, whose A record is <b>142.81.17.206</b>.<br>3. The browser connects to <b>142.81.17.206</b>.<br>Mail: the MX record points to <b>mail.enterprise.com</b>, whose address is <b>247.29.42.227</b>.","e":"Chapter 2, slide 51 (iterated query: root → TLD → authoritative). Slide 54: NS = authoritative name server for a domain; A = hostname → IP; CNAME = alias → canonical (real) name; MX = mail server for the domain.","nb":"The photo cuts off the sub-questions; this version asks what those records are used for.","from":[{"s":"FE","qn":"Q2 B","pg":162},{"s":"FF","qn":"Q3 B","pg":281}]},{"id":"Q1R-5","ch":2,"sl":"49","tp":"Authoritative DNS server role","t":"short","q":"What is the role of an authoritative name server in the DNS?","a":"It is the organization's own DNS server(s) that provides the <b>authoritative hostname-to-IP mappings</b> for the organization's named hosts (e.g. its Web and mail servers). It gives the final answer in a lookup. It can be maintained by the organization or by its service provider.","e":"Chapter 2, slide 49 (Top-Level Domain, and authoritative servers): authoritative DNS servers are the organization's own DNS server(s), providing authoritative hostname-to-IP mappings for the organization's named hosts; can be maintained by the organization or service provider.","from":[{"s":"Q1R","qn":"Q5","pg":65}]},{"id":"Q1R-6","ch":2,"sl":"35–36, 50, 53","tp":"Which caches are shared by users","t":"short","q":"In HTTP web browser caching, HTTP local web server (proxy) caching, and local DNS caching, a user benefits from finding a local copy of a requested item. In which of these forms of caching does a user benefit not only from its <i>own</i> recent requests but also from recent requests made by <i>other users</i>?","a":"<b>Local web (proxy) server caching</b> and <b>local DNS caching</b>. The browser cache only holds that user's own past replies.","e":"Chapter 2, slides 35–36: a Web cache (proxy server) is installed by an ISP/institution and serves all users whose browsers point to it. Slides 50 and 53: the local DNS server caches name-to-address mappings learned for any host it serves, so later queries from other hosts are answered from the cache. The browser cache lives on one host only.","from":[{"s":"Q1R","qn":"Q6","pg":65}]},{"id":"Q1R-1","ch":2,"sl":"23","tp":"Non-persistent HTTP RTTs","t":"short","q":"An HTTP/1.0 (non-persistent) client requests a base object from gaia.cs.umass.edu. The client has never requested it before and hasn't recently talked to the server, but knows its IP address. How many RTTs are needed from the request until the base page is completely downloaded, if transmitting the base file into the server's link takes <b>1/2 RTT</b> and transmitting the GET takes zero time? (Include TCP setup, object transmission and any propagation delays.)","a":"<b>2.5 RTT</b> = 1 RTT (TCP connection setup) + 1 RTT (HTTP GET goes out, first bits of the reply come back) + 0.5 RTT (time to transmit the file).","e":"Chapter 2, slide 23 (Non-persistent HTTP: response time): one RTT to initiate the TCP connection, one RTT for the HTTP request and the first few bytes of the HTTP response to return, plus the object/file transmission time → 2RTT + file transmission time.","from":[{"s":"Q1R","qn":"Q1","pg":69}]},{"id":"BB3-3","ch":2,"sl":"49","tp":"Authoritative server (multi-select)","t":"short","q":"What is the role of an authoritative name server in the DNS? (Select all that apply.)<br>□ It is a local (to the querying host) server that caches name-to-IP address translation pairs, so it can answer authoritatively and do so quickly.<br>□ It provides the definitive answer to the query with respect to a name in the authoritative name server's domain.<br>□ It provides the IP address of the DNS server that can provide the definitive answer to the query.<br>□ It provides a list of TLD servers that can be queried to find the IP address of the DNS server that can provide the definitive answer to this query.","a":"Only the <b>second</b> option: it provides the <b>definitive answer</b> to the query for a name in its own domain.","e":"Chapter 2, slide 49: authoritative DNS servers are the organization's own DNS servers, providing authoritative hostname-to-IP mappings for the organization's named hosts. The first option describes a local DNS server's cache (slide 50); the third and fourth describe what TLD and root servers return in an iterated query (slide 51).","from":[{"s":"BB3","qn":"Q3","pg":74}]},{"id":"BB3-7","ch":2,"sl":"23","tp":"Non-persistent HTTP RTTs (MCQ)","t":"mcq","q":"An HTTP/1.0 (non-persistent) client requests a base object from gaia.cs.umass.edu; it knows the server's IP address but has no open connection. How many RTTs are needed until the base page is completely downloaded, if transmitting the base file into the server's link takes 1/2 RTT and transmitting the GET takes zero time?","o":["0 RTT","0.5 RTT","1.5 RTT","2.5 RTT","3.5 RTT"],"a":3,"e":"Chapter 2, slide 23: 1 RTT for TCP connection setup + 1 RTT for the GET and the first bits of the response + 0.5 RTT to transmit the file = <b>2.5 RTT</b>.","from":[{"s":"BB3","qn":"Q7","pg":74},{"s":"BB3","qn":"Q7","pg":85}]},{"id":"BB3-DNS7","ch":2,"sl":"47–50","tp":"Match DNS server types","t":"short","q":"Match the function to the type of DNS server (Authoritative, Root, TLD, Local):<br>1. Provides authoritative hostname-to-IP mappings for an organization's named hosts.<br>2. Replies to a DNS query by the local host, by contacting other DNS servers to answer the query.<br>3. Responsible for a domain (e.g. *.com, *.edu); knows how to contact authoritative name servers.<br>4. Highest level of the DNS hierarchy; knows how to reach servers responsible for a given domain (e.g. *.com, *.edu).","a":"1 → <b>Authoritative DNS server</b><br>2 → <b>Local DNS server</b><br>3 → <b>Top Level Domain (TLD) servers</b><br>4 → <b>DNS root servers</b>","e":"Chapter 2, slides 47–48 (root name servers: contact-of-last-resort), slide 49 (TLD servers responsible for .com, .org, .net, .edu …; authoritative servers: the organization's own servers), slide 50 (local DNS server forwards queries into the hierarchy).","from":[{"s":"BB3","qn":"Q7","pg":87}]},{"id":"BB3-CG7","ch":2,"sl":"41","tp":"If-Modified-Since → cached copy","t":"mcq","q":"A client sends this HTTP GET to gaia.cs.umass.edu:<pre>GET /kurose_ross_sandbox/interactive/quotation2.htm HTTP/1.1\nHost: gaia.cs.umass.edu\nAccept: text/plain, text/html, text/xml, image/jpeg, ...\nAccept-Language: en-us, en-gb;q=0.1, ...\nIf-Modified-Since: Wed, 09 Sep 2020 16:06:01 -0700\nUser Agent: Mozilla/5.0 ...</pre>Does the client have a cached copy of the object being requested?","o":["There's not enough information in the header to answer this question.","No, because a client would not request an object if it had that object in its cache.","Yes, because this is a conditional GET, as evidenced by the If-Modified-Since field.","Yes, because HTTP 1.1 is being used."],"a":2,"e":"Chapter 2, slide 41 (Conditional GET): the cache/client specifies the date of its cached copy in the request with <code>If-modified-since: &lt;date&gt;</code>. The header is only sent when a cached copy exists.","from":[{"s":"BB3","qn":"Q7","pg":89}]},{"id":"BB3-IMS2","ch":2,"sl":"41","tp":"Purpose of If-Modified-Since","t":"mcq","q":"What is the purpose of the <i>If-Modified-Since</i> field in an HTTP GET request message?","o":["To indicate to the server that the server should replace this named object with the new version of the object attached to the GET, if the object has not been modified since the specified time.","To allow the server to indicate to the client that it (the client) should cache this object.","To inform the HTTP cache that it (the cache) should retrieve the full object from the server, and then cache it until the specified time.","To indicate to the server that the client has cached this object from a previous GET, and the time it was cached.","To indicate to the server that the client wishes to receive this object, and the time until which it will cache the returned object in the browser's cache."],"a":3,"e":"Chapter 2, slide 41 (Conditional GET): the client/cache specifies the date of its cached copy in the HTTP request (<code>If-modified-since: &lt;date&gt;</code>); the server answers 304 Not Modified if the cached copy is up-to-date.","from":[{"s":"BB3","qn":"Q2","pg":93}]},{"id":"M14-1-1","ch":2,"sl":"15","tp":"FTP runs on TCP","t":"mcq","q":"The FTP application runs on:","o":["TCP","UDP","DNS","POP3"],"a":0,"e":"Chapter 2, slide 15: file transfer/download — FTP [RFC 959] — transport protocol TCP.","from":[{"s":"ML","qn":"Q1.8","pg":247},{"s":"M14","qn":"Q1.1","pg":251}]},{"id":"M14-1-4","ch":2,"sl":"44","tp":"DNS load distribution","t":"mcq","q":"Replicated servers with rotating IP addresses are used to perform the ______ DNS service.","o":["hostname to IP address translation","load distribution","host aliasing","mail server aliasing"],"a":1,"e":"Chapter 2, slide 44 (DNS services): <b>load distribution</b> — replicated Web servers: many IP addresses correspond to one name.","from":[{"s":"ML","qn":"Q1.10","pg":247},{"s":"M14","qn":"Q1.4","pg":251}]},{"id":"ML-1-5","ch":2,"sl":"7","tp":"P2P feature","t":"mcq","q":"Which of the following is a feature of P2P architecture?","o":["always-on host","self-scalability","data centers","permanent IP address"],"a":1,"e":"Chapter 2, slide 7: P2P — self scalability (new peers bring new service capacity and new demands). Always-on host, permanent IP address and data centers are client-server features (slide 6).","from":[{"s":"ML","qn":"Q1.5","pg":244}]},{"id":"ML-1-6","ch":2,"sl":"9","tp":"Socket is software","t":"tf","q":"A socket is a hardware interface between the application process and the transport layer protocol.","a":1,"e":"Chapter 2, slide 9: a socket is a software abstraction (a \"door\") between the application process and the end-end transport protocol — not hardware. <b>False</b>.","from":[{"s":"ML","qn":"Q1.6","pg":244}]},{"id":"ML-1-7","ch":2,"sl":"23–24","tp":"Parallel TCP connections","t":"mcq","q":"______ can be used to shorten the response time in non-persistent HTTP connections.","o":["parallel TCP connections","pipelining connections","back-to-back connections","inter-process connections"],"a":0,"e":"Chapter 2, slide 24: non-persistent HTTP issues — 2 RTTs per object; browsers often open <b>multiple parallel TCP connections</b> to fetch referenced objects in parallel.","from":[{"s":"ML","qn":"Q1.7","pg":244}]},{"id":"ML-3-1","ch":2,"sl":"20, 25–27","tp":"Read GET: URL, persistence, body","t":"short","q":"<pre>GET /page/home.html HTTP/1.1\nHost: gaia.cs.umass.edu\nUser-Agent: Mozilla/5.0 (Windows;U; Windows NT 5.1; en-US; rv:1.7.2) ...\nAccept: ext/xml, application/xml, application/xhtml+xml, text/html;q=0.9, ...\nAccept-Language: en-us,en;q=0.5\nAccept-Encoding: zip,deflate\nAccept-Charset: ISO-8859-1,utf-8;q=0.7,*;q=0.7\nConnection: close</pre>a. What is the complete URL of the requested document?<br>b. Does the browser request a non-persistent or a persistent connection?<br>c. Which HTTP methods use the entity body?","a":"a. <b>http://gaia.cs.umass.edu/page/home.html</b> (Host header + path in the request line)<br>b. <b>Non-persistent</b> — <code>Connection: close</code><br>c. <b>POST</b> (form input) and <b>PUT</b> (uploaded object). GET and HEAD have an empty body.","e":"Chapter 2, slide 25 (request line + Host header), slide 20 (non-persistent: connection closed after one object), slides 26–27 (entity body: POST sends form input in it; PUT uploads a new file in it).","from":[{"s":"ML","qn":"Q3.1","pg":245}]},{"id":"ML-3-2","ch":2,"sl":"35–36, 41","tp":"Name the term: cache, conditional GET","t":"short","q":"Give the term:<br>1. A server that reduces the response time and Web traffic in the Internet.<br>2. A mechanism that allows a Web cache to verify that its objects are up to date.","a":"1. <b>Web cache</b> (proxy server)<br>2. <b>Conditional GET</b> (If-Modified-Since header)","e":"Chapter 2, slides 35–36 (Web caches / proxy servers: reduce response time and access-link traffic), slide 41 (Conditional GET).","from":[{"s":"ML","qn":"Q3.2","pg":246}]},{"id":"ML-3-3","ch":2,"sl":"51","tp":"What each iterated-query step returns","t":"short","q":"DNS <b>iterated query</b>: host ccis.imamu.edu wants the IP address of gaia.cs.ksu.edu; its local DNS server is dns.imamu.edu. What IP address is returned in the response at each step?<br>1. Local DNS server forwards the query to a root DNS server.<br>2. Local DNS server resends the query to one of the TLD servers.<br>3. Local DNS server resends the query directly to the authoritative server.","a":"1. Root → IP address of a <b>.edu TLD server</b>.<br>2. TLD → IP address of the <b>authoritative server for ksu.edu</b>.<br>3. Authoritative → IP address of <b>gaia.cs.ksu.edu</b> itself (the answer).","e":"Chapter 2, slide 51 (iterated query): each contacted server replies with the name/address of the next server to contact — \"I don't know this name, but ask this server\" — until the authoritative server returns the final mapping.","from":[{"s":"ML","qn":"Q3.3","pg":246}]},{"id":"PJ-1","ch":2,"sl":"14","tp":"Neither TCP nor UDP guarantees bandwidth","t":"mcq","q":"Which is not a service of both TCP and UDP?","o":["guaranteed delivery","guaranteed bandwidth","multiplexing and demultiplexing","all of above"],"a":1,"e":"Chapter 2, slide 14: neither TCP nor UDP provides a throughput (bandwidth) guarantee. Guaranteed (reliable) delivery is a TCP service, and both protocols provide multiplexing/demultiplexing (Chapter 3, slide 22).","from":[{"s":"PJ","qn":"Q1.1","pg":237}]},{"id":"F15-1-1","ch":2,"sl":"15","tp":"E-mail protocols","t":"mcq","q":"Which of the following could be required for an email application?","o":["IMAP","SMTP","POP","All of the above"],"a":3,"e":"Chapter 2, slide 15 lists SMTP for e-mail (sending between servers). Mail-access protocols such as IMAP and POP are used by the receiver's user agent to retrieve mail — all of them can be part of an e-mail application.","nb":"E-mail has only a brief mention in your Chapter 2 slides (slide 15 table).","from":[{"s":"F15","qn":"Q1.1","pg":223}]},{"id":"F15-1-3","ch":2,"sl":"54","tp":"Value is an IP → type A","t":"mcq","q":"When the \"value\" of a resource record is an IP address, the \"type\" of the record should be ______. Example: (ccis.imamu.edu, 112.37.93.100, type)","o":["A","NS","CNAME","MX"],"a":0,"e":"Chapter 2, slide 54: type=A — name is hostname, value is IP address.","from":[{"s":"F15","qn":"Q1.3","pg":223}]},{"id":"F15-2-2","ch":2,"sl":"15; ch3 25","tp":"Transport for HTTP/SMTP/DNS/DHCP","t":"short","q":"Fill in the transport-layer protocol used by each application-layer protocol: HTTP, SMTP, DNS, DHCP.","a":"HTTP → <b>TCP</b> · SMTP → <b>TCP</b> · DNS → <b>UDP</b> · DHCP → <b>UDP</b>","e":"Chapter 2, slide 15: Web/HTTP and e-mail/SMTP use TCP. Chapter 3, slide 25: DNS uses UDP. DHCP also runs over UDP (network-layer chapter).","from":[{"s":"F15","qn":"Q2.2","pg":224}]},{"id":"F14-1-3","ch":2,"sl":"15","tp":"SMTP uses TCP","t":"mcq","q":"The SMTP application protocol uses the ______ transport-layer protocol.","o":["UDP","POP3","TCP","ICMP"],"a":2,"e":"Chapter 2, slide 15: e-mail — SMTP [RFC 5321] — transport protocol TCP.","from":[{"s":"F14","qn":"Q1.3","pg":199}]},{"id":"F14-1-4","ch":2,"sl":"34","tp":"Cookies collect user info","t":"mcq","q":"Which statement is true about cookies?","o":["Cookies are used for hosting.","Cookies are used to collect information about users.","Cookies are used only by browsers.","Cookies are sweet and buttery."],"a":1,"e":"Chapter 2, slide 34 (HTTP cookies: comments): cookies are used for authorization, shopping carts, recommendations, user session state — and \"cookies and privacy: cookies permit sites to learn a lot about you\" (e.g. third-party tracking cookies).","from":[{"s":"F14","qn":"Q1.4","pg":199}]},{"id":"F14-1-5","ch":2,"sl":"20","tp":"Same server → persistent connection","t":"mcq","q":"Two different web pages on the same server (www.cs.imamu.edu.sa/faculty.html and www.cs.imamu.edu.sa/students.html) can be sent over the same ______ connection.","o":["UDP","Non-persistent","Persistent","DNS"],"a":2,"e":"Chapter 2, slide 20: with persistent HTTP, multiple objects can be sent over a single TCP connection between the client and that server.","from":[{"s":"F14","qn":"Q1.5","pg":199}]},{"id":"F14-1-6","ch":2,"sl":"54","tp":"MX record value","t":"mcq","q":"In a DNS resource record, the MX type means the stored Value is the name of the ______ associated with Name.","o":["Canonical hostname for the alias hostname","Canonical name of a mail server","IP address","DNS server"],"a":1,"e":"Chapter 2, slide 54: type=MX — value is the name of the SMTP mail server associated with name.","from":[{"s":"F14","qn":"Q1.6","pg":199}]},{"id":"F14-2-2","ch":2,"sl":"37–40","tp":"Proxy cache: link utilization","t":"short","q":"A company has an E2 link (<b>8.45 Mbps</b>) serving Web requests from <b>200 users</b>. Each user makes on average <b>2 requests/s</b>, average object size <b>20 kbits</b>. The company is about to install a proxy server (Web cache).<br>a. What percentage of the bandwidth is consumed by Web traffic with no proxy?<br>b. With a proxy hit rate of <b>45%</b>, what percentage is consumed?","a":"a. Traffic = 200 × 2 × 20 kbits = 8 Mbps → 8 / 8.45 = <b>≈ 94.7%</b><br>b. Only misses (55%) cross the link: 0.55 × 8 = 4.4 Mbps → 4.4 / 8.45 = <b>≈ 52.1%</b>","e":"Chapter 2, slides 37–40 (Caching example): access link utilization = traffic rate / link rate; with a local web cache, only the misses (1 − hit rate) go over the access link, which lowers utilization and delay.","from":[{"s":"F14","qn":"Q2.2","pg":201}]},{"id":"M14-1-2","ch":2,"sl":"15","tp":"SMTP is push","t":"mcq","q":"SMTP:","o":["is a \"pull\" protocol","is a \"push\" protocol","can send multiple objects in one message","b and c"],"a":3,"e":"SMTP <b>pushes</b> mail from the sender's server to the receiver's server (HTTP, by contrast, is a pull protocol), and an SMTP message can carry multiple objects (e.g. text plus attachments) in one multipart message.","nb":"SMTP details are in the textbook's e-mail section; your slides only list SMTP in the table on Ch 2 slide 15.","from":[{"s":"M14","qn":"Q1.2","pg":251}]},{"id":"M14-1-3","ch":2,"sl":"15","tp":"Mail access protocols","t":"mcq","q":"Which of the following is a mail access protocol?","o":["POP3","IMAP","SMTP","a and b"],"a":3,"e":"POP3 and IMAP are mail <b>access</b> protocols (the receiver's user agent retrieves mail from its server); SMTP transfers mail between servers. Your slides list IMAP among application-layer protocols (Ch 1, slide 61).","nb":"Mail access protocols are covered in the textbook's e-mail section, not in your slides.","from":[{"s":"M14","qn":"Q1.3","pg":251}]},{"id":"M14-2-2","ch":2,"sl":"15, 18","tp":"Web-mail to Outlook: protocols","t":"short","q":"Alice, with a Web-based e-mail account (Hotmail/Gmail), sends a message to Bob, who reads mail from his mail server with Outlook. Which application-layer protocol moves the message at each step?<br>1. Alice's host → Alice's mail server<br>2. Alice's mail server → Bob's mail server<br>3. Bob's mail server → Bob's host","a":"1. <b>HTTP</b> (web-based mail is used through the browser)<br>2. <b>SMTP</b><br>3. <b>IMAP</b> or <b>POP3</b>","e":"Chapter 2, slide 18: HTTP is the Web's application protocol (browser ↔ web-mail server). Slide 15: SMTP carries mail between mail servers. Bob's mail client retrieves mail with a mail access protocol (IMAP/POP3).","nb":"E-mail details come from the textbook's e-mail section; slides only list SMTP/IMAP.","from":[{"s":"M14","qn":"Q2.2","pg":253}]},{"id":"M14-2-3","ch":2,"sl":"54","tp":"Match RR name/value to type","t":"short","q":"Find the type of each DNS resource record:<br>1. Name = domain, Value = hostname (of a name server)<br>2. Name = alias hostname, Value = canonical name of mail server<br>3. Name = hostname, Value = IP address<br>4. Name = alias hostname, Value = canonical hostname","a":"1. <b>NS</b> · 2. <b>MX</b> · 3. <b>A</b> · 4. <b>CNAME</b>","e":"Chapter 2, slide 54: type=A (hostname → IP), NS (domain → authoritative name server), CNAME (alias → canonical name), MX (name → mail server).","from":[{"s":"M14","qn":"Q2.3","pg":253}]},{"id":"M26-2-3","ch":3,"sl":"20","tp":"TCP socket 4-tuple","t":"mcq","q":"Which of the following statements about a TCP socket is correct?","o":["A TCP socket is identified by a 4-tuple: source IP address, destination IP address, source port number, and destination port number.","Only destination port number used for demultiplexing.","Server supports only one TCP socket at a time.","All the above are correct."],"a":0,"e":"Chapter 3, slide 20 (Connection-oriented demultiplexing): TCP socket identified by 4-tuple (source IP, source port, dest IP, dest port); the receiver uses <i>all four</i> values to direct the segment, and a server may support <i>many simultaneous</i> TCP sockets (one per client). Using only the destination port is UDP demultiplexing (slide 18).","from":[{"s":"M26","qn":"Q2 Part1.3","pg":2}]},{"id":"M26-2-4","ch":3,"sl":"24–26, 30–31","tp":"Why UDP","t":"mcq","q":"Which of the following is advantage of UDP protocol?","o":["No setup/handshaking needed (no RTT incurred)","Can function when network service is compromised.","It includes a checksum mechanism for basic error detection.","All of the above are correct"],"a":3,"e":"Chapter 3, slides 24–26: UDP is connectionless — no handshaking (no connection-establishment RTT), simple, small header, no congestion control so it can function in the face of congestion/compromised network service. Slides 30–31: the UDP header carries a <b>checksum</b> to detect errors. So all three are advantages.","from":[{"s":"M26","qn":"Q2 Part1.4","pg":2}]},{"id":"M26-2-5","ch":3,"sl":"72","tp":"TCP fast retransmit","t":"mcq","q":"Using TCP fast retransmit is performed ________.","o":["If sender receives 3 ACKs for the same data","If sender receives 3 duplicate ACKs for the same data","If sender is unsure about whether the receiver has received a packet","None of the above"],"a":1,"e":"Chapter 3, slide 72 (TCP fast retransmit): if the sender receives <b>3 additional ACKs for the same data</b> (\"triple duplicate ACKs\"), resend the unACKed segment with the smallest seq # — likely that it was lost, so don't wait for timeout.","from":[{"s":"M26","qn":"Q2 Part1.5","pg":2},{"s":"MA","qn":"Q2 Part1.2","pg":3},{"s":"MC","qn":"Q2 Part1.2","pg":13}]},{"id":"M26-2-6","ch":3,"sl":"83","tp":"3-way handshake — SYN","t":"mcq","q":"Which of the following TCP header flags is set to 1 in the <b>first message</b> sent during TCP connection establishment?","o":["FIN","SYN","RST","ACK"],"a":1,"e":"Chapter 3, slide 83 (TCP 3-way handshake): the client chooses an initial seq # x and sends a TCP <b>SYN</b> msg (SYNbit=1, Seq=x). The server answers SYNACK (SYNbit=1, ACKbit=1); the client then sends ACK.","from":[{"s":"M26","qn":"Q2 Part1.6","pg":2}]},{"id":"M26-2-7","ch":3,"sl":"74–77","tp":"TCP flow control","t":"mcq","q":"TCP provides a flow-control service to:","o":["Eliminate network congestion","Eliminate overflowing receiver's buffer","Eliminate overflowing sender's buffer","All the answers are correct."],"a":1,"e":"Chapter 3, slides 74–77 (TCP flow control): the receiver controls the sender so the sender won't overflow the <b>receiver's buffer</b> by transmitting too much, too fast (receiver advertises free buffer space in the rwnd field). Avoiding network congestion is congestion control, a different service.","from":[{"s":"M26","qn":"Q2 Part1.7","pg":2},{"s":"MA","qn":"Q2 Part1.4","pg":3},{"s":"MC","qn":"Q2 Part1.4","pg":13},{"s":"MH","qn":"Q1.13","pg":118}]},{"id":"M26-2-8","ch":3,"sl":"49, 52–53, 57","tp":"Utilization: stop-and-wait vs pipelining","t":"mcq","q":"Which of the following of data transfer protocols has the best performance in term of utilization?","o":["Stop and wait protocol","Go Back-N protocol","Selective repeat protocol","All the answer has the same performance term of utilization."],"a":2,"e":"Chapter 3, slide 49: stop-and-wait (rdt3.0) has very poor utilization (U = 0.00027 in the example). Slides 52–53: pipelining (GBN and SR) keeps several packets in flight and increases utilization. Slide 57: Selective Repeat retransmits only the individual lost packets, while GBN retransmits the whole window — so SR wastes the least capacity and gives the best utilization.","from":[{"s":"M26","qn":"Q2 Part1.8","pg":2},{"s":"MA","qn":"Q2 Part1.6","pg":3},{"s":"MC","qn":"Q2 Part1.6","pg":13},{"s":"FD","qn":"Q1 A.8","pg":155}]},{"id":"M26-2-P2-4","ch":3,"sl":"66–67","tp":"TCP seq/ack numbers","t":"short","q":"Suppose Hosts A and B are using TCP as shown in the figure. Complete the missing Seq/Ack numbers.<pre>A → B : Seq # = 700, Ack # = 30,  DataLen = 130 bytes\nB → A : Seq # = ??,  Ack # = ??,  DataLen = 170 bytes\nA → B : Seq # = ??,  Ack # = ??,  DataLen = 550 bytes</pre>","img":"M26-2-P2-4.jpg","a":"<b>B → A:</b> Seq # = <b>30</b>, Ack # = <b>830</b><br><b>A → B:</b> Seq # = <b>830</b>, Ack # = <b>200</b>","e":"Chapter 3, slide 66 (TCP sequence numbers, ACKs): the seq # is the byte-stream number of the first byte in the segment's data; the ACK # is the seq # of the <i>next byte expected</i> from the other side (cumulative ACK).<br>• B's segment: its seq # is what A said it expects (Ack 30) → <b>30</b>; it acknowledges A's 130 bytes → 700 + 130 = <b>830</b>.<br>• A's next segment: seq = <b>830</b>; it acknowledges B's 170 bytes → 30 + 170 = <b>200</b>.","from":[{"s":"M26","qn":"Q2 Part2.4","pg":3}]},{"id":"M26-3-B","ch":3,"sl":"96, 98–99","tp":"TCP Reno cwnd graph","t":"short","q":"Assuming TCP Reno is the protocol experiencing the behavior shown (cwnd in segments vs. transmission round): rounds 1–10 have cwnd = 1, 2, 4, 8, 16, 17, 18, 19, 20, 21.<br>1. Identify the intervals of time when TCP slow start is operating.<br>2. Identify the intervals of time when TCP congestion avoidance is operating.<br>3. At the 10th transmission round, suppose segment loss is detected by <b>timeout</b>; compute the new cwnd at RTT = 11.<br>4. Following question 3, what congestion approach is operating at RTT 16 if no more loss is detected (slow start, congestion avoidance or fast recovery), and why?<br>5. What is the value of cwnd at transmission round 16?","img":"M26-3-B.jpg","a":"1. Slow start: rounds <b>[1, 5]</b> (cwnd doubles 1→2→4→8→16).<br>2. Congestion avoidance: rounds <b>[5, 10]</b> (cwnd grows by 1 per RTT: 16→21), so ssthresh = 16.<br>3. Timeout → ssthresh = cwnd/2 = 21/2 ≈ <b>10</b>, and cwnd = <b>1 MSS</b> at RTT 11.<br>4. <b>Congestion avoidance</b>: after the timeout cwnd restarts in slow start (rounds 11–14: 1, 2, 4, 8); at round 15 it reaches ssthresh (10), so from then on it grows linearly.<br>5. cwnd at RTT 16 = 10 + 1 = <b>11</b> segments.","e":"Chapter 3, slide 98 (TCP slow start): cwnd starts at 1 MSS and doubles every RTT. Slide 99: on a loss event ssthresh is set to 1/2 of cwnd just before the loss; when cwnd reaches ssthresh the exponential increase switches to linear (congestion avoidance). Slide 96: loss detected by <b>timeout</b> cuts cwnd to 1 MSS; triple duplicate ACK (Reno) cuts it in half instead.","from":[{"s":"M26","qn":"Q3 B","pg":5}]},{"id":"MA-2-1","ch":3,"sl":"30–31","tp":"UDP checksum goal","t":"mcq","q":"The goal of UDP checksum is to:","o":["avoid errors in transmitted segment","detect errors in transmitted segment","correct errors in transmitted segment","all of the above"],"a":1,"e":"Chapter 3, slide 31 (UDP checksum): Goal: <b>detect errors</b> (i.e. flipped bits) in the transmitted segment. The receiver only checks whether the computed checksum equals the checksum field — it cannot correct errors.","from":[{"s":"MA","qn":"Q2 Part1.1","pg":3},{"s":"MC","qn":"Q2 Part1.1","pg":13}]},{"id":"MA-2-3","ch":3,"sl":"43–44, 66","tp":"Sequence numbers detect duplicates","t":"mcq","q":"Which of the following mechanisms allows the receiver to detect duplicate copies of a packet?","o":["Acknowledgment","Checksum","Sequence number.","Window"],"a":2,"e":"Chapter 3, slides 43–44 (How to recover from errors?): when the sender retransmits, duplicates can arrive, so the sender adds a <b>sequence number</b> to each packet and the receiver discards (doesn't deliver up) duplicate packets. Checksums detect bit errors; ACKs tell the sender a packet arrived.","from":[{"s":"MA","qn":"Q2 Part1.3","pg":3},{"s":"MC","qn":"Q2 Part1.3","pg":13},{"s":"F22","qn":"Q15","pg":158},{"s":"QZ","qn":"Q1.4","pg":248},{"s":"BQ21","qn":"Q3","pg":11}]},{"id":"MA-2-5","ch":3,"sl":"48, 70","tp":"Premature timeout","t":"mcq","q":"Increasing of unnecessary retransmissions of segments at the sender, is caused by:","o":["overflow of the sender's buffer","acknowledgement of last segment sent.","a premature timeout","None of the above"],"a":2,"e":"Chapter 3, slide 48 (rdt3.0 in action — premature timeout/delayed ACK) and slide 70 (TCP retransmission scenarios — premature timeout): if the timeout is too short, the sender times out before the ACK arrives and retransmits a segment that was actually received → unnecessary retransmissions (duplicates).","from":[{"s":"MA","qn":"Q2 Part1.5","pg":3},{"s":"FC","qn":"Q1(a).9","pg":50},{"s":"F13","qn":"Q1(a).9","pg":209}]},{"id":"MA-2-7","ch":3,"sl":"18, 22","tp":"UDP demultiplexing","t":"mcq","q":"To implement the UDP demultiplexing, one of the following is required:","o":["The destination IP address and port number","Only destination port number","4-tuple: source and destination IP addresses, and port numbers.","All the above"],"a":1,"e":"Chapter 3, slide 18 (Connectionless demultiplexing): when the receiving host receives a UDP segment it <b>checks the destination port #</b> in the segment and directs it to the socket with that port #. Datagrams with the same dest. port but different source IPs/ports go to the same socket. Slide 22 summary: UDP demultiplexing uses the destination port number (only). The 4-tuple is TCP.","from":[{"s":"MA","qn":"Q2 Part1.7","pg":4},{"s":"MC","qn":"Q2 Part1.7","pg":13},{"s":"MK","qn":"Q1.1","pg":153}]},{"id":"MA-3-B","ch":3,"sl":"66–67","tp":"TCP seq/ack numbers","t":"short","q":"Hosts A and B are using TCP. Complete the missing Seq/Ack numbers.<pre>A → B : Seq # = 300, Ack # = 50, DataLen = 100 bytes\nB → A : Seq # = ??,  Ack # = ??, DataLen = 120 bytes\nA → B : Seq # = ??,  Ack # = ??, DataLen = 550 bytes</pre>","a":"<b>B → A:</b> Seq # = <b>50</b>, Ack # = <b>400</b><br><b>A → B:</b> Seq # = <b>400</b>, Ack # = <b>170</b>","e":"Chapter 3, slide 66: seq # = number of the first byte in the segment; ACK # = seq # of the next byte expected (cumulative). B's seq = the Ack A sent (50); B acks 300+100 = 400. A's next seq = 400; it acks 50+120 = 170.","from":[{"s":"MA","qn":"Q3 B","pg":6}]},{"id":"MA-3-C","ch":3,"sl":"96, 98–99","tp":"TCP Reno cwnd graph","t":"short","q":"Assuming TCP Reno is the protocol experiencing the behavior shown in the graph (cwnd in segments vs. time in RTT): cwnd grows 1, 2, 4, 8, then +1 per RTT to 11, drops to ≈9 and grows by 1 to 14, then drops to ≈1 and grows 2, 4, 9 then +1 per RTT to 18, drops to ≈2 and grows 3, 5, 9.5, 17.5 then +1 per RTT.<br>1. Identify the intervals of time when TCP slow start is operating.<br>2. Identify the intervals of time when TCP congestion avoidance is operating.<br>3. After the 7th transmission round, is segment loss detected by a triple duplicate ACK or by a timeout?<br>4. What is the initial value of the slow start threshold (ssthresh)?","img":"MA-3-C.jpg","a":"1. Slow start (exponential growth): ≈ rounds <b>1–4</b> (1→8), <b>13/14–17</b> and <b>26/27–31</b> (each restart after the window falls to ≈1).<br>2. Congestion avoidance (linear, +1 per RTT): ≈ rounds <b>4–7</b>, <b>8–13</b>, <b>17–26</b> and <b>31–35</b>.<br>3. <b>Triple duplicate ACK</b> — cwnd falls only part of the way (≈11 → ≈9) and continues linearly; a timeout would drop it to 1.<br>4. Initial <b>ssthresh = 8</b> segments (exponential growth switches to linear at cwnd = 8).<br><i>Because the points sit between tick marks, graders also accept half-round endpoints (e.g. slow start [0.5, 3.5]).</i>","e":"Chapter 3, slide 98: slow start doubles cwnd every RTT from 1 MSS. Slide 99: when cwnd reaches ssthresh, growth switches from exponential to linear (congestion avoidance) — so the first bend in the curve shows the initial ssthresh. Slide 96: a loss detected by triple duplicate ACK (Reno) cuts cwnd in half; a loss detected by timeout cuts it to 1 MSS.","from":[{"s":"MA","qn":"Q3 C","pg":6}]},{"id":"MC-2-C","ch":3,"sl":"96, 98–99","tp":"TCP Reno cwnd graph","t":"short","q":"Assuming TCP Reno is the protocol experiencing the behavior shown (cwnd in segments vs. round): rounds 1–10: 1, 2, 4, 8, 16, 17, 18, 19, 20, 21; round 11 drops to 1, then 2, 4, 8, 16 (round 15), 17 … 21 (round 20); round 21 drops to ≈10, then grows by 1 per round up to round 30.<br>1. Identify the intervals of time when TCP slow start is operating.<br>2. Identify the intervals of time when TCP congestion avoidance is operating.<br>3. After the 10th transmission round, is segment loss detected by a triple duplicate ACK or by a timeout?<br>4. What is the initial value of the slow start threshold (ssthresh)?","img":"MC-2-C.jpg","a":"1. Slow start: rounds <b>[1, 5]</b> and <b>[11, 15]</b> (exponential growth).<br>2. Congestion avoidance: rounds <b>[5, 10]</b>, <b>[15, 20]</b> and <b>[21, 30]</b> (+1 segment per round).<br>3. <b>Timeout</b> — cwnd drops to 1 MSS (a triple duplicate ACK would only halve it, as happens after round 20).<br>4. Initial <b>ssthresh = 16</b> segments.","e":"Chapter 3, slide 98 (slow start: cwnd starts at 1 MSS and doubles every RTT), slide 99 (switch from exponential to linear when cwnd reaches ssthresh; on loss ssthresh = cwnd/2), slide 96 (Reno halves cwnd on triple duplicate ACK; cwnd → 1 MSS on timeout).","from":[{"s":"MC","qn":"Q2 C","pg":17}]},{"id":"MC-3-B","ch":3,"sl":"66–67","tp":"TCP seq/ack numbers","t":"short","q":"Hosts A and B are using TCP. Complete the missing Seq/Ack numbers.<pre>A → B : Seq # = 500, Ack # = 50, DataLen = 100 bytes\nB → A : Seq # = ??,  Ack # = ??, DataLen = 120 bytes\nA → B : Seq # = ??,  Ack # = ??, DataLen = 550 bytes</pre>","a":"<b>B → A:</b> Seq # = <b>50</b>, Ack # = <b>600</b><br><b>A → B:</b> Seq # = <b>600</b>, Ack # = <b>170</b>","e":"Chapter 3, slide 66: seq # = first byte of this segment's data; ACK # = next byte expected. B starts at the byte A expects (50) and acknowledges 500 + 100 = 600. A then sends from 600 and acknowledges 50 + 120 = 170.","from":[{"s":"MC","qn":"Q3 B","pg":19}]},{"id":"BQ21-9","ch":3,"sl":"4, 6","tp":"Transport = logical communication between processes","t":"short","q":"Transport protocols provide logical communication between: ______","a":"<b>Processes</b> (application processes running on different hosts).","e":"Chapter 3, slide 4: transport protocols provide logical communication between application processes running on different hosts. Slide 6: the network layer provides logical communication between hosts.","from":[{"s":"ME","qn":"Q1.8","pg":95},{"s":"BQ21","qn":"Q9","pg":12}]},{"id":"ME-1-13","ch":3,"sl":"20–21","tp":"TCP demux — different sockets","t":"mcq","q":"A process in Host C has a TCP socket with port number 3456. Host A and Host B both use source port number 5666, and each sends a TCP segment to Host C with destination port number 3456. These two segments will be sent to:","o":["the same socket at Host C.","different sockets at Host C."],"a":1,"e":"Chapter 3, slide 20: a TCP socket is identified by the 4-tuple (source IP, source port, dest IP, dest port). The two segments have different source IP addresses, so they are demultiplexed to <b>different</b> sockets (slide 21 example). With UDP they would go to the same socket.","from":[{"s":"ME","qn":"Q1.13","pg":95}]},{"id":"ME-1-14","ch":3,"sl":"26, 64, 95","tp":"TCP has congestion control","t":"mcq","q":"Which of the following is correct for the TCP protocol?","o":["There is no connection establishment.","It has congestion control.","It has a small header size.","It is a simple protocol."],"a":1,"e":"Chapter 3, slide 64 (TCP overview): connection-oriented, flow controlled, congestion control (slides 95–100). The other options describe UDP (slide 26: no connection establishment, simple, small header).","from":[{"s":"ME","qn":"Q1.14","pg":95}]},{"id":"ME-1-15","ch":3,"sl":"43","tp":"Checksum detects errors in ACK/NAK","t":"mcq","q":"Which of the following mechanisms is used by the receiver to enable the sender to detect bit errors in a transmitted ACK/NAK?","o":["Checksum","Timer","Sequence number","ACK"],"a":0,"e":"Chapter 3, slide 43: bit errors are detected with a checksum; to handle corrupted ACK/NAKs the receiver includes a checksum in the ACK/NAK packet so the sender can detect the corruption (rdt2.1/2.2).","from":[{"s":"ME","qn":"Q1.15","pg":96}]},{"id":"ME-1-16","ch":3,"sl":"43–44, 48","tp":"Causes of duplicate packets","t":"mcq","q":"A duplicate packet can result from:","o":["error in ACK","lost ACK","delayed ACK","All of the above"],"a":3,"e":"Chapter 3, slide 43: if an ACK/NAK is corrupted the sender retransmits → possible duplicate. Slides 44, 48 (rdt3.0 in action): a lost ACK or a delayed ACK (premature timeout) makes the sender retransmit a packet the receiver already has → duplicate, detected by the sequence number.","from":[{"s":"ME","qn":"Q1.16","pg":96},{"s":"QZ","qn":"Q1.5","pg":248}]},{"id":"ME-1-17","ch":3,"sl":"57","tp":"Individual ACKs = Selective Repeat","t":"mcq","q":"A sender sends two packets unacknowledged one after the other. After some time it receives the individual ACK for the second packet. What kind of protocol is this?","o":["RDT 2.2","RDT 3.0","GBN","Selective Repeat","TCP"],"a":3,"e":"Chapter 3, slide 57: in Selective Repeat the receiver <b>individually</b> acknowledges all correctly received packets (and buffers out-of-order ones). rdt2.2/3.0 are stop-and-wait (only one unACKed packet); GBN and TCP use cumulative ACKs.","from":[{"s":"ME","qn":"Q1.17","pg":96},{"s":"M16","qn":"Q1.3","pg":231}]},{"id":"ME-1-18","ch":3,"sl":"61–62","tp":"SR window size vs seq # space","t":"mcq","q":"If the sequence numbers for the Selective Repeat protocol are [0–15], then to avoid any conflict the window size must be:","o":["15 or less","7 or less","15","10 or less"],"a":1,"e":"Chapter 3, slides 61–62 (Selective repeat: a dilemma): the receiver can't tell a new packet from a retransmission if the window is too large; the window size must be ≤ half the sequence-number space. 16 numbers → window ≤ 8.<br><i>Note:</i> by the strict rule the largest safe window is <b>8</b>; among the given options, \"7 or less\" is the only one that is always safe (15 and 10 are too large), so it is the expected answer.","from":[{"s":"ME","qn":"Q1.18","pg":96},{"s":"M16","qn":"Q1.7","pg":231}]},{"id":"ME-1-19","ch":3,"sl":"66","tp":"Segment size from seq numbers","t":"mcq","q":"Host A sends two TCP segments back-to-back to Host B. The first segment has sequence number 10; the second has sequence number 102. The size of the first segment is:","o":["1 byte","81 bytes","82 bytes","92 bytes"],"a":3,"e":"Chapter 3, slide 66: sequence numbers count bytes, so the first segment carries 102 − 10 = <b>92 bytes</b>.","from":[{"s":"ME","qn":"Q1.19","pg":96},{"s":"M16","qn":"Q2.1","pg":232}]},{"id":"ME-1-20","ch":3,"sl":"30–31","tp":"UDP has error detection","t":"tf","q":"There is no error detection in UDP.","a":1,"e":"Chapter 3, slides 30–31: the UDP header has a <b>checksum</b> field whose goal is to detect errors (flipped bits) in the transmitted segment. <b>False</b>.","from":[{"s":"ME","qn":"Q1.20","pg":96}]},{"id":"ME-2-B","ch":3,"sl":"31–33","tp":"Internet checksum calculation","t":"short","q":"Calculate the checksum value of the following 16-bit segments:<pre>1001001110010011\n1001100001001101</pre>","a":"<pre>  1001001110010011\n+ 1001100001001101\n= 1 0010101111100000   (carry out)\nwraparound: 0010101111100000 + 1\nsum      =  0010101111100001\nchecksum =  1101010000011110   (1s complement)</pre>Checksum = <b>1101010000011110</b>","e":"Chapter 3, slide 32 (UDP checksum, sender): treat contents as a sequence of 16-bit integers, add them (one's complement sum) and put the one's complement of the sum in the checksum field. Slide 33 (Internet checksum example): when adding numbers, a carryout from the most significant bit is added back to the result (wraparound).","from":[{"s":"ME","qn":"Q2 B","pg":97}]},{"id":"ME-5","ch":3,"sl":"54–56","tp":"Go-Back-N scenario","t":"short","q":"Go-Back-N with window size <b>4</b> and sequence numbers <b>[0, 7]</b>. The sender has 5 packets (pkt0–pkt4). pkt1 is lost, pkt2 arrives with errors, the other packets arrive correctly. Describe the scenario: packet and ACK sequence numbers, sender window, rcv_base (expected seq #) at the receiver, and which packet's timeout fires.","a":"1. Sender window [0 1 2 3] → sends pkt0, pkt1, pkt2, pkt3.<br>2. pkt0 arrives OK → receiver sends <b>ACK0</b>, expected = 1.<br>3. pkt1 is lost.<br>4. pkt2 arrives corrupted → discarded, re-send <b>ACK0</b> (expected still 1).<br>5. pkt3 arrives out of order → discarded, re-send <b>ACK0</b>.<br>6. ACK0 reaches the sender → window slides to [1 2 3 4] → sends <b>pkt4</b>; it arrives out of order → discarded, <b>ACK0</b>. Duplicate ACK0s are ignored.<br>7. <b>pkt1's timer times out</b> → the sender retransmits pkt1, pkt2, pkt3, pkt4 (go back N).<br>8. Receiver accepts them in order → ACK1, ACK2, ACK3, ACK4 (expected 2, 3, 4, 5); the sender window slides to [2 3 4 5], [3 4 5 6], [4 5 6 7], [5 6 7 0].","e":"Chapter 3, slide 54 (GBN sender): window of up to N consecutive unACKed packets; cumulative ACK(n) moves the window to n+1; a single timer for the oldest in-flight packet; timeout(n) retransmits packet n and all higher seq # packets in the window. Slide 55 (GBN receiver): always ACK the highest in-order seq # received; on out-of-order (or corrupted) packets, discard and re-ACK the highest in-order packet. Slide 56 shows the same pattern.","from":[{"s":"ME","qn":"Q5","pg":101}],"aimg":"ME-5-ans.jpg"},{"id":"MF-5-1","ch":3,"sl":"31","tp":"Purpose of checksum","t":"short","q":"What is the purpose of using a checksum in data communication?","a":"To <b>detect errors</b> (flipped bits) in the transmitted segment: the sender puts the 1s-complement sum of the data in the checksum field; the receiver recomputes it and, if it doesn't match, an error is detected.","e":"Chapter 3, slide 31 (UDP checksum) — Goal: detect errors (i.e. flipped bits) in transmitted segment. Slide 32 describes the sender and receiver steps.","from":[{"s":"MF","qn":"Q5.1","pg":105}]},{"id":"MF-5-2","ch":3,"sl":"87, 90","tp":"Cost of congestion","t":"mcq","q":"One of the following is the cost of congestion in networks:","o":["Increasing the packet delay","Increasing packet loss ratio","Decreasing the maximum achievable throughput","All the above"],"a":3,"e":"Chapter 3, slide 87: long delays (queueing in router buffers) and packet loss (buffer overflow). Slide 90: decreasing maximum achievable throughput, plus wasted retransmissions.","from":[{"s":"MF","qn":"Q5.2","pg":105}]},{"id":"MF-5-3","ch":3,"sl":"18–19","tp":"One UDP socket, many clients","t":"tf","q":"It is possible for two UDP segments to be sent from the same socket with source port 5723 at a server to two different clients.","a":0,"e":"Chapter 3, slides 18–19 (Connectionless demultiplexing): a UDP socket is identified only by its local port; when creating a datagram to send into the socket you specify any destination IP and port. A server with one UDP socket (e.g. port 6428 in the slide example) answers many clients from the same source port. <b>True</b>.","from":[{"s":"MF","qn":"Q5.3","pg":105}]},{"id":"MF-5-4","ch":3,"sl":"32–33","tp":"Internet checksum calculation","t":"short","q":"Calculate the Internet checksum for the following two 16-bit words:<pre>10010010 01110011\n11111001 11100010</pre>","a":"<pre>  1001001001110011\n+ 1111100111100010\n= 1 1000110001010101   (carry out)\nwraparound: + 1\nsum      =  1000110001010110\nchecksum =  0111001110101001</pre>Checksum = <b>0111001110101001</b>","e":"Chapter 3, slides 32–33: add the 16-bit words, add any carry out of the most significant bit back into the result (wraparound), then take the 1s complement (flip every bit).","from":[{"s":"MF","qn":"Q5.4","pg":105}]},{"id":"MF-5-5","ch":3,"sl":"66, 69","tp":"TCP seq numbers with lost segments","t":"short","q":"A TCP sender sends an initial window of 5 segments at t = 1, 2, 3, 4, 5. The initial sequence number is <b>110</b> and every segment carries <b>874 bytes</b>. One-way delay = 7 time units (segment sent at t=1 arrives at t=8). The segments sent at <b>t = 3 and t = 4 are lost</b>; no ACKs are lost; no timeouts; out-of-order segments are thrown out.<br>1–4) Sequence numbers of the segments sent at t = 1, 2, 3, 4?<br>5–8) Value of the ACK sent by the receiver at t = 8, 10, 11, 12? (write 'x' if the segment was lost)","img":"MF-5-5.jpg","a":"Seq numbers: t=1 → <b>110</b>; t=2 → <b>984</b>; t=3 → <b>1858</b>; t=4 → <b>2732</b> (t=5 → 3606).<br>ACKs: t=8 → <b>984</b>; (t=9 → 1858); t=10 → <b>x</b>; t=11 → <b>x</b>; t=12 → <b>1858</b> (segment 5 arrives out of order and is thrown out, so the receiver repeats the cumulative ACK for the next byte it still expects).","e":"Chapter 3, slide 66: seq # = byte-stream number of the first data byte; each segment adds 874. The ACK # is the next expected byte (cumulative ACK). Slide 69 (TCP receiver ACK generation): arrival of an out-of-order segment with a higher-than-expected seq # (a gap) → immediately send a duplicate ACK indicating the seq # of the next expected byte.","from":[{"s":"MF","qn":"Q5.5","pg":104}]},{"id":"MG-3-1","ch":3,"sl":"66, 69","tp":"TCP seq/ACK with lost segments (ISN 25)","t":"short","q":"A TCP sender sends a window of 5 segments at t = 1, 2, 3, 4, 5. The initial sequence number is <b>25</b> and each segment carries <b>460 bytes</b>. Delay = 7 time units (first segment arrives at t = 8). Segments sent at <b>t = 3 and t = 4 are lost</b>; no ACKs are lost; no timeouts; out-of-order segments are thrown out.<br>1–5) Sequence numbers of the segments sent at t = 1…5?<br>6) The value of the ACK sent at t = 8?<br>7) The ACK sent at t = 9?<br>8) The ACK sent at t = 11? (x if no segment arrives)","a":"Seq: t=1 → <b>25</b>, t=2 → <b>485</b>, t=3 → <b>945</b>, t=4 → <b>1405</b>, t=5 → <b>1865</b>.<br>ACK at t=8 → <b>485</b>; t=9 → <b>945</b>; t=10 and t=11 → <b>x</b> (those segments were lost); t=12 → <b>945</b> again (segment 5 is out of order, so it is a duplicate ACK).","e":"Chapter 3, slide 66: each segment's seq # = previous seq # + 460. The ACK # is the next byte expected. Slide 69: an out-of-order segment (gap detected) triggers an immediate duplicate ACK for the next expected byte (945).","from":[{"s":"MG","qn":"Q3 Part1","pg":108},{"s":"MG","qn":"Q3 Part1 (cont.)","pg":110}],"aimg":"MG-3-1-ans.jpg"},{"id":"MG-3-2","ch":3,"sl":"32–33","tp":"Internet checksum calculation","t":"short","q":"Calculate the Internet checksum for the following two 16-bit words:<pre>10110100 01000110\n11001000 01101110</pre>","a":"<pre>  1011010001000110\n+ 1100100001101110\n= 1 0111110010110100  (carry out)\nwraparound: + 1\nsum      =  0111110010110101\nchecksum =  1000001101001010</pre>Checksum = <b>1000001101001010</b>","e":"Chapter 3, slides 32–33: one's-complement sum with wraparound of the carry, then flip all bits.","from":[{"s":"MG","qn":"Q3 Part2","pg":110}]},{"id":"MG-3-3","ch":3,"sl":"32–33","tp":"Internet checksum calculation","t":"short","q":"Calculate the Internet checksum for the following two 16-bit words:<pre>01110110 00010011\n01100010 00101101</pre>","a":"<pre>  0111011000010011\n+ 0110001000101101\n= 1101100001000000   (no carry out)\nchecksum = 0010011110111111</pre>Checksum = <b>0010011110111111</b>","e":"Chapter 3, slides 32–33: add the words; there is no carry out of the MSB so no wraparound is needed; the checksum is the 1s complement of the sum.","from":[{"s":"MG","qn":"Q3 Part2 (variant)","pg":110}]},{"id":"MH-1-10","ch":3,"sl":"4","tp":"Transport runs in end systems","t":"mcq","q":"Where is transport-layer functionality primarily implemented?","o":["At the hosts at the \"edge\" of the network.","At the routers and switches in the network.","At each end of a physical link connecting one host/router/switch to another."],"a":0,"e":"Chapter 3, slide 4: transport protocols <b>actions in end systems</b>: sender breaks application messages into segments and passes them to the network layer; receiver reassembles segments into messages. Routers only go up to the network layer (Chapter 1, slide 66).","from":[{"s":"MH","qn":"Q1.10","pg":117}]},{"id":"MH-1-11","ch":3,"sl":"20","tp":"TCP socket = 4-tuple","t":"mcq","q":"In TCP-based demultiplexing, TCP sockets are identified by:","o":["destination IP address and port number","source IP address and port number","both destination and source IP addresses and port numbers","destination port number"],"a":2,"e":"Chapter 3, slide 20: a TCP socket is identified by the 4-tuple — source IP, source port, destination IP, destination port.","from":[{"s":"MH","qn":"Q1.11","pg":118}]},{"id":"MH-1-12","ch":3,"sl":"71","tp":"Cumulative ACK covers lost ACK","t":"mcq","q":"Host A sends two segments to Host B. B sends an acknowledgment for each. The first ACK is lost, but the second ACK arrives at A before the timer for the first segment expires. Then:","o":["Host A will retransmit both the first and the second segments","Host A will retransmit the first segment only","Host A will not retransmit any segment","None of the above"],"a":2,"e":"Chapter 3, slide 71 (TCP retransmission scenarios — cumulative ACK covers for earlier lost ACK): TCP ACKs are cumulative, so the second ACK confirms both segments and nothing is retransmitted.","from":[{"s":"MH","qn":"Q1.12","pg":118}]},{"id":"MH-1-14","ch":3,"sl":"32–33","tp":"Internet checksum (MCQ)","t":"mcq","q":"Compute the Internet checksum value for these two 16-bit words:<pre>11110101 11010011\n10110011 01000100</pre>","o":["01010110 11101000","01010110 11100111","01011110 11000101","01101110 11010101"],"a":1,"e":"Chapter 3, slides 32–33: 1111010111010011 + 1011001101000100 = 1 1010100100010111 → wraparound +1 → 1010100100011000 → 1s complement = <b>0101011011100111</b>.","from":[{"s":"MH","qn":"Q1.14","pg":118}]},{"id":"MH-3","ch":3,"sl":"66, 72, 96–97","tp":"Reno: dup ACKs & fast retransmit","t":"short","q":"Using TCP Reno, a sender transmits 5 segments back-to-back with sequence numbers <b>1000, 2400, 3600, 4800, 6000</b>. It receives five ACKs: <b>2400, 2400, 2400, 2400, 7200</b>.<br>a. Describe the segments exchanged (which segment was lost, what happens).<br>b. What is the size of the first segment?<br>c. What will ssthresh be after receiving the 4th ACK, if cwnd = 8000 bytes before that moment?","a":"a. Segment <b>2400 is lost</b>. Segment 1000 → ACK 2400. Segments 3600, 4800, 6000 arrive out of order → three <b>duplicate ACK 2400</b>s. After the third duplicate (the 4th ACK) the sender does a <b>fast retransmit</b> of segment 2400 (no timeout needed). The receiver now has everything up to byte 7199 → cumulative <b>ACK 7200</b>.<br>b. 2400 − 1000 = <b>1400 bytes</b>.<br>c. Triple duplicate ACK → ssthresh = cwnd/2 = <b>4000 bytes</b> (and Reno sets cwnd = ssthresh + 3 MSS, fast recovery).","e":"Chapter 3, slide 66: seq #s count bytes, so segment size = next seq − this seq. Slide 69: an out-of-order segment triggers an immediate duplicate ACK. Slide 72 (fast retransmit): 3 duplicate ACKs → resend the unACKed segment with the smallest seq #. Slides 96–97: on triple duplicate ACK, Reno halves cwnd (ssthresh = cwnd/2). The last segment's ACK, 7200, means the last segment held 1200 bytes.","from":[{"s":"MH","qn":"Q3","pg":120}],"aimg":"MH-3-ans.jpg"},{"id":"M23-1-1","ch":3,"sl":"98","tp":"Slow start doubles per RTT","t":"tf","q":"In slow start, a sender doubles its window size every RTT if all sent packets were acknowledged.","a":0,"e":"Chapter 3, slide 98: initially cwnd = 1 MSS; double cwnd every RTT, done by incrementing cwnd for every ACK received. <b>True</b>.","from":[{"s":"M23","qn":"Q1.1","pg":122}]},{"id":"M23-1-2","ch":3,"sl":"95","tp":"Additive increase = 1 MSS per RTT","t":"tf","q":"In additive increase, a sender increases its window size by one MSS for each acknowledgement.","a":1,"e":"Chapter 3, slide 95 (AIMD): additive increase — increase the sending rate by 1 maximum segment size <b>every RTT</b> until loss is detected, not per ACK. (+1 MSS per ACK is slow start's exponential growth.) <b>False</b>.","from":[{"s":"M23","qn":"Q1.2","pg":122}]},{"id":"M23-1-3","ch":3,"sl":"96","tp":"Timeout → cwnd = 1 MSS","t":"tf","q":"After detecting packet loss through a timeout, TCP halves its window size as a response to the path congestion.","a":1,"e":"Chapter 3, slide 96: on a loss detected by <b>timeout</b>, cwnd is cut to 1 MSS; halving happens on a triple duplicate ACK (TCP Reno). <b>False</b>.","from":[{"s":"M23","qn":"Q1.3","pg":122}]},{"id":"M23-2-7","ch":3,"sl":"4–6","tp":"Not a transport service","t":"mcq","q":"Which of the following is <b>not</b> a transport layer service?","o":["multiplexing, demultiplexing","reliable data transfer","communication between processes","communication between hosts"],"a":3,"e":"Chapter 3, slide 6: the network layer provides logical communication between <b>hosts</b>; the transport layer provides logical communication between <b>processes</b>. Slide 2: transport services include multiplexing/demultiplexing, reliable data transfer, flow control and congestion control.","from":[{"s":"M23","qn":"Q2.7","pg":123}]},{"id":"M23-2-8","ch":3,"sl":"15","tp":"Mux at sender, demux at receiver","t":"mcq","q":"Which of the following is correct about transport-layer multiplexing and demultiplexing?","o":["Multiplexing at sender and demultiplexing at receiver","Multiplexing at receiver and demultiplexing at sender","Multiplexing at router and demultiplexing at receiver","Multiplexing at receiver and demultiplexing at router"],"a":0,"e":"Chapter 3, slide 15: multiplexing <b>at sender</b> — handle data from multiple sockets, add transport header; demultiplexing <b>at receiver</b> — use header info to deliver received segments to the correct socket.","from":[{"s":"M23","qn":"Q2.8","pg":123}]},{"id":"M23-2-9","ch":3,"sl":"24, 26","tp":"UDP has no congestion control","t":"mcq","q":"Which of the following is <b>false</b> regarding UDP?","o":["each UDP segment handled independently of others","UDP provides best effort service","UDP provides congestion control","no handshaking between UDP sender, receiver"],"a":2,"e":"Chapter 3, slide 24: best effort, connectionless, no handshaking, each segment handled independently. Slide 26: <b>no congestion control</b> — UDP can blast away as fast as desired.","from":[{"s":"M23","qn":"Q2.9","pg":123}]},{"id":"M23-2-10","ch":3,"sl":"25","tp":"Protocols over UDP","t":"mcq","q":"Which of the following protocols uses UDP?","o":["DNS","SNMP","HTTP/3","All of the above"],"a":3,"e":"Chapter 3, slide 25 (UDP use): streaming multimedia, DNS, SNMP, HTTP/3.","from":[{"s":"M23","qn":"Q2.10","pg":124}]},{"id":"M23-2-11","ch":3,"sl":"65, 74–77","tp":"Receive window field","t":"mcq","q":"Which of the following TCP segment fields is used for performing flow control?","o":["Sequence number","Acknowledgement number","Receive window","None of the above"],"a":2,"e":"Chapter 3, slide 65 (TCP segment structure): \"receive window\" — flow control: # bytes the receiver is willing to accept. Slides 74–77: the receiver advertises free buffer space in the rwnd field.","from":[{"s":"M23","qn":"Q2.11","pg":124},{"s":"PJ","qn":"Q1.6","pg":237}]},{"id":"M23-2-12","ch":3,"sl":"74","tp":"Flow control problem statement","t":"mcq","q":"In TCP, which technique is responsible for solving this problem: \"the network layer delivers data faster than the application layer removes data from socket buffers\"?","o":["Error control","Flow control","Congestion control","All of the above"],"a":1,"e":"Chapter 3, slide 74 (TCP flow control) opens with exactly this question: Q: What happens if the network layer delivers data faster than the application layer removes data from socket buffers? A: flow control — the receiver controls the sender so it won't overflow the receiver's buffer.","from":[{"s":"M23","qn":"Q2.12","pg":124}]},{"id":"M23-3-B","ch":3,"sl":"83","tp":"Draw the 3-way handshake","t":"short","q":"Diagrammatically represent the TCP 3-way handshake.","a":"<pre>Client (LISTEN)                         Server (LISTEN)\n  choose init seq x\n  ── SYN (SYNbit=1, Seq=x) ──────────►   SYNRCVD\n                                         choose init seq y\n  ◄── SYNACK (SYNbit=1, Seq=y,\n          ACKbit=1, ACKnum=x+1) ──────\n  ESTAB\n  ── ACK (ACKbit=1, ACKnum=y+1) ─────►   ESTAB\n     (may carry client-to-server data)</pre>","e":"Chapter 3, slide 83 (TCP 3-way handshake): client sends SYN with seq x; server replies SYNACK acking x+1 with its own seq y; client sends ACK for y+1 (this segment may contain data); both sides are then ESTAB.","from":[{"s":"M23","qn":"Q3 B","pg":125}]},{"id":"MJ-1-3","ch":3,"sl":"22, 24, 26","tp":"UDP provides multiplexing","t":"mcq","q":"UDP protocol:","o":["provides flow control service.","provides congestion control service.","provides multiplexing service.","provides connection-oriented service."],"a":2,"e":"Chapter 3, slide 22: UDP demultiplexes using the destination port number — it provides multiplexing/demultiplexing (plus checksum). Slides 24 and 26: it is connectionless, with no flow control and no congestion control.","from":[{"s":"MJ","qn":"Q1.3","pg":146}]},{"id":"MJ-1-4","ch":3,"sl":"32–33","tp":"Checksum (MCQ)","t":"mcq","q":"What is the checksum of the 16-bit words <code>0101010101010101</code> and <code>0000000010101010</code>?","o":["0101010101010101","1010101000000000","0101010111111111","0101010100000000"],"a":1,"e":"Chapter 3, slides 32–33: sum = 0101010111111111 (no carry out of the MSB, so no wraparound); checksum = 1s complement = <b>1010101000000000</b>. Option C is the sum, not the checksum.","from":[{"s":"MJ","qn":"Q1.4","pg":146}]},{"id":"MJ-1-5","ch":3,"sl":"31","tp":"Checksum detects errors","t":"mcq","q":"The checksum is used:","o":["to detect duplicates.","to detect lost packets.","to detect channel transmission errors.","to correct channel transmission errors."],"a":2,"e":"Chapter 3, slide 31: goal of the checksum — detect errors (flipped bits) in the transmitted segment. It can't correct them; duplicates are detected with sequence numbers and losses with timers.","from":[{"s":"MJ","qn":"Q1.5","pg":146}]},{"id":"MJ-1-6","ch":3,"sl":"49–51","tp":"Stop-and-wait","t":"mcq","q":"In the Stop-and-Wait protocol,","o":["you can send as many segments as you want without waiting for acknowledgment.","you can send a maximum of N (fixed) segments without waiting for acknowledgment.","you can't send the next segment until you receive the acknowledgment of the current one.","you can send only two segments without waiting for acknowledgement."],"a":2,"e":"Chapter 3, slides 49–51 (rdt3.0: stop-and-wait operation): the sender sends one packet, then waits for the receiver's response (ACK) before sending the next. Option B describes the pipelined Go-Back-N window.","from":[{"s":"MJ","qn":"Q1.6","pg":146}]},{"id":"MJ-2","ch":3,"sl":"65, 83","tp":"Decode a TCP header (hex)","t":"short","q":"A TCP segment (hex) sent by host A to host B:<pre>01 bb d9 3c d1 89 c8 6d 1e 5c d6 6f 70 12 10 2c\n15 c4 00 00 02 04 05 64 04 02 00 00</pre>Layout: source port (16) · dest port (16) · seq # (32) · ack # (32) · HLEN (4) · reserved (6) · U A P R S F · window (16) · checksum (16) · urgent pointer (16) · options.<br>1. Source port (hex)?<br>2. Destination port (hex)?<br>3. Which flags U, A, P, R, S, F are set to 1?<br>4. Acknowledgement number (hex)?<br>5. Which phase is the connection in (setup, data transfer, release)?","img":"MJ-2.jpg","a":"1. <b>01bb</b> (= 443)<br>2. <b>d93c</b><br>3. Byte <code>12</code> = 0001 0010 → <b>A (ACK) and S (SYN)</b><br>4. <b>1e5cd66f</b> (seq # is d189c86d)<br>5. <b>Connection setup</b> — SYN + ACK together is the SYNACK, the 2nd message of the 3-way handshake.<br>(Also: HLEN = 7 → 28-byte header, window = 102c, checksum = 15c4.)","e":"Chapter 3, slide 65 (TCP segment structure): source port #, dest port #, sequence number, acknowledgement number, header length, flag bits (C E U A P R S F), receive window, checksum, urgent data pointer, options. Slide 83: the server replies to a SYN with a SYNACK (SYNbit = 1, ACKbit = 1).","from":[{"s":"MJ","qn":"Q2","pg":147}]},{"id":"MJ-3","ch":3,"sl":"96, 98–99","tp":"TCP Reno graph (70 rounds)","t":"short","q":"Assuming TCP Reno is the protocol experiencing the behaviour in the figure (cwnd in segments vs. transmission round 0–70):<br>1. Identify intervals where TCP slow start is operating.<br>2. Identify intervals where congestion avoidance is operating.<br>3. What is ssthresh at transmission round 10?<br>4. Identify round(s) where a segment loss is detected by a timeout.<br>5. Identify round(s) where a loss is detected by 3 duplicate ACKs.<br>6. During which transmission round is the 20th segment sent?<br>7. What is cwnd at round 67 if no segment loss is detected?","img":"MJ-3.jpg","a":"1. Slow start: <b>[1, 6], [7, 11], [56, 60]</b><br>2. Congestion avoidance: <b>[11, 19], [20, 36], [37, 55], [60, 66]</b><br>3. ssthresh = <b>16</b> (cwnd was 32 at the timeout after round 6; growth turns linear at 16)<br>4. Timeouts: after rounds <b>6 and 55</b> (cwnd drops to 1)<br>5. Triple duplicate ACK: after rounds <b>19 and 36</b> (cwnd halves)<br>6. Round 1 sends seg 1, round 2 segs 2–3, round 3 segs 4–7, round 4 segs 8–15, round 5 segs 16–31 → the 20th is sent in round <b>5</b><br>7. cwnd = <b>23</b> (17 at round 61, +1 per round)","e":"Chapter 3, slide 98: slow start doubles cwnd per RTT. Slide 99: switch to linear when cwnd reaches ssthresh; ssthresh = cwnd/2 on loss. Slide 96: timeout → cwnd = 1 MSS; triple duplicate ACK (Reno) → cwnd halved. The key also accepts the next-round numbering (7, 56 / 20, 37).","from":[{"s":"MJ","qn":"Q3","pg":149}]},{"id":"MK-3-2","ch":3,"sl":"66, 69","tp":"TCP window of 3, 2nd segment late","t":"short","q":"A TCP sender sends an initial window of 3 segments. The initial sequence number is <b>250</b> and each segment carries <b>100 bytes</b>. The <b>2nd segment arrives late</b> (after the 3rd, but before timeout). Give the 3 sequence numbers and the 3 ACK numbers.","img":"MK-3-2.jpg","a":"Seq #: <b>250, 350, 450</b>.<br>ACKs (in arrival order): 1st segment → <b>ACK 350</b>; 3rd segment (out of order) → duplicate <b>ACK 350</b>; 2nd segment fills the gap → <b>ACK 550</b> (cumulative, covers segments 2 and 3).","e":"Chapter 3, slide 66: seq # = first byte of the segment, ACK # = next byte expected (cumulative). Slide 69: out-of-order arrival → immediately send a duplicate ACK; arrival of a segment that fills a gap → immediately send an ACK for the new in-order end.","from":[{"s":"MK","qn":"Q3.2","pg":152}]},{"id":"MK-1-2","ch":3,"sl":"43","tp":"Purpose of ACKs","t":"mcq","q":"What is the purpose of acknowledgments (ACKs) in reliable data transfer?","o":["To confirm the receipt of packets","To request retransmission of lost packets","To establish a connection","To encrypt the data"],"a":0,"e":"Chapter 3, slide 43: acknowledgements (ACKs) — the receiver explicitly tells the sender that the packet was received OK. (Requesting retransmission is a NAK's job.)","from":[{"s":"MK","qn":"Q1.2","pg":153}]},{"id":"MK-1-3","ch":3,"sl":"72","tp":"Triple duplicate ACK principle","t":"mcq","q":"Which protocol works on the principle: \"if the sender receives 3 additional ACKs for the same data (triple duplicate ACKs), resend the unACKed segment with the smallest sequence number\"?","o":["Go-Back-N","Selective repeat","TCP Fast retransmission","None of the above"],"a":2,"e":"Chapter 3, slide 72 (TCP fast retransmit) states exactly this rule.","from":[{"s":"MK","qn":"Q1.3","pg":153}]},{"id":"FA-1-4","ch":3,"sl":"4, 14 (ch2), 37","tp":"Reliable delivery = transport","t":"mcq","q":"Which layer of the Internet model is responsible for ensuring reliable delivery of packets?","o":["Application layer.","Transport layer.","Network layer.","Link layer."],"a":1,"e":"Chapter 3, slides 37–40 (Principles of reliable data transfer) and Chapter 2, slide 14: TCP, a <b>transport</b>-layer protocol, provides reliable transport between sending and receiving processes over the unreliable network layer (IP is best effort).","from":[{"s":"FA","qn":"Q1 A.4","pg":26}]},{"id":"FA-1-12","ch":3,"sl":"87, 90, 92","tp":"Costs of congestion","t":"mcq","q":"Which one of the following is a cost of network congestion:","o":["Increasing the end-to-end delay","Increasing packet loss ratio","Decreasing the maximum achievable throughput","None of the above","All the above (A, B, C)"],"a":4,"e":"Chapter 3, slide 87: congestion shows up as long delays (queueing in router buffers) and packet loss (buffer overflow at routers). Slide 90: \"costs\" of congestion include more retransmission work, unneeded retransmissions and a <b>decreasing maximum achievable throughput</b>. Slide 92: upstream capacity used for dropped packets is wasted.","from":[{"s":"FA","qn":"Q1 A.12","pg":30},{"s":"FF","qn":"Q1.12","pg":279}]},{"id":"FA-1-14","ch":3,"sl":"25","tp":"Apps that use UDP","t":"mcq","q":"Which of the following application protocols uses UDP protocol?","o":["HTTP/3","DNS","DHCP","SNMP","All the above"],"a":4,"e":"Chapter 3, slide 25 (UDP use): streaming multimedia apps, <b>DNS</b>, <b>SNMP</b>, <b>HTTP/3</b>. DHCP also runs over UDP (ports 67/68; covered with the network layer). So all of them use UDP.","from":[{"s":"FA","qn":"Q1 A.14","pg":30},{"s":"FF","qn":"Q1.14","pg":279}]},{"id":"FA-UDP","ch":3,"sl":"24–26, 30–35","tp":"Describe UDP","t":"short","q":"Describe User Datagram Protocol (UDP): what are its main features and usage, and why is it there although of its limitations?","a":"<b>Features:</b> \"no frills, bare bones\" best-effort transport — segments may be lost or delivered out of order; <b>connectionless</b> (no handshaking, each segment handled independently); small 8-byte header (source port, dest port, length, checksum); <b>checksum</b> for error detection; no reliability, no flow control, no congestion control.<br><b>Usage:</b> streaming multimedia (loss tolerant, rate sensitive), DNS, SNMP, HTTP/3.<br><b>Why UDP exists:</b> no connection establishment (which can add an RTT of delay); simple — no connection state at sender or receiver; small header size; no congestion control, so UDP can blast away as fast as desired and can function in the face of congestion. If reliability is needed, it can be added at the application layer (e.g. HTTP/3).","e":"Chapter 3, slide 24 (UDP: \"no frills\", best effort, connectionless), slide 25 (UDP use, reliability added at the application layer for HTTP/3), slide 26 (Why is there a UDP? — no connection establishment, simple, small header, no congestion control), slide 30 (UDP segment header), slides 31–35 (checksum and summary).","from":[{"s":"FA","qn":"Q2 B","pg":35},{"s":"FF","qn":"Q (UDP essay)","pg":277}]},{"id":"FB-TF-1","ch":3,"sl":"4","tp":"Transport = process-to-process","t":"tf","q":"Transport layer is responsible for logical communication between processes running on different hosts.","a":0,"e":"Chapter 3, slide 4: transport protocols provide logical communication between application processes running on different hosts. <b>True</b>.","from":[{"s":"FB","qn":"Q1 B.1","pg":43}]},{"id":"FB-TF-2","ch":3,"sl":"15–16","tp":"Multiplexing vs demultiplexing","t":"tf","q":"In multiplexing, the sender uses header info to deliver received segments to the correct socket.","a":1,"e":"Chapter 3, slide 15: <b>multiplexing</b> at the sender = handle data from multiple sockets and add the transport header (later used for demultiplexing). <b>Demultiplexing</b> at the receiver = use header info to deliver received segments to the correct socket. The statement describes demultiplexing, so it is <b>False</b>.","from":[{"s":"FB","qn":"Q1 B.2","pg":43}]},{"id":"FB-TF-3","ch":3,"sl":"18, 22","tp":"UDP demux by destination port","t":"tf","q":"UDP: demultiplexing using destination port number only.","a":0,"e":"Chapter 3, slide 22 (Summary): UDP demultiplexing uses the destination port number (only); TCP uses the 4-tuple. <b>True</b>.","from":[{"s":"FB","qn":"Q1 B.3","pg":43},{"s":"FE","qn":"Q1 B.5","pg":161}]},{"id":"FB-TF-4","ch":3,"sl":"22","tp":"Mux/demux at all layers","t":"tf","q":"Multiplexing/demultiplexing happen only at the transport layer.","a":1,"e":"Chapter 3, slide 22 (Summary): multiplexing/demultiplexing happen at <b>all layers</b>. <b>False</b>.","from":[{"s":"FB","qn":"Q1 B.4","pg":43}]},{"id":"FB-TF-5","ch":3,"sl":"55, 57","tp":"SR vs GBN ACKs","t":"tf","q":"Selective repeat always sends ACK for the correctly-received packet so far, with the highest in-order seq #.","a":1,"e":"Chapter 3, slide 55: that is the <b>Go-Back-N receiver</b> (ACK-only, cumulative ACK of highest in-order seq #). Slide 57: the Selective Repeat receiver <i>individually</i> acknowledges all correctly received packets and buffers out-of-order packets. <b>False</b>.","from":[{"s":"FB","qn":"Q1 B.5","pg":43}]},{"id":"FC-TF-7","ch":3,"sl":"83","tp":"3-way handshake = 3 messages","t":"tf","q":"Using TCP, three messages are exchanged before a connection exists.","a":0,"e":"Chapter 3, slide 83 (TCP 3-way handshake): SYN, SYNACK, ACK — then both sides are in ESTAB. <b>True</b> (the model answer agrees).","from":[{"s":"FC","qn":"Q1(b).7","pg":50},{"s":"F13","qn":"Q1(b).7","pg":209}]},{"id":"FD-TF-3","ch":3,"sl":"20","tp":"TCP demux uses 4-tuple","t":"tf","q":"The TCP protocol uses two tuples in demultiplexing: the IP address and port number of the destination.","a":1,"e":"Chapter 3, slide 20: TCP demultiplexing uses the <b>4-tuple</b> (source IP, source port, destination IP, destination port). <b>False</b>.","from":[{"s":"FD","qn":"Q1 B.3","pg":155}]},{"id":"F22-13","ch":3,"sl":"6","tp":"Network layer: hosts","t":"mcq","q":"Which layer provides logical communication between <b>hosts</b>?","o":["Application layer","Transport layer","Network layer","Link layer"],"a":2,"e":"Chapter 3, slide 6: network layer — logical communication between hosts; transport layer — logical communication between processes (relies on and enhances network-layer services).","from":[{"s":"F22","qn":"Q13","pg":158}]},{"id":"F22-14","ch":3,"sl":"74–77","tp":"Flow control definition","t":"mcq","q":"\"The receiver controls the sender, so the sender won't overflow the receiver's buffer by transmitting too much, too fast.\" This describes:","o":["Congestion control","Flow control","Error control","Fast retransmit"],"a":1,"e":"Chapter 3, slides 74–77: this is the slide's definition of <b>flow control</b>. Congestion control (slide 87) is about too many sources sending too fast for the <i>network</i>.","from":[{"s":"F22","qn":"Q14","pg":158}]},{"id":"FE-1-4","ch":3,"sl":"64","tp":"TCP: in-order delivery","t":"mcq","q":"The Transmission Control Protocol (TCP) provides:","o":["a connection-less service.","unreliable delivery.","best-effort delivery.","in-sequence delivery"],"a":3,"e":"Chapter 3, slide 64 (TCP overview): reliable, <b>in-order byte stream</b>; connection-oriented (handshaking). Connectionless, unreliable, best-effort describe UDP (slide 24).","from":[{"s":"FE","qn":"Q1 A.4","pg":167}]},{"id":"QZ-1","ch":3,"sl":"22, 30–31","tp":"UDP provides","t":"mcq","q":"UDP provides:","o":["process-to-process delivery","host-to-host delivery","error checking","a and c"],"a":3,"e":"Chapter 3, slides 4 and 22: like every transport protocol, UDP delivers data process-to-process (demultiplexing by port). Slides 30–31: the UDP checksum gives error checking. Host-to-host delivery is the network layer's job.","from":[{"s":"QZ","qn":"Q1.1","pg":248}]},{"id":"QZ-2","ch":3,"sl":"15","tp":"Demultiplexing definition","t":"mcq","q":"Using header information to deliver data in a received segment to the correct socket is called:","o":["multiplexing","demultiplexing","delivery service","All of the above"],"a":1,"e":"Chapter 3, slide 15: demultiplexing at the receiver — use header info to deliver received segments to the correct socket.","from":[{"s":"QZ","qn":"Q1.2","pg":248}]},{"id":"QZ-3","ch":3,"sl":"26","tp":"Why UDP servers support more clients","t":"mcq","q":"Servers for applications that run over UDP can support many more clients than TCP. The reason is that UDP ______.","o":["has smaller header size","does not maintain congestion control","does not maintain connection state","None of the above"],"a":2,"e":"Chapter 3, slide 26 (Why is there a UDP?): simple — <b>no connection state at sender, receiver</b>. A TCP server keeps buffers, sequence numbers and congestion-control variables for every connection; a UDP server keeps none, so it can serve more clients.","from":[{"s":"QZ","qn":"Q1.3","pg":248}]},{"id":"QZ-6","ch":3,"sl":"44","tp":"Timer detects loss","t":"mcq","q":"The mechanism that allows the sender to detect lost packets/ACKs is:","o":["Sequence number","Checksum","Timer","Window"],"a":2,"e":"Chapter 3, slide 44: the sender waits a \"reasonable\" amount of time for an ACK and retransmits if no ACK is received in this time — the countdown <b>timer</b>.","from":[{"s":"QZ","qn":"Q1.6","pg":248}]},{"id":"QZ-7","ch":3,"sl":"54–57, 60","tp":"GBN vs SR with one lost packet","t":"short","q":"Host A sends 3 packets (pkt0, pkt1, pkt2) back to back to Host B; expectedseqnum = 0, window size = 3. <b>pkt1 is lost</b>; pkt0 and pkt2 arrive. No more data comes from the upper layer. For <b>GBN</b> and <b>SR</b>:<br>1. What ACK numbers does B send?<br>2. When does A resend?<br>3. Which packet numbers are resent?","img":"QZ-7.jpg","a":"<div class=\"tbl\"><table class=\"mini\"><tr><th></th><th>GBN</th><th>SR</th></tr><tr><td>ACKs from B</td><td>ACK0, ACK0 (pkt2 discarded, duplicate ACK0)</td><td>ACK0, ACK2 (pkt2 buffered)</td></tr><tr><td>When A resends</td><td>When the timer of the oldest unACKed packet (pkt1) expires</td><td>When pkt1's own timer expires</td></tr><tr><td>Resent packets</td><td>pkt1 and pkt2</td><td>pkt1 only</td></tr></table></div>","e":"Chapter 3, slide 54 (GBN sender: one timer, timeout(n) retransmits n and all higher packets in the window), slide 55 (GBN receiver: discard out-of-order, re-ACK highest in-order), slide 57 (SR: individual ACKs, per-packet timers, retransmit only unACKed packets), slide 60 (SR in action).","from":[{"s":"QZ","qn":"Q2","pg":249}]},{"id":"PJ-2","ch":3,"sl":"18–19","tp":"UDP: same dest port → same socket","t":"mcq","q":"Two UDP datagrams holding the same destination port numbers but different source port numbers are directed to:","o":["same socket but different application layer processes","same application layer process","different application layer processes","same application layer process and different sockets"],"a":1,"e":"Chapter 3, slide 18: IP/UDP datagrams with the same destination port # but different source IP addresses and/or source port numbers are directed to the <b>same socket</b> at the receiving host — and so to the same application process.","from":[{"s":"PJ","qn":"Q1.2","pg":237}]},{"id":"PJ-3","ch":3,"sl":"4, 7","tp":"UDP gets data from the app","t":"mcq","q":"In the sending computer, UDP receives a data unit from:","o":["The application layer","The network layer","Both","None"],"a":0,"e":"Chapter 3, slides 4 and 7 (Transport layer actions, sender): it is passed an application-layer message, determines segment header values, creates the segment and passes it to IP.","from":[{"s":"PJ","qn":"Q1.3","pg":237}]},{"id":"PJ-4","ch":3,"sl":"64","tp":"TCP delivers in order","t":"mcq","q":"TCP delivers ______ out-of-order segments to the process.","o":["All","None","Some"],"a":1,"e":"Chapter 3, slide 64: TCP gives a reliable, <b>in-order</b> byte stream; out-of-order segments are held (or discarded) until the gap is filled, never handed to the application out of order.","from":[{"s":"PJ","qn":"Q1.4","pg":237}]},{"id":"PJ-5","ch":3,"sl":"66","tp":"Bytes in first segment (80→110)","t":"mcq","q":"Host A sends two TCP segments back to back to Host B. The first has sequence number 80; the second has 110. The number of bytes in the first segment:","o":["29","30","31","None"],"a":1,"e":"Chapter 3, slide 66: 110 − 80 = <b>30 bytes</b>.","from":[{"s":"PJ","qn":"Q1.5","pg":237}]},{"id":"PJ-7","ch":3,"sl":"76, 97","tp":"rwnd ≠ cwnd","t":"tf","q":"The size of TCP rwnd is also the congestion window.","a":1,"e":"Chapter 3, slide 76: rwnd is the receiver's advertised free buffer space (flow control). cwnd is kept by the sender for congestion control (slides 95–99). They are different windows; the sender is limited by both. <b>False</b>.","from":[{"s":"PJ","qn":"Q1.7","pg":240}]},{"id":"PJ-9","ch":3,"sl":"89–90","tp":"Throughput vs link rate (retransmissions)","t":"mcq","q":"A system's throughput is 10 Mbps, whereas the link transmission rate is 20 Mbps. So:","o":["the number of retransmitted packets is 1/3 of the overall number of transmitted packets","the number of retransmitted packets is 1/2 of the overall number of transmitted packets","every packet is transmitted twice","a and c","b and c"],"a":4,"e":"Chapter 3, slides 89–90 (Causes/costs of congestion, scenario 2): with retransmissions, λ'<sub>in</sub> (original + retransmitted data) is larger than the goodput λ<sub>out</sub>. If the link carries 20 Mbps but only 10 Mbps is useful, every packet is effectively sent twice, so half of all transmitted packets are retransmissions.","from":[{"s":"PJ","qn":"Q1.9","pg":240}]},{"id":"PJ-10","ch":3,"sl":"96, 98–99","tp":"After timeout → slow start","t":"mcq","q":"In TCP congestion detection, if detection is by a timeout, a new ______ phase starts.","o":["slow start","congestion avoidance","congestion detection","none of above"],"a":0,"e":"Chapter 3, slide 96: on a timeout cwnd is cut to 1 MSS. Slide 98: from 1 MSS TCP grows exponentially again — slow start.","from":[{"s":"PJ","qn":"Q1.10","pg":240}]},{"id":"M16-1-2","ch":3,"sl":"43–44","tp":"No loss → no timer","t":"mcq","q":"Which component of reliable data delivery is NOT required if there is no chance of packet loss?","o":["Sequence numbers","Time out","ACK/NACK","Retransmissions","All required"],"a":1,"e":"Chapter 3, slide 43: bit errors alone are handled with checksum, ACK/NAK, retransmission and sequence numbers (rdt2.x). Slide 44: the countdown <b>timer</b> is added only because the channel can <b>lose</b> packets (rdt3.0).","from":[{"s":"M16","qn":"Q1.2","pg":231}]},{"id":"M16-1-8","ch":3,"sl":"64; ch2 14","tp":"Transport services available","t":"mcq","q":"Which of the following services is available in the transport layer of the Internet?","o":["reliability","guaranteed delay","guaranteed bandwidth","All of the above","None of the above"],"a":0,"e":"Chapter 2, slide 14: TCP gives reliable transport but neither TCP nor UDP gives timing (delay) or throughput (bandwidth) guarantees.","from":[{"s":"M16","qn":"Q1.8","pg":231}]},{"id":"M16-2-2","ch":3,"sl":"17–19","tp":"Same host? Check source IP","t":"short","q":"A host receives two UDP segments. How can we tell whether both came from the same host or from different hosts? (Each sending host has one network interface; no NAT.)","a":"Compare the <b>source IP addresses</b> of the two datagrams that carried them — same IP = same host. (The source port alone is not enough: different hosts can use the same port.)","e":"Chapter 3, slide 17: each IP datagram carries a source and destination IP address and one transport-layer segment with source and destination port numbers. Slide 18: UDP delivers by destination port only, so segments from different hosts can land in the same socket — the IP source address tells them apart.","from":[{"s":"M16","qn":"Q2.2","pg":232}]},{"id":"M16-2-3","ch":3,"sl":"76, 97","tp":"How much more can be sent","t":"short","q":"A TCP sender receives an ACK with receive window value <b>X</b>. There are already <b>Y</b> unacknowledged bytes in flight. The new congestion window is <b>Z</b> bytes. How many more bytes can be sent now?","a":"<b>min(X, Z) − Y</b> bytes. If this is negative (or zero), nothing more can be sent yet.","e":"Chapter 3, slide 76 (flow control): the sender limits unACKed (in-flight) data to rwnd. Slide 97 / congestion-control details: in-flight data must also stay ≤ cwnd. So LastByteSent − LastByteAcked ≤ min(cwnd, rwnd).","from":[{"s":"M16","qn":"Q2.3","pg":232}]},{"id":"M16-2-4","ch":3,"sl":"65","tp":"Header-length field sizing","t":"short","q":"A protocol ABC has a fixed header of 32 bytes plus optional header fields.<br>a. What is the minimum size of the header-length field (in bits) if the header size is given in bytes?<br>b. If the header-length field is 5 bits and counts 16-bit words, what is the largest possible size of the options (bytes)?<br>c. If the header length is counted in 32-bit words, what is the smallest value in the header-length field?","a":"a. The smallest header is 32 (= 100000<sub>2</sub>) → at least <b>6 bits</b>.<br>b. Max field value 31 × 2 bytes = 62 bytes header → options ≤ 62 − 32 = <b>30 bytes</b>.<br>c. 32 bytes / 4 bytes per word = <b>8</b>.","e":"Chapter 3, slide 65 (TCP segment structure) has the same idea: TCP's \"header length\" field counts 32-bit words, so a 20-byte header is stored as 5.","from":[{"s":"M16","qn":"Q2.4","pg":233}]},{"id":"M16-4-1","ch":3,"sl":"66, 69–72","tp":"Five segments, six ACKs","t":"short","q":"A TCP sender transmits 5 segments with sequence numbers <b>1200, 2400, 3600, 4800, 6000</b>. It then receives 6 ACKs: <b>2400, 2400, 2400, 2400, 7200, 7200</b>. Describe the events (losses and retransmissions) that explain this.","a":"1. Seg 1200 arrives → <b>ACK 2400</b>.<br>2. Seg <b>2400 is lost</b>.<br>3. Segs 3600, 4800, 6000 arrive out of order → three <b>duplicate ACK 2400</b>s.<br>4. After 3 duplicates the sender <b>fast-retransmits seg 2400</b> → receiver now has everything → cumulative <b>ACK 7200</b>.<br>5. Seg 2400 is sent again (e.g. its timer had already expired — a premature timeout), so the receiver gets a duplicate and replies <b>ACK 7200</b> again.","e":"Chapter 3, slide 69: out-of-order segment → duplicate ACK for the next expected byte; a segment that fills the gap → ACK the new in-order end. Slide 72: fast retransmit on 3 duplicate ACKs. Slide 70: a premature timeout causes an unneeded retransmission and a repeated cumulative ACK.","from":[{"s":"M16","qn":"Q4.1","pg":234}]},{"id":"M16-4-2","ch":3,"sl":"96, 98–99","tp":"Tahoe vs Reno table","t":"short","q":"Show the TCP congestion window at every round 1–10 for <b>TCP Tahoe</b> and <b>TCP Reno</b>. Initial ssthresh = <b>16</b>. After round 4 a <b>triple duplicate ACK</b> occurs; after round 6 a <b>timeout</b> occurs.","a":"<div class=\"tbl\"><table class=\"mini\"><tr><th>Round</th><th>1</th><th>2</th><th>3</th><th>4</th><th>5</th><th>6</th><th>7</th><th>8</th><th>9</th><th>10</th></tr><tr><td>Tahoe</td><td>1</td><td>2</td><td>4</td><td>8</td><td>1</td><td>2</td><td>1</td><td>2</td><td>3</td><td>4</td></tr><tr><td>Reno</td><td>1</td><td>2</td><td>4</td><td>8</td><td>4</td><td>5</td><td>1</td><td>2</td><td>3</td><td>4</td></tr></table></div>After round 4: ssthresh = 8/2 = <b>4</b>. Tahoe restarts at 1 and slow-starts to the threshold; Reno halves to 4 and grows linearly.<br>After round 6 (timeout): Tahoe ssthresh = 2/2 = 1, Reno ssthresh = 5/2 ≈ 2; both restart at 1, then grow linearly once at/above ssthresh.","e":"Chapter 3, slide 96: Reno halves cwnd on triple duplicate ACK; Tahoe (and any timeout) cuts cwnd to 1 MSS. Slide 99: ssthresh = cwnd/2 at each loss; exponential growth below ssthresh, linear above it.","from":[{"s":"M16","qn":"Q4.2","pg":235}]},{"id":"BQ21-1","ch":3,"sl":"66","tp":"TCP seq numbers — next segment","t":"short","q":"Host A and B are communicating over a TCP connection, and Host B has already received from A all bytes up through byte 6500. A now sends two segments to B back-to-back. The first segment has sequence number 6501 and contains 200 bytes of data. The second contains 400 bytes of data. What is the sequence number of the second segment?","a":"<b>6701</b>","e":"Chapter 3, slide 66: the sequence number is the byte-stream number of the first byte in the segment's data. The first segment carries bytes 6501–6700, so the second starts at 6501 + 200 = <b>6701</b> (which is also the ACK number B sends after receiving the first segment).","from":[{"s":"BQ21","qn":"Q1","pg":10}]},{"id":"BQ21-2","ch":3,"sl":"66","tp":"TCP seq numbers — data in segment","t":"short","q":"Suppose Host A sends two TCP segments back to back to Host B over a TCP connection. The first segment has sequence number 90; the second has sequence number 110. How much data is in the first segment?","a":"<b>20 bytes</b> (110 − 90)","e":"Chapter 3, slide 66: consecutive segments are numbered by bytes, so the second segment's sequence number = first seq # + bytes in the first segment → 110 − 90 = 20 bytes.","from":[{"s":"BQ21","qn":"Q2","pg":10}]},{"id":"BQ21-4","ch":3,"sl":"66","tp":"TCP seq/ack — payload length","t":"short","q":"Host A sends a TCP segment (Sequence number = 76, Acknowledgment number = 120) to Host B. Then, Host B responds with a TCP segment (Sequence number = 120, Acknowledgment number = 91). How long is the payload of the first TCP segment?","a":"<b>15 bytes</b> (91 − 76)","e":"Chapter 3, slide 66: B's ACK number is the next byte it expects from A. A's segment started at byte 76 and B now expects byte 91, so the segment carried 91 − 76 = 15 bytes.","from":[{"s":"BQ21","qn":"Q4","pg":11}]},{"id":"BQ21-5","ch":3,"sl":"45–46","tp":"rdt3.0 sender — duplicate ACK","t":"short","q":"For an rdt 3.0 sender, what will be performed when receiving an unexpected (duplicate) ACK or a corrupted ACK?","a":"<b>No action</b> — the sender ignores it and keeps waiting; it retransmits only when its timer expires.","e":"Chapter 3, slides 45–46 (rdt3.0 sender FSM): in the \"wait for ACK\" state, if the received packet is corrupt or is an ACK with the wrong sequence number, the action is Λ (do nothing). Only a timeout triggers retransmission (udt_send(sndpkt), start_timer).","from":[{"s":"BQ21","qn":"Q5","pg":11}]},{"id":"BQ21-6","ch":3,"sl":"74–77","tp":"TCP receive window changes","t":"tf","q":"The size of the TCP RcvWindow never changes throughout the duration of the connection.","a":1,"e":"Chapter 3, slides 74–77 (TCP flow control): the receiver advertises its free buffer space (rwnd) in every segment; rwnd changes as data arrives and as the application reads data from the buffer. So the statement is <b>False</b>.","from":[{"s":"BQ21","qn":"Q6","pg":11}]},{"id":"BQ21-7","ch":3,"sl":"43–44","tp":"Purpose of sequence numbers","t":"short","q":"The sequence number implemented in most reliable data transfer protocols is used to: ______","a":"<b>Handle (detect) duplicate packets.</b>","e":"Chapter 3, slides 43–44: retransmissions create possible duplicates, so the sender adds a sequence number to each packet and the receiver discards duplicates. (Loss is detected with timers/ACKs, not with the sequence number alone.)","from":[{"s":"BQ21","qn":"Q7","pg":11}]},{"id":"BQ21-8","ch":3,"sl":"96–97","tp":"Reno after triple duplicate ACK","t":"short","q":"After a loss event is detected by a triple duplicate ACK, TCP Reno ______.","a":"<b>Enters a fast recovery phase</b> — cwnd is cut in half (not to 1) and ssthresh = cwnd/2.","e":"Chapter 3, slide 96: in TCP Reno the sending rate is cut in half on loss detected by triple duplicate ACK (TCP Tahoe cuts to 1 MSS). Slide 97 (TCP congestion control details, FSM): duplicate ACK count == 3 → fast recovery state.","from":[{"s":"BQ21","qn":"Q8","pg":12}]},{"id":"BQ21-10","ch":3,"sl":"74–77","tp":"Unacked bytes ≤ receive buffer","t":"tf","q":"Suppose Host A is sending Host B a large file over a TCP connection. The number of unacknowledged bytes that A sends cannot exceed the size of the receive buffer.","a":0,"e":"Chapter 3, slides 74–77: with flow control the sender limits the amount of unACKed (\"in-flight\") data to the receiver's rwnd value, and rwnd can never be larger than the receive buffer (RcvBuffer). So the statement is <b>True</b>.","from":[{"s":"BQ21","qn":"Q10","pg":12}]},{"id":"F15-1-4","ch":3,"sl":"54–55","tp":"GBN properties","t":"mcq","q":"Which of the following is correct for the GBN pipelined protocol?","o":["Receiver sends individual ACKs","Sender has a timer for the oldest packet","Sender window contains acknowledged packets","Receiver window contains out-of-order packets"],"a":1,"e":"Chapter 3, slide 54 (GBN sender): cumulative ACK; <b>timer for the oldest in-flight packet</b>; the window holds sent-but-unACKed and usable packets. Slide 55: the GBN receiver discards (doesn't buffer) out-of-order packets. Individual ACKs and buffered out-of-order packets are Selective Repeat (slide 57).","from":[{"s":"F15","qn":"Q1.4","pg":223}]},{"id":"F15-1-5","ch":3,"sl":"26, 30–31","tp":"UDP characteristic: checksum","t":"mcq","q":"UDP has which of the following characteristics?","o":["Three-way handshake for connection establishment.","Connection state at the server.","Regulated send rate.","Checksum for error detection."],"a":3,"e":"Chapter 3, slide 26: UDP has no connection establishment, no connection state at sender/receiver, and no congestion control (unregulated rate). Slides 30–31: the UDP header has a checksum for error detection.","from":[{"s":"F15","qn":"Q1.5","pg":223}]},{"id":"F15-3-1","ch":3,"sl":"66, 83","tp":"Handshake seq/ack values","t":"short","q":"TCP 3-way handshake between Host A and Host B:<br>A → B: Seq = 101<br>B → A: Seq = 222, ACK = <b>[A]</b><br>A → B: Seq = <b>[B]</b>, ACK = <b>[C]</b><br>Fill in A, B and C.","img":"F15-3-1.jpg","a":"A = <b>102</b> · B = <b>102</b> · C = <b>223</b>","e":"Chapter 3, slide 83: SYN(Seq = x) → SYNACK(Seq = y, ACKnum = x+1) → ACK(ACKnum = y+1). The SYN consumes one sequence number, so A's next seq is x+1 = 102 and B acks 101+1 = 102; A acks B's SYN with 222+1 = 223.","from":[{"s":"F15","qn":"Q3.1","pg":225},{"s":"M14","qn":"Q4.2","pg":256}]},{"id":"F15-3-2","ch":3,"sl":"96–99","tp":"Read a TCP window graph (events 1–6)","t":"short","q":"Consider the TCP window-size graph (window in bytes vs time): it rises exponentially to <b>200</b> (event 1), drops to ≈0, rises exponentially then linearly (event 4 at the bend) to <b>500</b> (event 2), drops to ≈0, rises exponentially (event 5) then linearly to event 3, drops by half and continues linearly (event 6).<br>a. What happens at events 1, 2 and 3?<br>b. What is the window size (threshold) at event 4?<br>c. What is TCP doing at events 5 and 6?","img":"F15-3-2.jpg","a":"a. Event 1: loss detected by <b>timeout</b> (window → ~0/1 MSS). Event 2: loss by <b>timeout</b>. Event 3: loss by <b>triple duplicate ACK</b> (window only halved).<br>b. ssthresh = 200 / 2 = <b>100</b> — growth turns linear there.<br>c. Event 5: <b>slow start</b> (exponential growth). Event 6: after the halving, linear growth — the key calls it <b>fast recovery</b>, then it continues as congestion avoidance.","e":"Chapter 3, slide 96: timeout → cwnd = 1 MSS (TCP Tahoe behaviour); triple duplicate ACK → cwnd cut in half (Reno). Slides 98–99: slow start grows exponentially until cwnd reaches ssthresh = half the window at the last loss, then grows linearly. Slide 97: triple duplicate ACK enters fast recovery.","from":[{"s":"F15","qn":"Q3.2","pg":225}]},{"id":"F14-1-7","ch":3,"sl":"20","tp":"TCP socket identifiers","t":"mcq","q":"A TCP socket is identified by:","o":["source IP address and source port number","destination IP address and destination port number","source IP address and destination port number","a and b"],"a":3,"e":"Chapter 3, slide 20: the 4-tuple — source IP + source port <i>and</i> destination IP + destination port.","from":[{"s":"F14","qn":"Q1.7","pg":200},{"s":"M15","qn":"Q1.3","pg":258}]},{"id":"F14-1-8","ch":3,"sl":"45–46","tp":"rdt3.0 retransmits on timeout","t":"mcq","q":"In rdt 3.0, the sender retransmits a packet when:","o":["it receives a duplicate ACK","it receives a corrupted ACK","timeout occurs","All of the above"],"a":2,"e":"Chapter 3, slides 45–46 (rdt3.0 sender FSM): a corrupt or wrong-numbered ACK causes no action; only a <b>timeout</b> triggers udt_send(sndpkt) and restarting the timer.","from":[{"s":"F14","qn":"Q1.8","pg":200}]},{"id":"F14-1-9","ch":3,"sl":"83","tp":"First two handshake segments","t":"mcq","q":"In the TCP handshaking phase, the type of the first and second segments sent is:","o":["RST","SYN","FIN","None of the above"],"a":1,"e":"Chapter 3, slide 83: 1st = SYN (SYNbit=1); 2nd = SYNACK (SYNbit=1, ACKbit=1). Both have the SYN bit set.","from":[{"s":"F14","qn":"Q1.9","pg":200}]},{"id":"F14-2-3","ch":3,"sl":"55, 57, 69","tp":"Out-of-order: TCP vs GBN vs SR","t":"short","q":"Host A received one segment from Host B containing bytes <b>0–465</b> and another containing bytes <b>800–900</b>; the second segment (bytes 466–799) hasn't arrived, so the third arrived out of order. For TCP, GBN and SR, what is done with the out-of-order segment (keep/discard) and which ACK is sent? (For GBN and SR, number the segments 0, 1, 2.)","a":"<div class=\"tbl\"><table class=\"mini\"><tr><th>Protocol</th><th>Action</th><th>ACK</th></tr><tr><td>TCP</td><td>Keep (buffer)</td><td>ACK 466 (next byte expected)</td></tr><tr><td>GBN</td><td>Discard</td><td>ACK 0 (last in-order packet)</td></tr><tr><td>Selective Repeat</td><td>Keep (buffer)</td><td>ACK 2 (that packet itself)</td></tr></table></div>","e":"Chapter 3, slide 69: TCP receiver — out-of-order segment → immediately send a duplicate ACK for the next expected byte (TCP buffers it in practice). Slide 55: GBN receiver discards out-of-order packets and re-ACKs the highest in-order seq #. Slide 57: SR buffers out-of-order packets and individually ACKs each.","from":[{"s":"F14","qn":"Q2.3","pg":201}]},{"id":"F14-2-4","ch":3,"sl":"96, 98–99","tp":"Reno graph: ssthresh 32/21","t":"short","q":"For the TCP Reno graph (cwnd: 1, 2, 4, 8, 16, 32 at round 6, then +1 per round to 42 at round 16; drops to 24 at round 17 and grows to 29 at round 22; drops to 1 at round 23 and grows 2, 4, 8):<br>a. Initial value of ssthresh?<br>b. After round 16, is the loss detected by triple duplicate ACK or timeout?<br>c. ssthresh at round 18?<br>d. cwnd at round 17?<br>e. After round 22, triple duplicate ACK or timeout?","img":"F14-2-4.jpg","a":"a. <b>32</b> — exponential growth stops at 32 and linear growth starts (the printed key says 33; textbook versions of this graph give 32).<br>b. <b>Triple duplicate ACK</b> — cwnd is cut to about half, not to 1.<br>c. ssthresh = 42 / 2 = <b>21</b><br>d. Reno fast recovery: cwnd = ssthresh + 3 = <b>24</b><br>e. <b>Timeout</b> — cwnd drops to 1.","e":"Chapter 3, slide 99: the switch from exponential to linear growth happens at ssthresh; on loss ssthresh = cwnd/2. Slide 96: triple duplicate ACK → cwnd halved (Reno); timeout → cwnd = 1 MSS. Slide 97 (FSM): on entering fast recovery, cwnd = ssthresh + 3 MSS.","from":[{"s":"F14","qn":"Q2.4","pg":202}]},{"id":"F13-1-1","ch":3,"sl":"25","tp":"DNS runs over UDP","t":"mcq","q":"Which of the following higher-level protocols typically operates on top of UDP?","o":["SMTP","DNS","FTP","All of above"],"a":1,"e":"Chapter 3, slide 25 (UDP use): DNS, SNMP, HTTP/3, streaming multimedia. SMTP and FTP use TCP (Chapter 2, slide 15).","from":[{"s":"F13","qn":"Q1(a).1","pg":208}]},{"id":"F13-1-2","ch":3,"sl":"74–77","tp":"Advertised window = flow control","t":"mcq","q":"In TCP, the receiver advertises its window size in order to prevent the transmitter from overrunning the receiver's buffer. This mechanism is called ______.","o":["Flow control","Congestion control","Routing control","Dynamic packet management"],"a":0,"e":"Chapter 3, slides 74–77: TCP receiver \"advertises\" free buffer space in the rwnd field of the TCP header; the sender limits unACKed data to rwnd — flow control.","from":[{"s":"F13","qn":"Q1(a).2","pg":208}]},{"id":"F13-1-6","ch":3,"sl":"85","tp":"Closing a TCP connection","t":"mcq","q":"With TCP client-server connectivity, disconnection from the session is achieved:","o":["When the client sends a FIN to the server and the server returns an ACK.","When the client sends a FIN to the server, followed by the server's FIN.","When the client sends a FIN, the server returns an ACK, then the server sends a FIN and the client returns an ACK.","None of these"],"a":2,"e":"Chapter 3, slide 85 (Closing a TCP connection): client and server each close their side — send a TCP segment with FIN bit = 1 and respond to the received FIN with an ACK (on receiving FIN, the ACK can be combined with own FIN). Both directions must be closed.","from":[{"s":"F13","qn":"Q1(a).6","pg":208}]},{"id":"F13-5","ch":3,"sl":"54–56","tp":"Find the GBN mistake","t":"short","q":"GBN scenario: the sender wants to send packets 0–4 with window size N = 4. pkt2 is corrupted (receiver re-sends ack1 for pkt2, pkt3, pkt4). In the figure the sender, on receiving the duplicate ack1, <b>immediately sends pkt2</b>, then later pkt2 times out.<br>i. What is the mistake in the figure? Why?<br>ii. Correct the mistake and complete the scenario.","img":"F13-5.jpg","a":"i. The sender <b>re-sends pkt2 as soon as it gets the duplicate ack1</b>. GBN ignores duplicate ACKs and only retransmits when the <b>timer for pkt2 expires</b>.<br>ii. Sender gets ack0 → window [1 2 3 4], sends pkt4; gets ack1 → window [2 3 4 5]; ignores the duplicate ack1s. At the <b>pkt2 timeout</b> it resends <b>pkt2, pkt3, pkt4</b>. Receiver accepts them in order and sends ack2, ack3, ack4; the sender window slides to [3 4 5 6], [4 5 6 7], [5 6 7 8].","e":"Chapter 3, slide 54 (GBN sender): a timer for the oldest in-flight packet; timeout(n) → retransmit packet n and all higher seq # packets in the window. Slide 55 (GBN receiver): discard out-of-order packets and re-ACK the highest in-order seq #. Slide 56 shows the correct version (ignore duplicate ACK, wait for pkt 2 timeout).","from":[{"s":"F13","qn":"Q5 a","pg":213}]},{"id":"M15-1-4","ch":3,"sl":"96","tp":"Tahoe → 1 MSS on any loss","t":"mcq","q":"TCP Tahoe sets cwnd to 1 MSS when ______.","o":["a timeout occurs or three duplicate ACKs are received","three duplicate ACKs are received only","a timeout occurs or three NACKs are received","a timeout occurs only"],"a":0,"e":"Chapter 3, slide 96: TCP Tahoe cuts cwnd to 1 MSS on every loss event (timeout or triple duplicate ACK); TCP Reno only halves cwnd on a triple duplicate ACK.","from":[{"s":"M15","qn":"Q1.4","pg":258}]},{"id":"M15-1-6","ch":3,"sl":"75–77","tp":"rwnd depends on receiver buffer","t":"mcq","q":"In TCP, the flow-control window (rwnd) is adjusted based on ______.","o":["Maximum Segment Size (MSS)","Congestion window","Receiver buffer","ssthresh"],"a":2,"e":"Chapter 3, slides 75–77: rwnd = free buffer space at the receiver (RcvBuffer minus buffered data).","from":[{"s":"M15","qn":"Q1.6","pg":259}]},{"id":"M15-1-9","ch":3,"sl":"49–51","tp":"Stop-and-wait = window of 1","t":"mcq","q":"Stop-and-Wait flow control is a special case of the sliding-window scheme when the window size equals:","o":["0","1","∞","2"],"a":1,"e":"Chapter 3, slides 49–51: stop-and-wait allows only one unACKed packet in flight — a window of 1. Pipelined protocols (slide 52) allow more.","from":[{"s":"M15","qn":"Q1.9","pg":259}]},{"id":"M15-1-10","ch":3,"sl":"67","tp":"Piggybacking","t":"tf","q":"Piggybacking is the ability to send data together with the acknowledgement packet in a full-duplex manner.","a":0,"e":"Chapter 3, slide 67 (telnet example): Host B ACKs receipt of 'C' and echoes back 'C' in the same segment — the ACK rides on a data segment. TCP is full duplex (slide 64). <b>True</b>.","from":[{"s":"M15","qn":"Q1.10","pg":259}]},{"id":"M15-1-11","ch":3,"sl":"57–59","tp":"SR needs sender buffer","t":"tf","q":"The selective-repeat (selective reject) error-control scheme requires a buffer at the transmitter end.","a":0,"e":"Chapter 3, slides 57–59: the SR sender keeps every unACKed packet (each with its own timer) so it can resend it individually; the receiver also buffers out-of-order packets. <b>True</b>.","from":[{"s":"M15","qn":"Q1.11","pg":259}]},{"id":"M15-1-12","ch":3,"sl":"55","tp":"GBN receiver doesn't buffer","t":"tf","q":"The Go-Back-N error-control scheme requires a buffer at the receiver end.","a":1,"e":"Chapter 3, slide 55 (GBN receiver): on receipt of an out-of-order packet, discard (don't buffer) it; the receiver only remembers rcv_base. <b>False</b>.","from":[{"s":"M15","qn":"Q1.12","pg":259}]},{"id":"M15-2-1","ch":3,"sl":"49, 53","tp":"GBN window for 100% utilization","t":"short","q":"In a Go-Back-N system the transmission delay of one packet is <b>0.2 RTT</b>. What window size gives (theoretically) 100% utilization?","a":"U = N·(L/R) / (RTT + L/R) = N × 0.2 / 1.2. Setting U = 1 → N = 1.2 / 0.2 = <b>6</b> packets.","e":"Chapter 3, slide 49: U<sub>sender</sub> = (L/R) / (RTT + L/R) for stop-and-wait. Slide 53: with N packets pipelined, U = N·(L/R) / (RTT + L/R). The sender is busy all the time once the first ACK arrives before it runs out of window.","from":[{"s":"M15","qn":"Q2.1","pg":260}]},{"id":"M15-3","ch":3,"sl":"66–67, 83","tp":"Find W, X, Y, Z (handshake + HTTP)","t":"short","q":"TCP scenario:<br>A → B: SYN, Seq 0<br>B → A: SYN+ACK, Seq 0, ACK 1<br>A → B: ACK, Seq 1, ACK <b>W</b><br>A → B: HTTP request, Seq 1, ACK 1, Data <b>X</b> bytes<br>B → A: HTTP reply, Seq 1, ACK 101, Data 200 bytes<br>A → B: HTTP request, Seq <b>Y</b>, ACK 201, Data 50 bytes<br>B → A: HTTP reply, Seq 201, ACK <b>Z</b>, Data 1000 bytes<br>Find W, X, Y and Z.","img":"M15-3.jpg","a":"W = <b>1</b> (acks B's SYN, seq 0)<br>X = <b>100</b> (B acks 101 = 1 + X)<br>Y = <b>101</b><br>Z = <b>151</b> (101 + 50)","e":"Chapter 3, slide 83: the SYN uses one sequence number, so the ACK of a SYN with seq 0 is 1. Slide 66: the ACK # is the next byte expected; seq numbers advance by the bytes of data sent. A pure ACK carries no data, so A's request still starts at seq 1.","from":[{"s":"M15","qn":"Q3","pg":261}]},{"id":"M14-1-5","ch":3,"sl":"64, 68–72","tp":"TCP = hybrid of GBN and SR","t":"mcq","q":"TCP's reliability mechanism is categorized as:","o":["rdt 3.0 (stop and wait)","GBN","SR (Selective Repeat)","hybrid of GBN and SR"],"a":3,"e":"Chapter 3, slides 64 and 68–72: TCP is pipelined with <b>cumulative ACKs</b> and a single timer for the oldest unACKed segment (GBN-like), but on timeout it retransmits only the one segment that caused it and the receiver can buffer out-of-order segments (SR-like).","from":[{"s":"M14","qn":"Q1.5","pg":251}]},{"id":"M14-1-6","ch":3,"sl":"15","tp":"Multiplexing definition","t":"mcq","q":"Gathering data from different sockets, creating segments, and passing the segments to the network layer is called:","o":["Multiplexing","Demultiplexing","Host-to-host delivery","Process-to-process delivery"],"a":0,"e":"Chapter 3, slide 15: multiplexing at sender — handle data from multiple sockets, add transport header (later used for demultiplexing).","from":[{"s":"M14","qn":"Q1.6","pg":252}]},{"id":"M14-1-7","ch":3,"sl":"43","tp":"rdt 2.1 additions","t":"mcq","q":"New mechanism(s) in rdt 2.1 beyond rdt 2.0:","o":["Error detection for corrupted ACK/NAK","Error detection for corrupted packets","Sequence number for each packet","a and c"],"a":3,"e":"Chapter 3, slide 43 (How to recover from errors?): rdt2.0 uses checksum + ACK/NAK + retransmission. What if the ACK/NAK is corrupted? The sender retransmits, which can create duplicates — so rdt2.1 adds a <b>checksum on ACK/NAK</b> and a <b>sequence number</b> on each packet so the receiver can discard duplicates.","from":[{"s":"M14","qn":"Q1.7","pg":252}]},{"id":"M14-1-8","ch":3,"sl":"44","tp":"Countdown timer = rdt 3.0","t":"mcq","q":"The countdown timer is the mechanism of:","o":["rdt 2.0","rdt 2.1","rdt 2.2","rdt 3.0"],"a":3,"e":"Chapter 3, slide 44: when the underlying channel can also <b>lose</b> packets, the sender waits a \"reasonable\" time for an ACK, using a countdown timer, and retransmits if none arrives — rdt3.0.","from":[{"s":"M14","qn":"Q1.8","pg":252}]},{"id":"M14-1-10","ch":3,"sl":"74–77","tp":"Unacked bytes ≤ receive buffer (MCQ)","t":"mcq","q":"Host A sends a large file to Host B over TCP. The number of unacknowledged bytes that A sends cannot exceed the size of the:","o":["Receiver buffer","Receiver window","Sender buffer","Sender window"],"a":0,"e":"Chapter 3, slides 74–77: the sender limits unACKed data to rwnd, and rwnd is at most the receiver's buffer RcvBuffer — so in-flight data can never exceed the receive buffer. (rwnd changes over time; the buffer size is the fixed upper limit the textbook question uses.)","from":[{"s":"M14","qn":"Q1.10","pg":252}]},{"id":"M14-3-1","ch":3,"sl":"32–33","tp":"8-bit checksum of three bytes","t":"short","q":"Compute the 8-bit checksum of the three bytes <code>00100011</code>, <code>01001110</code>, <code>11010100</code>. (UDP uses 16-bit words; here use 8-bit sums.)","a":"<pre>  00100011\n+ 01001110\n= 01110001\n+ 11010100\n= 1 01000101  (carry out)\nwraparound: 01000101 + 1 = 01000110\nchecksum = 1s complement = 10111001</pre>Checksum = <b>10111001</b>","e":"Chapter 3, slides 32–33: one's-complement sum with wraparound of carries, then invert all bits.","from":[{"s":"M14","qn":"Q3.1","pg":254}]},{"id":"M14-3-2","ch":3,"sl":"45–48","tp":"Find the rdt3.0 mistake","t":"short","q":"In this rdt3.0 scenario: pkt1's timer expires and pkt1 is resent; then the (delayed) ack1 arrives and the sender sends pkt0; then the second ack1 arrives and the sender <b>immediately resends pkt0</b>. What is the error, and why?","img":"M14-3-2.jpg","a":"The error is <b>resending pkt0 immediately after receiving the unexpected (duplicate) ack1</b>. In rdt3.0 the sender does nothing when it receives a duplicate or unexpected ACK; it retransmits only when its <b>timer expires</b>.","e":"Chapter 3, slides 45–46 (rdt3.0 sender FSM): in \"wait for ACK\", a corrupt ACK or an ACK with the wrong number → Λ (no action); timeout → retransmit. Slide 48 shows the correct premature-timeout behaviour: the duplicate ACK is ignored.","from":[{"s":"M14","qn":"Q3.2","pg":254}]},{"id":"M14-3-3","ch":3,"sl":"49, 52–53, 57","tp":"Weakness and fix of rdt3.0 / GBN","t":"short","q":"What is the problem (disadvantage) of each protocol, and what is the solution?<br>1. rdt 3.0<br>2. GBN","a":"1. rdt 3.0: <b>low utilization / low throughput</b> (stop-and-wait: only one packet in flight). Solution: <b>pipelined protocols</b> (GBN, SR).<br>2. GBN: <b>wastes bandwidth with unnecessary retransmissions</b> — one loss makes the sender resend the whole window, and the receiver discards correctly received out-of-order packets. Solution: <b>Selective Repeat</b> (individual ACKs, retransmit only lost packets, buffer out-of-order packets).","e":"Chapter 3, slide 49: rdt3.0's U<sub>sender</sub> = 0.00027 — performance stinks. Slides 52–53: pipelining increases utilization. Slide 54: GBN timeout retransmits all higher packets in the window. Slide 57: SR retransmits only individual unACKed packets.","from":[{"s":"M14","qn":"Q3.3","pg":255}]},{"id":"M14-4-1","ch":3,"sl":"20, 66, 69","tp":"Seq #, ports and ACK numbers","t":"short","q":"Host B has received from A all bytes up through byte <b>126</b>. Host A sends two segments back-to-back with <b>80</b> and <b>40</b> bytes of data. The first segment has seq # 127, source port 302, destination port 80. B sends an ACK for every segment it receives.<br>a. In the second segment, what are the seq #, source port and destination port?<br>b. If the first segment arrives first, what are the ACK number, source port and destination port in its ACK?<br>c. If the second segment arrives first, what is the ACK number in the ACK for that first-arriving segment?","a":"a. Seq = <b>207</b>, source port <b>302</b>, destination port <b>80</b>.<br>b. ACK = <b>207</b>, source port <b>80</b>, destination port <b>302</b> (ports swap for the reply).<br>c. ACK = <b>127</b> — B still expects byte 127 (duplicate ACK).","e":"Chapter 3, slide 66: seq # = first byte; 127 + 80 = 207. ACK # = next byte expected. Slide 20: a reply segment swaps source and destination ports. Slide 69: an out-of-order segment triggers a duplicate ACK for the next expected byte.","from":[{"s":"M14","qn":"Q4.1","pg":255}]}]};
